export const y3v4Chapters: Record<number, string> = {
    "1": "<div><p>I always had a feeling that someday it would come to this, that sooner or later, I wouldn’t be able to keep up with this school’s system.</p></div>\n<div><p>I sucked at studying.</p></div>\n<div><p>I wasn’t exactly good at working with other people either.</p></div>\n<div><p>The only thing I could say I was good at… was fighting.</p></div>\n<div><p>That’s why somewhere deep down, I had already sensed it, that when the time came, I’d be the one discarded.</p></div>\n<div><p>Ryūen, obviously, and even Shiina and Katsuragi, were indispensable to the class.</p></div>\n<div><p>But unlike them, I’d always been standing on the edge of the cliff.</p></div>\n<div><p>That was why I thought I’d be fine even if I got expelled.</p></div>\n<div><p>That was what I’d believed all this time.</p></div>\n<div><p>That I had no regrets left behind.</p></div>\n<div><p>At least, that was what I thought…</p></div>\n<div><p>But now, as I stared at Ayanokōji’s back, I realized there was still one thing left undone.</p></div>\n<div><p>If I was getting expelled anyway, then before I disappeared, I wanted to land at least one solid punch on Ayanokōji, no matter what.<span></span></p></div>\n<div><p>Staring at his infuriating back, I steeled my resolve.</p></div>\n<div><p><em>A surprise attack?</em></p></div>\n<div><p><em>Feints before the real hit?</em></p></div>\n<div><p>Yeah, I already knew none of that crap would work on this guy.</p></div>\n<div><p>So I’d do it properly.</p></div>\n<div><p>Straight on. Fair and square.</p></div>\n<div><p>I stepped forward with force and closed the distance between us.</p></div>\n<div><p>Ayanokōji turned around.</p></div>\n<div><p>That same unreadable expression on his face.</p></div>\n<div><p>I grabbed him by the collar and drew back my fist.</p></div>\n<div><p>“I’ll accept the expulsion,” I spat. “So let me hit you once before I go.”</p></div>\n<div><p>It was a completely absurd demand.</p></div>\n<div><p>A hopeless shot.</p></div>\n<div><p>I’d fully expected him to refuse, tell me he had no reason to indulge me, and the second he did, I was ready to swing anyway.<span></span></p></div>\n<div><p>But the response I got was the last thing I expected.</p></div>\n<div><p>“I’m the one who decided to have you expelled, after all,” Ayanokōji said evenly. “I suppose I can grant you at least that much.”</p></div>\n<div><p>Hearing that, the corner of my mouth curled upward ever so slightly.</p></div>\n<div><p>“You’ve got some nerve,” I muttered, tightening my grip. “Fine, then. Don’t expect me to hold back.”</p></div>\n<div><p>I won’t hold back.</p></div>\n<div><p>If he thought he could underestimate a woman's strength, he was dead wrong.</p></div>\n<div><p>I was going to knock out one or two of his teeth for sure.</p></div>\n<div><p>Then, putting every last ounce of strength into it, I unleashed the most dead-serious, super-ultra straight punch of my entire life.<span></span></p></div>",
    "2": "<div><p>Mashima-sensei’s voice rang across the shoreline with quiet finality.</p></div>\n<div><p>“Effective immediately, we will now commence the Uninhabited Island Special Exam.”</p></div>\n<div><p>The students, already exhausted from the survival game, were still struggling to process what they had just heard. Yet Mashima-sensei showed no intention of waiting for anyone to catch up. As though brushing aside the confusion spreading through the crowd, he continued his explanation without hesitation.</p></div>\n<div><p>Just when everyone thought the island exam was finally over, another special exam was suddenly set into motion.</p></div>\n<div><p><em>So the Survival Game conducted earlier was merely the prelude, and this was the second phase?</em></p></div>\n<div><p>Of course, there was always the possibility that this next phase was only the midpoint of an even larger ordeal waiting beyond it. But considering the condition some students were already in, pushing them through three consecutive stages would be unrealistic.</p></div>\n<div><p>Either way, it was a harsh situation.</p></div>\n<div><p>Meanwhile, the sun was already beginning to sink toward the horizon. It was close to five in the evening.</p></div>\n<div><p>The third-years had weathered countless special exams by now and developed a tolerance for the school’s unpredictability. Even so, they couldn’t hide their confusion. This was different from anything they’d faced before.</p></div>\n<div><p>“Damn, they’re seriously going to start another special exam right now?” Hashimoto muttered beside me with a strained half-laugh. “Yamamura and Shiraishi are already hanging by a thread.”</p></div>\n<div><p>His tone carried a trace of sympathy, but the school showed no sign of reconsidering.</p></div>\n<div><p>“The special exam commencing now,” Mashima-sensei continued, “will consist of ten groups, each containing sixteen students. Every group will be assigned one adult supervisor who will provide instructions as necessary. You are expected to obey your supervisor at all times. As you are already aware, due to the number of students expelled thus far, some groups will inevitably begin with fewer members than others. However, adjustments have been made to ensure that disparities in group size will not create any advantages or disadvantages.”</p></div>\n<div><p>Sixteen students per group.</p></div>\n<div><p>If that was the base structure, then this was unlikely to be a straightforward class-versus-class exam.</p></div>\n<div><p>As though confirming that very suspicion, Mashima-sensei’s next words peeled back another layer of the situation.</p></div>\n<div><p>“The bottled drinks you were instructed to take upon disembarking may have struck some of you as unusual. Those bottles are the key to determining your groups.”</p></div>\n<div><p>At once, students began glancing down at the plastic bottles in their hands.</p></div>\n<div><p>“There are five different label colors,” he explained. “Red, blue, green, yellow, and purple. Enough had been prepared for each class, with adjustments and guidance carried out to ensure everyone received one.”</p></div>\n<div><p>I lowered my gaze to the mineral water bottle I’d been carrying since leaving the ship, it bore a blue label.</p></div>\n<div><p>Hashimoto, standing beside me, held purple.</p></div>\n<div><p>At the very least, it confirmed one thing: the two of us wouldn’t end up in the same group.</p></div>\n<div><p>However, there were only five colors. That alone wasn’t enough to divide everyone into ten separate groups.</p></div>\n<div><p>Which meant there had to be another layer hidden somewhere in the selection process.</p></div>\n<div><p>Removing the label would only create litter. On an island like this, a stray gust of wind could easily carry it straight into the ocean. The school wouldn’t use something so careless.</p></div>\n<div><p>If they wanted a cleaner, simpler way to add another randomizer, there was an obvious answer.</p></div>\n<div><p>The cap.</p></div>\n<div><p>Without a word, I twisted the bottle open, removed the cap, and checked the underside.</p></div>\n<div><p>A second later, Hashimoto noticed what I was doing and quietly checked his own as well.</p></div>\n<div><p>“There’s nothing on my cap,” I said quietly. “What about yours?”</p></div>\n<div><p>“Mine’s marked,” Hashimoto replied immediately. “One black line.”</p></div>\n<div><p>Right on cue, Mashima-sensei resumed speaking over the microphone.</p></div>\n<div><p>“I would like everyone to remove the caps from your bottles and examine the underside carefully.”</p></div>\n<div><p>Around us, the sound of twisting plastic caps spread through the crowd in uneven bursts.</p></div>\n<div><p>“There are two types of caps prepared for this exam,” he continued. “Plain caps with no markings, and caps marked with a single black line. Students carrying red labels with unmarked caps will belong to Group 1, and students carrying red labels with marked caps will belong to Group 2. That will determine your assigned groups.”</p></div>\n<div><p>He proceeded through the remaining combinations without pause.</p></div>\n<div><p>Blue labels corresponded to Groups 3 and 4. Green to 5 and 6. Yellow to 7 and 8. And purple to 9 and 10.</p></div>\n<div><p>It was also explained that Group 10 alone would begin with fewer than sixteen members.</p></div>\n<div><p>Hashimoto glanced at his purple label again.</p></div>\n<div><p>“So I got stuck in the smaller Group 10, huh? And you’re Group 3…” He slowly scanned the students surrounding us. “Still, there’s no way in hell to tell who ended up where from here.”</p></div>\n<div><p>Even if someone managed to identify the color of another student’s bottle label from a distance, spotting the tiny black line hidden beneath a bottle cap was another matter entirely. Until everyone physically gathered with their assigned groups, nobody could know for certain who their teammates would be.</p></div>\n<div><p>Which was probably intentional.</p></div>\n<div><p>If group assignments had been too easy to identify, students might’ve attempted to exchange bottles beforehand. The school had clearly accounted for that possibility from the start.</p></div>\n<div><p>Still, the identities of our future teammates were something we would inevitably learn soon enough. Speculating now was pointless. More important was understanding the rules of the exam itself.</p></div>\n<div><p>In fact, Mashima-sensei and the others were already proceeding to the next stage without wasting time.</p></div>\n<div><p>“Now then, I will explain the details of this special exam. To assist your understanding, documents summarizing the rules and structure will now be distributed. Read through them carefully.”</p></div>\n<div><p>After a brief pause, teachers moved through the students, handing out the materials one by one.</p></div>\n<div><p>The multi-page document was bundled together with detailed maps of the island. Small card rings had been fastened through the corners, likely to prevent them from being blown away by the wind.</p></div>\n<div><p>As the documents reached my hands, Mashima-sensei resumed speaking.</p></div>\n<div><p>“You will divide into your assigned groups and undertake various challenges throughout the island. Based on your results, you will earn rewards known as ‘tokens.’ Collecting these tokens will form the core objective of the exam. In addition, one student from each class has already been selected by their homeroom teacher to serve as class leader. Although the results of the Survival Game Special Exam have caused provisional changes in class rankings, those standings will remain unofficial until the end of the month. Therefore, for the purposes of this exam, the current class designations will remain unchanged.</p></div>\n<div><p>He paused briefly before reading out the names.</p></div>\n<div><p>“For Class A: Horikita Suzune. For Class B: Ryūen Kakeru. For Class C: Ayanokōji Kiyotaka. And for Class D: Ichinose Honami. These students will serve as the leaders for their respective classes.”</p></div>\n<div><p>As his voice echoed across the shore, I lowered my gaze to the documents in my hands.</p></div>\n<div><hr></div>\n<div><p><strong><em>‘Token Collection Special Exam’</em></strong></p></div>\n<div><p>• <strong>Overview</strong></p></div>\n<div><p>During the course of the four-day, three-night examination, students are required to travel across the island while undertaking various challenges, collect tokens, and ultimately reach the designated goal.</p></div>\n<div><p>• <strong>Group Goal Rewards</strong></p></div>\n<div><p>Token multipliers and Private Point rewards will be distributed according to the order in which groups reach the goal.</p></div>\n<div><p>• <em>Note:</em></p></div>\n<div><p><em>A group’s finishing rank is determined the moment a majority of its members successfully reach the goal.</em></p></div>\n<div><p>• <strong>Group Rank</strong></p></div>\n<div><p>1st Place: 100% Token Multiplier &amp; 100,000 Private Point Reward</p></div>\n<div><p>2nd Place: 95% Token Multiplier &amp;  80,000 Private Point Reward</p></div>\n<div><p>3rd Place: 90% Token Multiplier &amp;  50,000 Private Point Reward</p></div>\n<div><p>4th Place: 85% Token Multiplier &amp;  30,000 Private Point Reward</p></div>\n<div><p>5th Place: 80% Token Multiplier &amp;  20,000 Private Point Reward</p></div>\n<div><p>6th Place or Lower: 75% Token Multiplier &amp;  10,000 Private Point Reward</p></div>\n<div><p>Disqualified Group: 70% Token Multiplier &amp;  No additional reward</p></div>\n<div><p>• <strong>Rewards and Penalties Based on Token Holdings</strong></p></div>\n<div><p>The groups containing each class leader will determine their class’s outcome based on the total number of tokens accumulated.</p></div>\n<div><p>• <strong>Token Holding Rank Result</strong></p></div>\n<div><p>1st Place: Class Points +100</p></div>\n<div><p>2nd Place: Class Points +50</p></div>\n<div><p>3rd Place: Class Points +20</p></div>\n<div><p>4th–9th Place: No Change</p></div>\n<div><p>Last Place: Class Points -50</p></div>\n<div><hr></div>\n<div><p>What mattered most was not simply collecting tokens, but balancing two objectives simultaneously: gathering as many as possible while also reaching the goal quickly enough to preserve a high multiplier.</p></div>\n<div><p>Neither alone would be enough.</p></div>\n<div><p>Mashima-sensei broke the brief silence, resuming his explanation.</p></div>\n<div><p>“As for the private point rewards granted upon reaching the goal, if a group finishes in first place, every student within that group will individually receive 100,000 private points. The second reward, the token multiplier, is tied both to your group’s ranking by token possession and to the individual rewards I will explain shortly. If a group finishes in third place, the total number of tokens used in calculations will be reduced to 90%. Groups ranked 6th or lower will receive only 75%.” He paused briefly before adding, “Any fractional values produced after the multiplier is applied will be rounded upward.”</p></div>\n<div><p>In other words, even if a group accumulated 1,000 tokens through relentless effort over four exhausting days, a poor finishing rank would steadily erode the value of everything they had gathered.</p></div>\n<div><p>The exact conditions for what constituted “reaching the goal” remained unclear for now, but one thing was already obvious. Finishing near the top was non-negotiable.</p></div>\n<div><p>“Up to this point, the rules may have sounded favorable to the students, however, this special exam also contains several major penalties. And… some of them are unavoidable.”</p></div>\n<div><p>I lowered my eyes to the next page of the booklet. The penalties he referred to had already been printed there in orderly text.</p></div>\n<div><hr></div>\n<div><p><strong><em>Penalty List</em></strong></p></div>\n<div><p>• <strong>Lowest Token Holder Expulsion</strong></p></div>\n<div><p>At the conclusion of the exam, the single student across the entire year with the fewest tokens will be expelled.</p></div>\n<div><p>If multiple students are tied for the lowest number of tokens, the student with the lowest Overall Ability Assessment (OAA) score as of June 1st will be selected. If still tied, earlier monthly OAA records will be referenced in order.</p></div>\n<div><p>• <strong>Reaching Zero Tokens</strong></p></div>\n<div><p>If a student’s token count ever reaches zero during the exam, that student will be expelled immediately.</p></div>\n<div><p>However, if the student possesses a Protection Point, they will instead withdraw from the exam and wait aboard the ship.</p></div>\n<div><p>This penalty applies only to the <em>first</em> student whose token count reaches zero.</p></div>\n<div><p>• <strong>Failure to Reach the Goal</strong></p></div>\n<div><p>For every student who fails to reach the goal by the end of the exam, their class will lose 5 Class Points.</p></div>\n<div><p>In addition, regardless of the group’s finishing rank, any student who fails to reach the goal will have their token multiplier reduced to 70%.</p></div>\n<div><p>• <strong>Delayed Goal Completion Penalty</strong></p></div>\n<div><p>Once a majority of a group has reached the goal and the group’s ranking is finalized, every student who still has not reached the goal will continue costing their class 1 Class Point every 30 minutes until they arrive.</p></div>\n<div><p>• <strong>Leaving the Supervisor’s Area</strong><span></span></p></div>\n<div><p>For every hour a student remains outside the area where their assigned supervisor is stationed, that student will lose 1 token.</p></div>\n<div><p>Returning to the designated area resets the timer.</p></div>\n<div><hr></div>\n<div><p>The penalties laid out before us were severe.</p></div>\n<div><p>Unlike ordinary punishments for breaking rules, these weren’t pitfalls students could simply avoid through caution or obedience. Some could potentially be managed, but others were built into the structure of the exam itself, unavoidable by design.</p></div>\n<div><p>Compared to the Survival Game Special Exam, this was a clear step deeper into dangerous territory.</p></div>\n<div><p>“So this is finally the real deal, huh?” Hashimoto muttered beside me under his breath.</p></div>\n<div><p>“It seems so,” I replied quietly.</p></div>\n<div><p>Considering Horikita had most likely shouldered the penalty from the Survival Game Exam, the only student confirmed to still possess a Protection Point was Kōenji. Other classes might still have some in reserve, but intentionally reducing your own tokens to zero just to burn that single expulsion slot would only benefit rival classes more than your allies. No one would willingly make that sacrifice.</p></div>\n<div><p>With the safety net already stripped away following their recent defeat, Class A’s position in particular had become especially unforgiving.</p></div>\n<div><p>Mashima-sensei gave the students a moment to absorb the weight of the penalties before resuming his explanation.</p></div>\n<div><p>“Next, I will explain the details regarding tokens themselves… as well as the individual rewards.”</p></div>\n<div><hr></div>\n<div><p>• <strong>Token Classifications (Front-side and Back-side)</strong></p></div>\n<div><p>Tokens are divided into two distinct classifications: Front-side and Back-side.</p></div>\n<div><p>Tokens earned through verified individual achievements are classified as Front-side. Tokens acquired through all other methods are classified as Back-side.</p></div>\n<div><p>Victory rewards based on token possession will account for the aggregate total, regardless of whether they are Front-side or Back-side.</p></div>\n<div><p>Individual rewards will strictly account for Front-side tokens only.</p></div>\n<div><p>• <strong>Token Transfer Protocols</strong></p></div>\n<div><p>Tokens are fully transferable between students. To initiate a transfer, a specific interface operation must be performed, followed by physical contact between both parties' wristwatches.</p></div>\n<div><p>There are no restrictions on the quantity of tokens transferred, the frequency of transfers, or the intended recipient.</p></div>\n<div><p>Any token utilized in a transfer will permanently convert into a Back-side token and cannot be reverted back to Front-side.</p></div>\n<div><p>A student's token count becomes finalized the exact moment they reach the goal. Beyond this point, any further transfers involving that student are prohibited.</p></div>\n<div><p>• <strong>Token Expenditure</strong></p></div>\n<div><p>Expending 1 Token permits 5 minutes of communication with any student of your choice.</p></div>\n<div><p>Expending 1 Token permits a location check to view the current coordinates of any student of your choice.</p></div>\n<div><hr></div>\n<div><p>The ability to freely transfer tokens at any time seemed likely to play a major role in avoiding certain penalties.</p></div>\n<div><p>A student close to reaching zero could be rescued by allies before expulsion triggered. Likewise, someone at risk of falling to the bottom of the rankings could potentially be saved by pooling resources.</p></div>\n<div><p>At the same time, there was an obvious tradeoff.</p></div>\n<div><p>The moment a token was transferred, it lost its front-side status and became a back-side token permanently, making them ineligible for pursuing individual rewards.</p></div>\n<div><hr></div>\n<div><p><strong><em>Individual Rewards</em></strong></p></div>\n<div><p>• <strong>Special Reward:</strong> The class of the student who accumulates the highest number of Front-side tokens will be awarded 100 Class Points. Additionally, that student will receive 500,000 Private Points. <em>(In the event of a tie for the top position, the rewards will be divided equally among the qualifying students).</em></p></div>\n<div><p>• <strong>General Reward (All Students):</strong> Every student will receive 1,000 Private Points multiplied by their total number of Front-side tokens in possession.</p></div>\n<div><hr></div>\n<div><p>The section regarding the Special Reward was impossible to ignore.</p></div>\n<div><p>100 Class Points.</p></div>\n<div><p>That alone was significant enough to rival the rewards of an entire special exam victory. But there was an important catch. If multiple students tied for the highest number of front-side tokens, the reward would simply be divided among them.</p></div>\n<div><p>In any case, gathering even a single additional token as an individual carried clear advantages for every student involved.</p></div>\n<div><p>By now, the entire structure of the exam had finally come into view, and a measured tension began settling over the crowd.</p></div>\n<div><p>If a group cooperated efficiently, gathered large numbers of tokens, and secured a top finish, then naturally every member of that group stood to gain a huge amount of Private Points. That was the straightforward benefit.</p></div>\n<div><p>But the problem was what happened inside the group itself.</p></div>\n<div><p>If a student from a rival class happened to accumulate an overwhelming number of front-side tokens while working alongside you, they could seize the Special Award for their class instead. And that would effectively create a massive class point gap in favor of a rival class.</p></div>\n<div><p>After that, the explanation shifted toward the new functions added to the wristwatches.</p></div>\n<div><p>“By entering the six-digit passcode assigned to your device,” Mashima-sensei explained, “you may confirm your current token count as well as transfer tokens to others. We will now have everyone operate the system as part of the explanation.”</p></div>\n<div><p>He paused briefly.</p></div>\n<div><p>“However, there is one important precaution. Every student has been provided with at least two tokens at the start of the exam, but the number distributed differs from student to student. Your starting token count is therefore valuable information. I strongly recommend you avoid revealing it to others.”</p></div>\n<div><p>So the starting conditions weren’t equal after all.</p></div>\n<div><p>The wristwatch displays themselves were designed with privacy in mind. Unless someone deliberately stood directly behind another person, or pressed in unnaturally close from the side, stealing a glance at the screen was nearly impossible.</p></div>\n<div><p>Even so, the students took no chances, shielding the screens with their bodies, they cautiously entered passcodes to confirm the initial token counts.</p></div>\n<div><p>I too entered my passcode and the screen lit up.</p></div>\n<div><p><em>11 Tokens: Front-Side</em></p></div>\n<div><p>At first glance, it seemed relatively high.</p></div>\n<div><p>But there was no baseline yet beyond “two or more.” Without additional comparisons, there was no reliable way to judge where the number actually stood.</p></div>\n<div><p>In addition, a send button and receive button for transfers were displayed simultaneously. It seemed token transfers required both parties to activate the appropriate commands before physically touching their wristwatches together.</p></div>\n<div><p>Without speaking, I extended my arm slightly toward Hashimoto, showing him my screen.</p></div>\n<div><p>His eyes widened slightly in surprise as he compared it to his own before turning his watch toward me in return.</p></div>\n<div><p><em>9 Tokens</em></p></div>\n<div><p>Close to mine, but slightly lower.</p></div>\n<div><p>It was hard to believe the distribution was based directly on OAA scores or academic performance. More likely, they were related to the previous exam, not necessarily contribution itself, but survival duration.</p></div>\n<div><p>Yamamura and Shiraishi had endured until the very end of the Survival Game, exhausting themselves more thoroughly than anyone else.</p></div>\n<div><p>Meanwhile, students eliminated early had probably recovered completely by now, entering this exam in a far better condition.</p></div>\n<div><p>Seen that way, the uneven token distribution made sense. A form of insurance. A balancing measure intended to offset the physical disparity between students.</p></div>\n<div><p>Still, it wasn’t something to celebrate unconditionally.</p></div>\n<div><p>Even if others could eventually make educated guesses regarding who had started with a larger number of tokens, concealing that information whenever possible was still the smarter choice.</p></div>\n<div><p>“And finally,” Mashima-sensei continued, “although everyone is currently present, some students may unexpectedly fall ill during the course of the exam. In such cases, the procedures involved are extremely delicate. Be certain to carefully review the relevant section in your documents.”</p></div>\n<div><p>At those words, I lowered my gaze toward the final page.</p></div>\n<div><hr></div>\n<div><p>• <strong>Conditions That Make Continuing the Exam Impossible</strong></p></div>\n<div><p>If a student suffers a sudden illness or serious injury severe enough to prevent them from continuing, they may, in principle, report the situation verbally to a supervisor and request a judgment on whether they are allowed to proceed.</p></div>\n<div><p>If no supervisor is nearby and direct contact is impossible, the student may instead use the emergency request function on their wristwatch.</p></div>\n<div><p>However, the moment a student is officially declared retired from the exam, their token count becomes finalized.</p></div>\n<div><p>As a relief measure, any student may transfer tokens to a retired participant regardless of distance.</p></div>\n<div><p>In addition, a group containing a retired student may still receive an official ranking, but only if every remaining member of that group successfully reaches the goal.</p></div>\n<div><p>Feigning illness, or intentionally concealing a serious injury or medical condition in order to continue participating, is strictly prohibited.</p></div>\n<div><p>If a student is uncertain whether their condition qualifies, they are instructed to consult the school for judgment.</p></div>\n<div><p>If a violation is discovered, an expulsion penalty will be imposed.</p></div>\n<div><hr></div>\n<div><p>In an island exam like this, health issues and injuries were practically inevitable.</p></div>\n<div><p>Because the exam was fundamentally built around maintaining group numbers, the school likely had zero tolerance for students concealing their true condition.</p></div>\n<div><p>If being grouped together with students from other classes puts you at a disadvantage, then naturally people would want to hide any signs of poor health.</p></div>\n<div><p>This rule existed specifically to prevent that from happening.</p></div>\n<div><p>And since faking illness would not work either, it effectively prevented someone like Kōenji from casually abandoning the exam whenever he pleased.</p></div>\n<div><p>“Man, these rules are brutal,” Hashimoto muttered. “So even if you get sick and retire, they still won’t show any mercy, huh?”</p></div>\n<div><p>The relief measures certainly existed. But if a student lacking either ability or social value retired early, there was a very real possibility their class would simply abandon them.</p></div>\n<div><p>On the other hand, someone like Ichinose would almost certainly be saved without hesitation. Her classmates would willingly gather tokens from across the island just to keep her safe.</p></div>\n<div><p>In any case, token possession itself remained hidden behind layers of secrecy. Whether they were front-side or back-side, no third party had any reliable way to verify the total unless the owner chose to reveal it. The entire system was effectively a black box.</p></div>\n<div><p>Let alone knowing the token counts outside the group, even grasping the token counts within the group won't be straightforward.</p></div>\n<div><p>Additionally, it seems students could spend tokens to contact one another, but every use would naturally reduce the maximum number of tokens they could finish the exam with. Unless it was an emergency, unnecessary communication had to be avoided.</p></div>\n<div><p>After that, the explanation shifted to supplies: food, tents, and other necessities.</p></div>\n<div><p>Students would each be given a designated backpack and permitted to pack whatever items they wanted from the prepared stock.</p></div>\n<div><p>However, no explanation was given regarding what would happen if supplies ran short during the three nights on the island. Because of that, it was probably wiser to carry extra provisions even if it meant adding more weight.</p></div>\n<div><p>That naturally made girls with less muscle mass more likely to be at a disadvantage.<span></span></p></div>\n<div><p>Still, it was hard to believe the school hadn’t already considered that issue. There was a good chance some kind of support measure existed behind the scenes.</p></div>\n<div><p>“Now then, after a 10-minute break, you will assemble according to your assigned groups. That concludes the explanation.”</p></div>\n<div><p>With that, the briefing finally came to an end.</p></div>\n<div><p>I turned toward Hashimoto.</p></div>\n<div><p>“I need you to pass a message along to the others in class,” I said.</p></div>\n<div><p>Hashimoto looked over at me.</p></div>\n<div><p>“Sure thing, just say the word.”</p></div>\n<div><p>“The first thing I want you to tell them is this: whether they share their token counts with classmates is their own decision. But right now, they should think very carefully before doing it.”</p></div>\n<div><p>“…Carefully about sharing?” Hashimoto tilted his head slightly. “I mean, personally I’m all for keeping secrets, but wouldn’t sharing help avoid risks?”</p></div>\n<div><p>“It would, if you could be absolutely certain every single person was prepared to go down together for the sake of the class.”</p></div>\n<div><p>I paused.</p></div>\n<div><p>“But classmates are still, ultimately, other people. If it comes down to choosing between themselves and someone else, the answer becomes obvious.”</p></div>\n<div><p>Especially in my class, more than half the students were highly capable and deeply confident in their own abilities.</p></div>\n<div><p>And because they carried such a strong determination to graduate from Class A, careless information sharing carried risks of its own.</p></div>\n<div><p>The students assigned to each mixed group were now being forced to make a difficult choice:</p></div>\n<div><p><em>Would they constantly share information about their token counts with their classmates… or keep everything hidden?</em></p></div>\n<div><p>If a class managed token information thoroughly, then students running low could be supported collectively, reducing the risk of expulsions across the board. There was a clear advantage to that approach.</p></div>\n<div><p>Of course, doing so would make it nearly impossible for any individual to monopolize tokens and chase the massive personal rewards tied to them.</p></div>\n<div><p>Still, if the alternative was sacrificing classmates, plenty of students would consider that a fair trade.</p></div>\n<div><p>The problem was that even perfect cooperation didn’t guarantee safety.</p></div>\n<div><p>Suppose three or four students worked together and distributed tokens evenly among themselves. If that balance still resulted in someone ending up at the bottom overall, then expulsion remained unavoidable.</p></div>\n<div><p>In the end, the deciding factor would become OAA rankings.</p></div>\n<div><p>And if the group tried compensating for that by funneling extra tokens toward the student with the lowest OAA, then naturally the student with the second-lowest OAA would become the next person in danger.</p></div>\n<div><p>No matter how carefully people joined hands, trust and moral hazard would always exist side by side.</p></div>\n<div><p>It started with whether people could genuinely accept the policy established from the beginning. Even within a single group, resentment and distrust could easily grow through complaints like, “He’s holding more than he claims,” or “She’s not helping nearly as much as expected.” On top of that, there was no telling where information might leak.</p></div>\n<div><p>Students who accumulated large numbers of tokens would eventually attract attention beyond their own groups as well. The more successful someone became, the more they would inevitably be treated as a potential savior by people desperate for help.</p></div>\n<div><p>On the other hand, refusing to share token counts entirely was also a perfectly reasonable option.</p></div>\n<div><p>But complete secrecy created its own dangers.</p></div>\n<div><p>If nobody shared anything, then classmates approaching the expulsion threshold could not be rescued in time during emergencies.</p></div>\n<div><p>Worse, students willing to lie and manipulate others into offering assistance would gain a clear advantage. Paranoia inside the class would deepen further, slowly poisoning internal trust eventually causing losses.</p></div>\n<div><p>In the end, the most rational students would probably settle somewhere in the middle. They would avoid revealing exact numbers, respond vaguely like “I don’t really have room to spare,” and only contribute the bare minimum whenever a classmate truly faced immediate danger.</p></div>\n<div><p>“So basically,” Hashimoto said, “don’t trust your classmates too much.”</p></div>\n<div><p>“That’s right.”</p></div>\n<div><p>The fact that Hashimoto understood immediately probably meant he’d already been thinking along similar lines himself.</p></div>\n<div><p>After that, I gave him a few more requests to pass along.</p></div>\n<div><p>He accepted every one of them without complaint, nodding firmly each time.</p></div>\n<div><p>“Leave it to me for now.”</p></div>\n<div><p>Hashimoto answered with easy confidence, then immediately broke into a run across the sand.</p></div>\n<div><p>Almost as if trading places with him, Shiraishi and Nishikawa began walking toward me at an unhurried pace.</p></div>\n<div><p>“Just now, the loyal dog Hachikō, or rather, the loyal dog Hashimoto Masayoshi, seemed to run energetically across the sandy beach. He looked like a child unable to contain his joy at being asked to run an errand.”</p></div>\n<div><p>And alongside them was the usual oddball Morishita.</p></div>\n<div><p>“You look more energetic than expected, Ayanokōji Kiyotaka,” she said as she walked up. “Weren't you starting to feel a mixture of heart-pounding anticipation and anxiety from wanting to see me so badly?\"</p></div>\n<div><p>“Not even remotely,” I replied. “More importantly, considering you retired on the second day, you seem pretty energetic yourself.”</p></div>\n<div><p>“Quite, quite,” Morishita declared proudly without the slightest shame. “Life aboard the ship was unexpectedly wonderful. I spent private points like running water, eating delicious food, drinking, and playing around. Honestly, I would’ve liked to continue that elegant lifestyle for a while longer.”</p></div>\n<div><p>She spoke without the slightest attempt to hide a single thing.</p></div>\n<div><p>“That certainly sounds like a meaningful use of your time,” I said dryly. “Did anything unusual happen aboard the ship?”</p></div>\n<div><p>Expecting little of value from Morishita, I directed the question toward Nishikawa instead, since she had also been eliminated early.</p></div>\n<div><p>“The third-years who retired were basically given free time until the Survival Game Special Exam ended,” Nishikawa explained. “But it sounded like the first-years and second-years were doing separate special exams of their own. Though I haven’t heard anything about the results, so I don’t really know the details. Sorry.”</p></div>\n<div><p>So rather than getting an early summer vacation, it seemed they had been placed in a similar environment.</p></div>\n<div><p>“The first-years must have it rough too,” Shiraishi murmured. “They’re probably struggling with the contrast compared to the luxury cruise ship.”</p></div>\n<div><p>She sounded genuinely concerned, but Morishita immediately went “tsk, tsk” and wagged a finger.</p></div>\n<div><p>“You’re still far too naïve, Shiraishi Asuka. A real softie. Our juniors, especially the first-years, should absolutely suffer on the island just like we did. We’ve been struggling ever since our own first year, and yet they get pampered? Very cheeky.”</p></div>\n<div><p>Coming from someone who’d barely suffered at all this year, Morishita’s venom carried remarkably little self-awareness.</p></div>\n<div><p>“I happened to run into Yamamura Miki earlier,” she continued. “And wow, she absolutely reeked of sweat and dirt.”</p></div>\n<div><p>“Don’t say things like that, even as a joke,” I replied. “Yamamura staying until the end helped the class a lot. Same goes for Shiraishi here.”</p></div>\n<div><p>I looked toward Shiraishi.</p></div>\n<div><p>“How’s your condition?”</p></div>\n<div><p>“To be honest,” she answered with a faint smile, “it’s a little difficult. But I can’t afford to complain. Our class managed to take second place, and we’ve finally closed the distance with the classes above us.”</p></div>\n<div><p>In the Survival Game Special Exam, Ichinose’s class had finished first, Ryūen’s class third, while Horikita’s class had fallen to last place. As a result, the gap in Class Points between the upper and lower classes had narrowed significantly.</p></div>\n<div><p>Although our class had temporarily dropped into provisional Class D after the reshuffling, the difference between us and Ryūen’s class was still minimal.</p></div>\n<div><p>Depending on the outcome of the special exam about to begin, every class still had a realistic chance of ending up anywhere between A and D.</p></div>\n<div><p>“We actually came over because we wanted to compare our initial token counts.”</p></div>\n<div><p>Saying that, Shiraishi swiftly operated her wristwatch and turned the display toward me.</p></div>\n<div><p>The tokens displayed there were 12. Nishikawa, who showed hers in tandem, had 2, a massive difference.</p></div>\n<div><p>“What about Morishita?”</p></div>\n<div><p>“Fufu, I am a believer in secrecy.”</p></div>\n<div><p>“Earlier, I was allowed to confirm Morishita-san’s token count,” Shiraishi said calmly. “She had five.”</p></div>\n<div><p>It seemed the believer in secrecy had thoroughly shared her information.</p></div>\n<div><p>“Well, for someone operating at my level, five tokens is more than sufficient. Though in the unlikely event of an emergency, I fully intend to exploit Ayanokōji Kiyotaka, so please earn plenty on my behalf.”<span></span></p></div>\n<div><p>At the moment, Shiraishi held the highest confirmed count with twelve. I had eleven. Nishikawa had two, and Morishita five, huh.</p></div>\n<div><p>“Hashimoto had nine,” I said. “It’s probably safe to assume the longer someone remained active in the Survival Game Special Exam, the larger the advantage they received in starting tokens.”</p></div>\n<div><p>Class rankings, movements during the exam, roles, and contribution levels may also have had an effect.</p></div>\n<div><p>At the very least, those kinds of factors were clearly connected to the initial token distribution.</p></div>\n<div><p>How meaningful that initial token handicap would prove to be might become one of the major keys to the entire test.</p></div>\n<div><p>Shiraishi considered that silently before speaking again.</p></div>\n<div><p>“Since everyone begins with at least two tokens, would it be reasonable to assume the penalty involving the first student reduced to zero tokens is unlikely to happen easily?”</p></div>\n<div><p>“Not necessarily,” I replied. “As long as unrestricted token transfers exist, the system is constantly providing students with ways to adjust their situation.”</p></div>\n<div><p>I looked back toward Shiraishi.</p></div>\n<div><p>“If the very first task carried the possibility of losing multiple tokens, then students would need to receive additional tokens from others before even attempting it.”</p></div>\n<div><p>It was an intentionally extreme scenario.</p></div>\n<div><p>Realistically, the exam probably wouldn’t escalate that far that quickly. But with Morishita casually nodding along beside us, it wasn’t a bad lie to leave hanging in the air.</p></div>\n<div><p>A little tension would do her good.</p></div>\n<div><p>“Are you sure it's okay not to go and support everyone in the class?” Shiraishi asked quietly.</p></div>\n<div><p>“I’ve already asked Hashimoto to relay several things,” I replied. “Besides, no matter how thoroughly we organize things, nobody is truly safe from the zero-token expulsion penalty until they’ve secured a stable number of tokens for themselves. Since the groups have been separated, this is something they’ll have to overcome on their own.”</p></div>\n<div><p>There were limits to how much protection could be offered from the outside.</p></div>\n<div><p>If someone allowed their tokens to fall to zero so easily, then receiving an expulsion notice would simply be the consequence of that failure.</p></div>\n<div><p>There was another possible approach, of course.</p></div>\n<div><p>The class could gather from the start, pool its surplus tokens, and redistribute them to students like Nishikawa, who possessed only the minimum amount.</p></div>\n<div><p>On paper, that would strengthen the weakest members of the class. But even that strategy came with drawbacks.</p></div>\n<div><p>Protecting weaker students too aggressively would lower the overall ceiling of the class’s earning potential. The more tokens were redistributed defensively, the harder it became for stronger students to maximize gains elsewhere.</p></div>\n<div><p>And in an exam structured entirely around token acquisition, lowering the class’s offensive potential too much could become fatal in its own way.</p></div>\n<div><p>If the class intended to win, then students ultimately needed to gather tokens through their own ability.</p></div>\n<div><p>This was not an exam where every single person could be protected with absolute certainty. A certain amount of risk had to be accepted.</p></div>\n<div><p>“By the way,” Nishikawa asked, “what group did you end up in, Ayanokōji-kun? I’m in Group One. Honestly, I was hoping I’d end up with Asuka if possible, though~\"</p></div>\n<div><p>It seemed Shiraishi had been assigned to Group Two instead, so that wish had not been granted.</p></div>\n<div><p>“So you wish to know my group?” Morishita folded her arms with unnecessary pride, “truly, what a secretly perverted man you are! It’s Group Three. Three.”</p></div>\n<div><p>“I don’t remember asking in the slightest…” I muttered. “Wait. Don’t tell me we’re actually in the same group…”</p></div>\n<div><p>“Eh!? Seriously!? We’re together!?”<span></span></p></div>\n<div><p>Morishita abruptly covered her mouth with both hands in exaggerated shock.</p></div>\n<div><p>Though notably, her eyes remained completely unchanged.</p></div>\n<div><p>“This is going to be an exhausting special exam…”</p></div>\n<div><p>Just imagining how loud things were likely to become over the next few days was enough to leave me slightly depressed already.<span></span></p></div>\n<div><h2>Part 1</h2></div>\n<div><p>With the explanations finally concluded, Morishita and I made our way to our group's designated gathering spot.</p></div>\n<div><p>Since Group 3’s standby area happened to be right nearby, we ended up being the first ones to arrive.</p></div>\n<div><p>“Allow me to make one thing clear in advance,” Morishita said, turning to me with the composed severity of someone delivering an official warning. “During the exam, please refrain from acting overly familiar with me. If there were even the slightest misunderstanding that you were my boyfriend, it would seriously ruin my future school life.”</p></div>\n<div><p>“You don’t have to worry about that.”</p></div>\n<div><p>“I wonder about that,” she replied without missing a beat. “They say that even when a man denies it, his lower half remains quite energetic. Though I admit, I don't fully understand the biological mechanisms behind it.”<span></span></p></div>\n<div><p>“You really have a knack for speaking confidently about things you know nothing about.”</p></div>\n<div><p>“Flattery won't raise my affection rating for you, you know.”</p></div>\n<div><p><em>Isn't anyone else going to show up?</em></p></div>\n<div><p>Just as I was silently hoping for a distraction, the sound of footsteps shifting through the sand reached my ears.</p></div>\n<div><p>“Let’s do our best, Ayanokōji.” The voice belonged to Yoshida Kenta, who had come up from behind.</p></div>\n<div><p>Sanada followed shortly after, and with their arrival, the Class C members assigned to our group had gathered. Looking over them, they were the academically inclined sort, students who might not stand out in any dramatic way, but who could be counted on to handle most situations steadily and without unnecessary trouble.</p></div>\n<div><p>“Ugh, Morishita, seriously?” Yoshida groaned.</p></div>\n<div><p>“It seems you simply cannot hide your joy, Kobayashi Kenta.”</p></div>\n<div><p>“It's Yoshida,” he corrected at once. “<em>Yoshida.</em>”</p></div>\n<div><p>“...Ugh. Ayanokōji. Don't tell me I'm stuck with you.” The voice that cut in from the side was thick with undisguised disgust. It belonged to another participant: Class B’s Ibuki Mio.<span></span></p></div>\n<div><p>Almost at the same moment, another figure began moving toward us: Katsuragi Kōhei, his expression stiff and guarded.<span></span></p></div>\n<div><p>“To think I'd be placed in the same group as you,” he said, stopping nearby. “It looks like this is going to be a tough battle.”</p></div>\n<div><p>“I could say the same,” I replied.</p></div>\n<div><p>Katsuragi wasn’t the type to be easily swayed by emotion. If he ended up on the opposing side in a special exam like this, he wouldn’t make things easy for anyone.</p></div>\n<div><p>That said, because this exam also required mutual cooperation within the same group, he could just as easily be considered a highly dependable ally, making it difficult to definitively weigh his presence.</p></div>\n<div><p>The rest of the Class B students had yet to make an appearance. Before they did, however, a student from Class A approached.</p></div>\n<div><p>“Oh, I'm with you, Ibuki-san!” Kushida’s voice came brightly from behind her. “I look forward to working together.”</p></div>\n<div><p>She stepped close to Ibuki and, with a gentle little pat, placed a hand on her shoulder. Her smile was flawless, almost angelic.</p></div>\n<div><p>To anyone watching from the outside, it would have looked like nothing more than a girl warmly greeting a friend. Whether that was truly the case, however, was another matter.</p></div>\n<div><p>“Ugh, Kushida... This is the absolute worst.”</p></div>\n<div><p>Ibuki looked just as thoroughly disgusted with her as she had been with me, but Kushida, naturally, didn't allow a single facial muscle to twitch.</p></div>\n<div><p>In the meantime, students from the other classes continued to arrive one after another.</p></div>\n<div><p>When, at last, all sixteen participants had gathered, I looked over the group once more and took a moment to mentally review the lineup.</p></div>\n<div><hr></div>\n<div><p><strong>Group 3 Participants</strong></p></div>\n<div><p>Class D: Sumida Makoto, Moriyama Susumu, Minamikata Kozue, Amikura Mako.<span></span></p></div>\n<div><p>Class C: Ayanokōji Kiyotaka, Yoshida Kenta, Sanada Kōsei, Morishita Ai.</p></div>\n<div><p>Class B: Sonoda Masashi, Katsuragi Kōhei, Ibuki Mio, Morofuji Rika.</p></div>\n<div><p>Class A: Ike Kanji, Kushida Kikyō, Shinohara Satsuki, Wang Mei-Yu.<span></span></p></div>\n<div><hr></div>\n<div><p>There were a few loudmouths in the mix, but my initial impression was that this was a solid, well-balanced group.<span></span></p></div>\n<div><p>I immediately began constructing the logic needed to secure a win, and more importantly, how to avoid a loss.<span></span></p></div>\n<div><p>The important factors were the number of tokens, the multipliers, and avoiding penalties. There were still unknowns, such as the goals system that affected those multipliers, but one thing was already certain: these sixteen people were both allies and enemies. By analyzing their individual abilities and relationships, I began narrowing down the optimal way to maneuver from here.</p></div>\n<div><p>As I ran through these calculations, I noticed the four Class A students watching me closely.</p></div>\n<div><p>As their former classmate, I figured I should probably offer them a standard, polite greeting. Though, knowing Ike and the others, there was a fair chance they would just hurl abuse at me the second I opened my mouth.</p></div>\n<div><p>While I was idly considering that possibility, Ike Kanji and Shinohara Satsuki exchanged a glance. Then after a brief, hushed conversation, they took the initiative and approached me, both wearing visibly nervous expressions.</p></div>\n<div><p>They were walking extremely close to one another, close enough that their shoulders nearly lined up. From that alone, it was easy to see that their relationship was still going well.</p></div>\n<div><p>Statistically, the probability of a couple ending up in the same group was just under eight percent. It wasn't a particularly surprising outcome in itself, but the two of them likely interpreted it as some stroke of baseless romantic destiny.<span></span></p></div>\n<div><p>Behind them, Kushida and Mii-chan were watching me as well. Kushida, smile firmly in place, gave me a small, casual wave. Mii-chan, meanwhile, looked somewhat nervous, but still lowered her head in a polite bow.<span></span></p></div>\n<div><p>“I never imagined I'd end up in the same group as you, Ayanokōji.”</p></div>\n<div><p>Ike was the first to speak. His tone was surprisingly composed. Even as I considered how best to match his demeanor, he kept going.</p></div>\n<div><p>“When I first saw your face, I thought about giving you a piece of my mind. But since we're stuck in the same group, we might as well try to get along. I'll lend a hand where I can.”</p></div>\n<div><p>“I feel the same way as Kanji,” Shinohara added. “It doesn't seem like this exam is just a straightforward battle, and I think I properly understand just how capable you actually are, Ayanokōji-kun. I'll cooperate however I can, so I look forward to working with you.”</p></div>\n<div><p>It was an unexpectedly amicable greeting from my former classmates. Given the circumstances, they should have harbored overwhelmingly negative feelings toward me. Yet, their smiles were genuine, lacking any trace of deception, and they seemed to be treating me as normally as possible.<span></span></p></div>\n<div><p>In this exam, we were simultaneously allies and enemies. That was precisely why they wanted to keep the peace and approach the situation cordially. Maneuvering to avoid making unnecessary enemies was the tactically correct decision, but I was genuinely surprised to see such sound judgment coming from these two. It felt as though I was witnessing a genuine sign of growth.</p></div>\n<div><p>Considering they were addressing the very person who had betrayed their class, their soft expressions and mild demeanor were practically impeccable. Ike and Shinohara had likely mustered a great deal of courage just to initiate this contact.</p></div>\n<div><p>I let my gaze slip away from the two of them.</p></div>\n<div><p>Then, without stopping, I passed by and moved toward Kushida and Mii-chan, who had been standing just behind them, quietly watching how things were unfolding.</p></div>\n<div><p>”I'm sure there are plenty of difficulties that come with working alongside a traitor,” I said, directing my first words to Mii-chan. “But I look forward to working with you until the exam concludes.”</p></div>\n<div><p>“Eh?” She blinked, visibly caught off guard. “Ah, y-yes. The pleasure is mine...”</p></div>\n<div><p>Though she was flustered, her reply was polite, almost overly so. After receiving it, I shifted my eyes to Kushida, who stood beside her.</p></div>\n<div><p>“It would be a great help if I could rely on you as an ally, too.”</p></div>\n<div><p>“That’s what I should be saying,” Kushida answered with a gentle smile. “I only hope someone like me can be useful.”</p></div>\n<div><p>Her voice was soft, her expression perfectly composed. Only her eyes gave the faintest glimpse of something closer to her true feelings.</p></div>\n<div><p>“I rate your communication skills particularly highly, Kushida,” I said. “With students from all four classes mixed together, managing the group won’t be easy.”</p></div>\n<div><p>“Of course, I'll do everything in my power to help. It would be wonderful if everyone in the group could achieve a good result, wouldn't it?” Ever mindful of the prying eyes around us, Kushida delivered a flawlessly safe response.</p></div>\n<div><p>“That will be sufficient.”</p></div>\n<div><p>With those brief greetings out of the way, I turned my back on them and began walking over to where the Class C students were gathered.</p></div>\n<div><p>“Hey, wait, hold on a second?”</p></div>\n<div><p>“Um, Ayanokōji-kun...?”</p></div>\n<div><p>Ike and Shinohara called after me, their voices carrying the same bewilderment their faces showed. Neither of them seemed to understand what had just happened. They had approached me, offered a greeting, extended something close to goodwill, and I had walked past them as though it had never reached me.</p></div>\n<div><p>I gave them only the briefest glance.</p></div>\n<div><p>Then I continued on.</p></div>\n<div><p>Perhaps realizing just how unnatural this behavior was, Ike raised his voice.<span></span></p></div>\n<div><p>“Wait a minute, you're just gonna ignore us?!”</p></div>\n<div><p>The irritation in him finally began to show. He had been the one to take the first step, forcing down whatever resentment still lingered inside him and choosing to speak to me before Kushida or Mii-chan did.</p></div>\n<div><p>“That's honestly really messed up,” Shinohara said, her tone losing some of its earlier composure. “I mean, seriously… Did we do something to you?”</p></div>\n<div><p>“No, nothing,” I answered. “I simply judged that you weren't worth greeting.”<span></span></p></div>\n<div><p>“Excuse me?!”</p></div>\n<div><p>Showered with such unexpectedly merciless words, their expressions predictably, and rather amusingly, twisted with fresh anger.<span></span></p></div>\n<div><p>Even Kushida likely couldn't have imagined I would say something so harshly blunt.</p></div>\n<div><p>But their reaction was a perfectly natural one. Anyone would be furious if they choked down their negative feelings to politely greet someone, only to receive an unreserved insult in return.</p></div>\n<div><p>“Well then,” I said, already turning away. “I’ll see you later.”</p></div>\n<div><p>Even as I took my leave, I aimed those parting words entirely at Kushida and Mii-chan, completely ignoring the other two.</p></div>\n<div><p>“Ayanokōji!” Ike shouted after me, his restraint finally breaking. “What the hell is your problem?! That attitude is way out of line!”<span></span></p></div>\n<div><p>Though he finally let his suppressed emotions explode, Ike didn't attempt to chase after me.</p></div>\n<div><p>Ignoring his shouting, I resumed my walk toward the area where Yoshida and the others had gathered. Along the way, I noticed a girl standing between us, frozen as though the commotion had caught her attention and then left her unsure of what to do. She was looking directly at me as our eyes met.</p></div>\n<div><p>“...A-Ah, s-sorry! I'm sorry...!” Morofuji stammered, shrinking back almost at once. “F-For being in the way...”<span></span></p></div>\n<div><p>Her apology came out in broken fragments. Before I could say anything, she hurriedly moved aside and fled, her behavior suspiciously restless.</p></div>\n<div><p>There had been no particular reason for her to apologize. Yet the look on her face had gone beyond ordinary wariness. She seemed frightened, unnaturally so.</p></div>\n<div><p>Morofuji had once been among the students involved in the bullying of Karuizawa. Perhaps what happened back then still lingered in her memory and influenced the way she saw me now.</p></div>\n<div><p>As I watched her flee back toward the Class B students, Yoshida approached from the other side and called out to me.</p></div>\n<div><p>“Did something happen with Morofuji?”</p></div>\n<div><p>“No,” I replied. “Nothing in particular.”</p></div>\n<div><p>“I see. More importantly…” Yoshida glanced past me. “Are you sure that’s okay? Ike and Shinohara have been glaring at you this whole time.”</p></div>\n<div><p>He must have overheard parts of our exchange, judging by his concerned tone.</p></div>\n<div><p>“Don't worry about it. I never intended to play nice with my former classmates to begin with,” I replied. “More importantly, now that you’ve seen the members, what's your assessment of our group's lineup?”<span></span></p></div>\n<div><p>“Hm? Oh, well,” Yoshida looked over the gathered group. “I’d say we got off pretty easy. Katsuragi is going to be a pain since he knows us well, but the rest of Class B's members are pretty minor players. Class A is a mixed bag: a weird, mismatched combination of top-tier and bottom-tier students. As for Class D, they're well-balanced, and they seem capable enough, but they aren't exactly intimidating, you know?”</p></div>\n<div><p>Having visualized the upcoming battles, Yoshida offered this straightforward evaluation.</p></div>\n<div><p>“This setup should make things pretty easy for you to maneuver too, right?” he asked.</p></div>\n<div><p>“If we’re only talking about Group Three, then that assessment is correct.” I looked over the assembled students once more. “However, when it comes to the key leaders, figures like Ryūen, Horikita, and Ichinose, it would have been best to have them all placed in the same group as me. Especially Ryūen.”</p></div>\n<div><p>“...<em>Ryūen?” </em>Yoshida’s face twisted at the thought, as if he had just bitten into something bitter. “I'd absolutely hate being stuck in the same group as him.”</p></div>\n<div><p>From a short distance away, Sanada, who had been listening to us, slowly approached.</p></div>\n<div><p>“The more troublesome the opponent, the more useful it is to keep them close. In this special exam, that makes them easier to control. That’s what you’re thinking, isn’t it, Ayanokōji-kun?”</p></div>\n<div><p>“Exactly. Regardless of who I’m up against, my commitment to doing whatever it takes to protect the class and secure a win remains unchanged. But given the structure of this exam, it’s going to be impossible to manage everything happening out of my sight.”</p></div>\n<div><p>Sanada nodded, picking up the exam materials and flipping to the page detailing the penalties.</p></div>\n<div><p>“To a certain extent, I can maneuver things to ensure our classmates don't finish dead last in token counts, or prevent anyone from failing to reach the goal,” I said. “However, the penalty stating that the first student whose tokens drop to zero will face immediate expulsion, that is something I have absolutely no control over.”</p></div>\n<div><p>Yoshida seemed to understand what I meant. His mouth bent into a hard, uneasy line, and after a moment he nodded.</p></div>\n<div><p>“Yeah, you've got a point... If the guys grouped with Ryūen fall for one of his underhanded tricks and hit zero tokens, they'd be instantly expelled on the spot. When you put it like that, it's actually pretty terrifying.”</p></div>\n<div><p>“Of all the penalties outlined in the rules, I feel that's the only one I can't actively counter,” I added.</p></div>\n<div><p>In reality, under a specific set of conditions, there was a chance that an entirely different penalty could bare its fangs and prove even more devastating. However, there was no point in bringing that up right now, so I let the thought pass.<span></span></p></div>\n<div><p>“Isn't it pointless to worry too much about it?” Sanada interjected. “I imagine the school has designed the tasks so that tokens won’t drop to zero that easily.”</p></div>\n<div><p>“Sanada's right,” Yoshida agreed. “As long as someone doesn't do something incredibly stupid and walk right into a trap, they'll be fine. Besides, even if we do worry about it, there's no way to prevent it, right?”</p></div>\n<div><p>“For now, let's prioritize figuring out how our own group is going to maneuver,” Sanada said.</p></div>\n<div><p>I gave a single nod in agreement.</p></div>\n<div><p>From here on out, my process would be the same as always. I needed to gather all the scattered building blocks of practical strategies before me and begin sorting through them based on what was efficient and what wasn’t.</p></div>\n<div><p>I had already eliminated many unnecessary possibilities from consideration, but I still lacked the information necessary to map out the hidden motives of the class leaders: Horikita, Ichinose, and Ryūen.<span></span></p></div>\n<div><p>More time was needed before I could fully analyze the finer details of the rules.</p></div>\n<div><p>In the meantime, with our faculty supervisor still nowhere to be seen, I let my gaze drift around the area.</p></div>\n<div><p>Naturally, the entirety of the third-year student body, along with numerous adult staff members, were hurriedly gathering nearby.</p></div>\n<div><p>That said, I wasn't scanning the crowd to figure out the composition of all ten groups, nor was I trying to map out who belonged where. While I could roughly identify some of it just by observing the crowd here, without any way to guarantee complete accuracy, there was little value in trying to memorize it all.</p></div>\n<div><p>My true objective was simpler than that.</p></div>\n<div><p>I was looking for one particular person.<span></span></p></div>\n<div><p>And sure enough, I eventually spotted Hiyori in the distance, chatting happily while surrounded by her classmates. If she had been closer, I might have been able to call out to her, but the physical distance made that completely impossible.</p></div>\n<div><p>It seemed I really was fated to have no meaningful interaction with her during this Uninhabited Island Exam.</p></div>\n<div><p>But there was no need to rush.</p></div>\n<div><p>Once we returned to the cruise ship, there would inevitably be time to talk.</p></div>\n<div><p>“...”</p></div>\n<div><p>Suddenly, a strange sense of dissonance crept into my thoughts.</p></div>\n<div><p>That’s right. There was no need to rush.<span></span></p></div>\n<div><p>And thinking I was ‘fated to have no connection’ with her was logically incorrect, too.</p></div>\n<div><p>It was true that we hadn't spoken for a few days, not since we first boarded the cruise ship. But a few days wasn't nearly long enough to warrant such a dramatic conclusion. In fact, looking back, there had been plenty of times where we had gone much longer without interacting at all.</p></div>\n<div><p><em>So why was I suddenly overwhelmed by the sensation that it had been an eternity since we last spoke?</em></p></div>\n<div><p>No...</p></div>\n<div><p><em>Was the very fact that I was questioning the reason already proof that I had entered unfamiliar territory?</em></p></div>\n<div><p><em>Was this the effect of realizing I might have feelings for Hiyori, the change it had brought about in my heart?</em><span></span></p></div>\n<div><p>Given the current lack of concrete exam details, Hiyori, who belonged to a different class and a completely different group, was nothing but static noise. Her existence factored nowhere into the strategic framework I was currently constructing.</p></div>\n<div><p>And still, my eyes followed her.</p></div>\n<div><p>Unconsciously, they traced the distant outline of her profile.</p></div>\n<div><p>Even after I realized what I was doing, nothing changed.</p></div>\n<div><p>The action was pointless. The time spent on it served no practical purpose. Even so, somewhere within that uselessness, there was a faint stirring of exhilaration.</p></div>\n<div><p>If this feeling really was romantic affection, then had Karuizawa once looked at me in the same way? Had she felt something similar when her eyes followed me?</p></div>\n<div><p>Romance was a textbook I had failed to comprehend on my first read-through. But by reviewing the material, I was gradually beginning to notice all the subtle details I had missed the first time around.<span></span></p></div>\n<div><p><em>What sort of emotion was born when speaking to the person one liked?</em></p></div>\n<div><p><em>What arose when touching them?</em></p></div>\n<div><p>My curiosity wasn't limited to purely positive feelings, either.</p></div>\n<div><p><em>What sort of emotions would be born within me if I were to be hated by that same person, or if I were to lose them entirely?</em><span></span></p></div>\n<div><p>I wanted to experience both ends of it: the warmth of affection, and the coldness of rejection. Love and hate alike.</p></div>\n<div><p>Yet perhaps it was foolish to wish for both at the same time.</p></div>\n<div><p>Perhaps it was important not to be greedy. Perhaps one should not try to learn everything from a single romance.</p></div>\n<div><p>If attaining both was impossible, then experiencing either one would suffice...<span></span></p></div>\n<div><p>“What's wrong, Ayanokōji? Something bothering you?”</p></div>\n<div><p>Yoshida, who had been speaking with Sanada only moments before, turned his attention toward me.</p></div>\n<div><p>“No, not particularly,” I replied. “Why do you ask?”</p></div>\n<div><p>“Well, it’s not exactly why……” He glanced in the direction I had been looking, then back at me. “You were staring off into the distance. I thought maybe you’d noticed something we should be worried about.”</p></div>\n<div><p>“We just finished the Survival Game Special Exam, after all,” I replied smoothly. “I suppose I'm just a little worn out. But considering Shiraishi and Yamamura are still giving it their all, I can't exactly be the first one to throw in the towel.”<span></span></p></div>\n<div><p>Taking a brief pause, I decided to steer the conversation and add a bit more context.</p></div>\n<div><p>“Right now, we don't have the full picture. We don't know the exact number of tasks, nor how many tokens we'll actually be able to acquire. Whatever happens, please do not leak any information regarding your token counts to anyone outside.”</p></div>\n<div><p>“Not even to our allies, right? I heard that from Hashimoto,” Yoshida said.</p></div>\n<div><p>“Right. And for now, I’d also like to avoid unnecessary conflict with the other classes. If we’re going to aim for first place in this group, like you’re hoping, then cooperation with students from the other classes will be unavoidable.”<span></span></p></div>\n<div><p>“I suppose that's true,” Sanada chimed in. “But I wonder how the other side feels about that. I'm sure they want the Private Points, but they probably don't want our class to win, either. They might end up slacking off on purpose.”</p></div>\n<div><p>“Even if they do, the leaders of the other three classes are facing the exact same dilemma. The underlying motive of not wanting to hand another class a victory will always be a factor.”</p></div>\n<div><p>Sanada and Yoshida exchanged a brief glance, quickly understanding the logic behind my words.</p></div>\n<div><p>“I get what you're saying,” Yoshida said. “Anyway, just give us the word whenever you need us.”</p></div>\n<div><p>I gave a single nod, letting my demeanor convey my gratitude.</p></div>\n<div><p>Satisfied with my convenient excuse, Yoshida gave me a light pat on the back.</p></div>\n<div><p>“Don't hesitate to reach out if you need a hand.”</p></div>\n<div><p>“Yeah, I will.”</p></div>\n<div><p>With that response, I finally tore my lingering gaze away from Hiyori.</p></div>\n<div><p>For the time being, all I needed to focus on was getting through this Special Exam. Everything beyond that could wait.<span></span></p></div>\n<div><h2>Part 2</h2></div>\n<div><p>Right around the time Ayanokōji was making his first contact with Group 3, Horikita, assigned elsewhere to Group 8, was experiencing a face-to-face encounter of her own.</p></div>\n<div><p>A gentle sea breeze playfully tossed the long, pink hair of the student standing before her. A warm smile graced the girl's lips as she spoke.</p></div>\n<div><p>“I look forward to working with you, Horikita-san.”</p></div>\n<div><p>“I knew there was a decent chance that class leaders might end up in the same group, but to think I'd be paired with you of all people, Ichinose-san.”</p></div>\n<div><p>Inwardly, Horikita breathed a sigh of relief. Out of the three rival leaders, Ichinose was by far the easiest to manage. It wasn't a question of her being a weak opponent, but rather a certainty: <em>having Ichinose Honami as an ally would bring an immense sense of stability to their group.</em></p></div>\n<div><p>This special exam certainly contained the element of competition between classes. However, it also placed heavy importance on the results achieved by each group as a whole. In that regard, Ichinose’s presence was almost guaranteed to steer them in a positive direction.</p></div>\n<div><p>“If this were a purely class-based competition, it might have been a bit troublesome,” Ichinose said. “But looking at the rules, cooperating as a group clearly leads to mutual benefit, so it's a rather good setup. If you and I pool our strengths, Horikita-san, we might just be able to guide our group to a safe and steady victory.”</p></div>\n<div><p>It seemed Ichinose had been harboring the exact same thoughts.</p></div>\n<div><p>Yet, looking at the girl standing before her, Horikita sensed a quiet, powerful intensity that hadn't been there before. As an enemy, this newfound strength would be a nightmare to deal with. But as an ally? It made her incredibly reliable.</p></div>\n<div><p>“True enough,” Horikita replied. “As leaders, our group is expected to secure a win. Under normal circumstances, we'd be probing each other for ulterior motives, but instead, we will cooperate and aim for the highest rank possible... I take it we're in agreement on that?”</p></div>\n<div><p>Whether they chose to cooperate or oppose would determine everything. It was possible to send tokens to other groups, deliberately weakening their own side in order to prevent another class from profiting. Depending on the policy they adopted, the total number of tokens their group could secure would change dramatically.</p></div>\n<div><p>“Of course,” Ichinose replied brightly. “If our group takes first place, we'll each be rewarded with one hundred Class Points. It's the ideal outcome for both of us. And it won't just be me, if necessary, I'll firmly request the full cooperation of everyone in Class D. Does that work for you?”</p></div>\n<div><p>“I'll gladly accept your offer,” Horikita said smoothly. “On our end, I also intend to unite my classmates under a policy of securely maximizing our group's total tokens. Though, naturally, that will heavily depend on the moves made by Class B and Class C, whose hands we've yet to see.”</p></div>\n<div><p>Students from the other classes began to appear one by one, but there was no sign of Ayanokōji or Ryūen among them.</p></div>\n<div><p>Hypothetically, if all four class leaders had ended up in the same group, cooperating to maximize their total token yield would have been a simple affair. However, such an arrangement offered little benefit to anyone aside from the front-running Class A.</p></div>\n<div><p>A precious Special Exam like this was a rare opportunity to widen the gap between classes; but if every leader simply worked together in the same group, that precious chance would be dulled from the outset.</p></div>\n<div><p>“It seems coming to a mutual understanding and aiming for first place will go smoother than expected,” Horikita noted. “However, there is one critical issue that both you and I must treat with the utmost importance.”</p></div>\n<div><p>“How to handle the expulsions... right?”</p></div>\n<div><p>Their eyes met, and Horikita gave a firm nod.</p></div>\n<div><p>It had already been established that this Special Exam would result in expulsions. Worse still, one of those was a mandatory penalty that <em>someone </em>absolutely had to shoulder. The only ways to prevent a student from being sent home were if the target conveniently held a Protection Point, or if someone paid the exorbitant fee of 20 million Private Points.</p></div>\n<div><p>“Horikita-san,” Ichinose said, her tone resolute. “I absolutely will not allow a single one of my classmates to be expelled. If securing first place in total tokens requires sacrificing a peer, then I will choose to save my ally without a second thought.”</p></div>\n<div><p>The unspoken message from Ichinose was clearly hanging in the air: <em>If you have a problem with that, speak up now.</em></p></div>\n<div><p>Taking the declaration in stride, Horikita drew a quiet breath before responding. “I agree. I have no intention of sacrificing my classmates either.”</p></div>\n<div><p>“Then I suppose that makes us allies who can join hands and face the same direction, right?”</p></div>\n<div><p>“...Assuming you're willing to trust me, that is.”</p></div>\n<div><p>Horikita was well aware that she hadn't garnered nearly as much goodwill and trust as Ichinose had. She knew her standing. Right now, she was the one who needed to prove she was worthy of being trusted.</p></div>\n<div><p>“Then it looks like we won't have any problems!”</p></div>\n<div><p>Breaking into a bright, unwavering smile, Ichinose extended her hand.</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"https://cdn.sanity.io/images/m1xj6lbt/production/09779d2ff988ea23846805b0c78a8ec1dbeaa1e6-2000x2808.webp\"><span><span></span></span></div>\n<div><p>Seeing her unhesitating demeanor, Horikita couldn't help but let out an inward sigh of admiration.</p></div>\n<div><p>Over the past two years, Ichinose had weathered countless storms through the sheer power of trust, a track record that spoke volumes. Horikita had felt it indirectly on several occasions, but standing beside her in the same group brought that strength into incredibly sharp, reassuring focus. Under normal circumstances, one should never easily trust a rival. Yet, Horikita found her mind effortlessly jumping to the conclusion that Ichinose was safe to believe in.</p></div>\n<div><p>Of course, that trust was not absolute. The possibility of betrayal, however remote, could never truly be erased.</p></div>\n<div><p>But the mere fact that Ichinose could subconsciously instill such an unwavering mindset in someone: making them feel that <em>if I am betrayed by Ichinose, then so be it, </em>was a profoundly impressive feat in itself.</p></div>\n<div><p>“Before I take your hand, there is one more thing…”</p></div>\n<div><p>Staring down at Ichinose's slender, elegant fingers, Horikita pressed further, delving into the crux of the matter.</p></div>\n<div><p>“Sacrifices are practically unavoidable in this exam. However, we are agreeing that neither of our classes will produce any expulsions, and we will maneuver with everything we have to ensure that. Maintaining this policy means, by process of elimination, cornering someone from either Ryūen-kun's or Ayanokōji-kun's class for expulsion instead. Are you prepared for that?”</p></div>\n<div><p>At the sharp question, Ichinose closed her eyes for a moment, letting out a soft, breathy laugh.</p></div>\n<div><p>“It's true that the old me probably wouldn't have agreed so easily,” she admitted. “But I don't hesitate anymore. You can rest assured, Horikita-san, I have no intention of holding back against rival classes if it means protecting my friends.”</p></div>\n<div><p>Horikita met that open, unwavering gaze head-on.</p></div>\n<div><p>“I see. It seems you've grown far more than I realized while I wasn't looking, Ichinose-san.”</p></div>\n<div><p>Horikita had always recognized her as a formidable opponent. Yet, somewhere deep down, she had still been underestimating the student known as Ichinose Honami.</p></div>\n<div><p>Being a genuinely good person usually meant harboring inherent weaknesses beneath the surface. Protecting an entire class was no easy feat; Horikita and Hirata had both tried countless times, only to fall short of that ideal. Yet, despite her bitter struggles, Ichinose had continued to protect her classmates to this very day, refusing to lose a single one.<span></span></p></div>\n<div><p>“I feel the exact same way about you, Horikita-san,” Ichinose replied softly. “You're much more formidable now than when we first enrolled.”</p></div>\n<div><p>“I wonder about that. Personally, I feel it's only become harder to maneuver now that I have more things to protect…” Horikita trailed off before continuing. “But more importantly, there is something that's been bothering me since we heard the explanation for this Special Exam. Ensuring our allies' tokens don't drop to zero will require a certain element of luck. What are your thoughts on that?”</p></div>\n<div><p>“Have you noticed the correlation between the number of starting tokens and the Survival Game Special Exam?”</p></div>\n<div><p>“Yes,” Horikita answered. “Students who remained in the previous exam for a longer time seem to have received more tokens. Of course, I haven’t confirmed it with every classmate, so I can’t say for certain…”</p></div>\n<div><p>She added, after a moment, that this was based only on what she had heard from several students whose elimination times had differed.</p></div>\n<div><p>“That is my assessment as well,” Ichinose said. “In other words, you could say we have a slight advantage over Ayanokōji-kun's and Ryūen-kun's classes, since both suffered a high number of early eliminations.”</p></div>\n<div><p>“Your class even had students who remained until the very end. If that conclusion can be drawn from the highest number of tokens among them, then you’re probably right. However, simply having a high total token pool as a class doesn't necessarily mean things will proceed to our advantage.”</p></div>\n<div><p>Ultimately, because the students had been distributed randomly, a high class total would only create variance between the different groups, or at best, provide an edge in individual battles.</p></div>\n<div><p>“But holding a large number of tokens as a class does mean a massive difference in how often we can transmit information over the radios,” Ichinose countered. “If you and I cooperate to meticulously manage our tokens, Horikita-san, we can constantly keep track of any students whose counts drop dangerously low. Excluding Group 10, which doesn’t have full sixteen members, we’d have eight people in each group who could transfer tokens and cover for one another.”</p></div>\n<div><p>“I see... You're suggesting that everyone outside of our Group 8, which will strictly aim for first place, maneuvers solely to prevent casualties? Transferred tokens are flipped Back-side, meaning they lose their value for individual rewards. But from our group's perspective, it also means the rival groups we need to defeat will naturally fall behind.”</p></div>\n<div><p>Under normal circumstances, coordinating two separate classes with such a unified strategy was no simple task. First and foremost, it required forcing the students assigned to the other nine groups to completely abandon any hope of acquiring the Special Reward. While the monolithically united Ichinose Class might accept such terms, convincing every single one of Horikita's classmates to swallow that pill would be practically impossible.</p></div>\n<div><p>“It's an interesting idea,” Horikita said, “but it means forcing students in other groups who might be perfectly capable of pulling off a massive upset to sacrifice their chances. If anything, wouldn't the groups completely free of Ryūen-kun and Ayanokōji-kun's influence be the ones harboring the best chance for a surprise victory?”</p></div>\n<div><p>This exchange perfectly highlighted their fundamental difference in approach. Ichinose wanted to fight with a heavily defensive focus, prioritizing collective survival, while Horikita wanted to maintain a certain degree of offensive awareness, seeking out opportunities to win.</p></div>\n<div><p>Even with their agreement to cooperate, Horikita couldn't shake the strong premonition that this Special Exam was going to be fraught with difficulties.</p></div>\n<div><p>“You're right,” Ichinose agreed softly. “I'm sure we won't always see eye to eye. But this Special Exam lasts for four days and three nights. Let's discuss things thoroughly and decide our course as we go, Horikita-san.”</p></div>\n<div><p>“True. We still don't know what the specific tasks entail or how the tokens will flow in practice. There's no point in rushing things.”</p></div>\n<div><p>“Alright then. I’ll go speak to everyone in the group.”</p></div>\n<div><p>With a polite bow, Ichinose excused herself and stepped away.</p></div>\n<div><p>Standing alone at a slight distance, Horikita watched as Ichinose cheerfully exchanged greetings with students from other classes.</p></div>\n<div><p>“I know there's no need to rush, but…” she murmured to herself.</p></div>\n<div><p>Her mind drifted back to a troubling exchange she’d had with Sudō immediately following the Survival Game Special Exam.</p></div>\n<div><p><em>“There might be a traitor in our class.”</em></p></div>\n<div><p>He had told her how, during Class A's battle, the opposing students had completely bypassed him, despite the massive physical threat he posed on the battlefield, to aggressively target Satō, their VIP.</p></div>\n<div><p>If Horikita had been the enemy commander, she would have undoubtedly prioritized taking Sudō off the board first. If the opposition had instead focused all their fire on Satō... and if someone had been pulling the strings from the shadows to orchestrate that...</p></div>\n<div><p><em>“Is someone in our class really leaking information...?”</em></p></div>\n<div><p>Her gaze drifted, eventually landing on Ayanokōji's figure in the distance. Gathered with him were four students from Class A: Wang, Shinohara, Ike, and Kushida.</p></div>\n<div><p>Before the first semester had even come to an end, the four classes had already settled in a tense state of equilibrium.</p></div>\n<div><p>If all of their internal affairs were truly leaking out, then the strategies or information Horikita relayed to her classmates would inevitably find their way to Ayanokōji.</p></div>\n<div><p>Should that come to pass, they would be forced into a grueling, uphill battle in this Special Exam as well.</p></div>\n<div><p>And so, like a quiet, stubborn ember, that dark anxiety continued to smolder within her chest.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>Before the exhaustion from the Survival Game Special Exam could even fade, a new Special Exam was already upon them. As Mashima outlined the rules, Ryūen was already turning over several strategies in his mind.</p></div>\n<div><p>Ever since enrolling at this school, he had tackled every obstacle with absolute, unshakable confidence in his own judgment. Yet lately, no matter the time or situation, the phantom image of Ayanokōji seemed to constantly flicker at the back of his mind.</p></div>\n<div><p>Orthodox tactics, unconventional schemes, or even outright lawlessness that shattered the rules themselves, Ayanokōji would see right through all of it and still come out on top.</p></div>\n<div><p>Ryūen caught himself preemptively conceding defeat for a future that had yet to even unfold.</p></div>\n<div><p>If this were a mere battle of wits, he would have countless ways to counterattack. But Ayanokōji also possessed monstrous physical prowess. The memory of their shootout with paint guns flashed behind his eyes, prompting Ryūen to let out a quiet, sharp click of his tongue.</p></div>\n<div><p>“Is something the matter, Ryūen-shi? Did something displease you?”</p></div>\n<div><p>Having been placed in the same group, Kaneda seemed to have noticed that small sound. He called out to Ryūen, his gaze shifting toward the other members who were starting to gather.</p></div>\n<div><p>“I was just thinkin' about that bastard Ayanokōji. Don't sweat it.”</p></div>\n<div><p>“...So it has to do with Ayanokōji-shi. I see.”</p></div>\n<div><p>If Ayanokōji were left to his own devices, his group would easily secure first place in total tokens. Between that and the Special Reward for individual performance, Class C stood to gain a massive haul of up to 200 Class Points. On top of that, the influx of Private Points would grant them an even more dangerous degree of freedom.</p></div>\n<div><p>The comfortable advantage Ryūen's class had maintained up until now had completely vapourised during the first half of the uninhabited island exam. Even if official class demotions wouldn't take effect until the following month, they had already bled enough Class Points to provisionally plummet from Class B down to Class C. Worse yet, the gap between them and Ayanokōji's last-place class was now razor-thin.</p></div>\n<div><p>Simply put, it was a battle they absolutely could not afford to lose. Then again... the exact same thing could have been said about the last Special Exam.</p></div>\n<div><p><em>Just how is he supposed to outmaneuver Ayanokōji?</em></p></div>\n<div><p>Ayanokōji would undoubtedly rake in a massive haul of Front-side tokens. The real question was whether Ryūen could actually surpass that total. If outscoring him directly proved impossible, then beating him in the group rankings to secure the token multiplier was an absolute must. It was the bare minimum requirement for Ryūen to secure a victory.</p></div>\n<div><p>Then there was the expulsion penalty, triggered the moment a student's token count hit zero.</p></div>\n<div><p>No matter how monstrous Ayanokōji might be, he couldn't protect all his classmates twenty-four hours a day. If Ryūen could seize total control of their group, eliminating a single student from Class C would be entirely within his grasp.</p></div>\n<div><p>Letting his gaze drift across the area, Ryūen spotted Ayanokōji a short distance away. Yoshida was standing right beside him, chattering about something, but the boy didn't even register in Ryūen's field of vision.</p></div>\n<div><p>Ayanokōji was staring off in another direction, his eyes characteristically listless.</p></div>\n<div><p><em>“What the hell is that bastard staring at—”</em><span></span></p></div>\n<div><p>Just because Ayanokōji’s thoughts and emotions were hidden behind an impenetrable wall didn't mean Ryūen was going to give up trying to read him. To find a breakthrough, he had no choice but to strike like a serpent, sinking his fangs into even the most trivial of clues.</p></div>\n<div><p>And so, Ryūen traced the line of Ayanokōji's gaze.</p></div>\n<div><p>Normally, pinpointing exactly what someone was looking at from a distance was nearly impossible, especially with so many students clustered tightly together.</p></div>\n<div><p>Yet, Ryūen realized it instantly.</p></div>\n<div><p>Standing at the very end of Ayanokōji's unblinking gaze was the figure of Shiina Hiyori.<span></span></p></div>\n<div><p>“Ryūen-kun, it looks like we're in the same group.”</p></div>\n<div><p>A voice shattered his concentration just as he was trying to dissect Ayanokōji's thoughts.</p></div>\n<div><p>“What the hell do you want?”</p></div>\n<div><p>Whipping his sharp glare toward the intruder, Ryūen found Hirata Yōsuke standing right in front of him.</p></div>\n<div><p>“I'd like to make a request right off the bat,” Hirata said. “I don't want anyone in this group to be expelled.”</p></div>\n<div><p>“Hah, you've got a damn sharp nose,” Ryūen scoffed. “But that's one wish I ain't granting, Hirata. This is the perfect chance to kick someone out of your precious Class A, after all. Don't go thinkin' you're the only one sitting safe and sound.”</p></div>\n<div><p>“If you want to target me, I don't intend to stop you,” Hirata replied evenly. “But if you plan on expelling any other student from Class A... or from Class C, for that matter, then I'll have to make you listen.”</p></div>\n<div><p>Hirata had accurately read the atmosphere. He knew from Ryūen's gaze alone that Class A wasn't even on his radar; Ryūen was actively scouting for prey in Class C. That was exactly why Hirata's statement carried such a pointed implication.</p></div>\n<div><p>“I ain't got any reason to take orders on who I target,” Ryūen sneered. “Or what? You got something to offer in exchange for me lettin' the small fry off the hook?”</p></div>\n<div><p>“Well, I suppose I could become proactive about cooperating across class lines. You're a class leader, Ryūen-kun, which means a victory for our group is also a victory for Class B.”</p></div>\n<div><p>“I can't think of a single damn reason why a Class A guy like you would lend me a hand.”</p></div>\n<div><p>“It's simple, really. We can avoid producing any pointless expulsions. To me, that is the greatest merit.”</p></div>\n<div><p>“Seems like you've got the same pain-in-the-ass personality as Ichinose.”</p></div>\n<div><p>“I don't mind what you think of me. I just want to settle things peacefully.”</p></div>\n<div><p>Rather than jumping to a hasty conclusion, Ryūen paused to weigh the credibility of Hirata's words and demeanor, carefully considering which path would best serve his goals.</p></div>\n<div><p>Even if he did drain someone's tokens to zero and force an expulsion from Class C, it would amount to little more than petty harassment directed at Ayanokōji. It wouldn't directly impact his own class's standing or net them any points. Furthermore, one could argue that any student careless enough to let their tokens hit zero was just dead weight anyway. Going out of his way to eliminate them, especially at the cost of making an enemy out of Hirata, held very little strategic value.</p></div>\n<div><p>On the other hand, if Hirata's offer to cooperate was genuine, it would be a distinct advantage.</p></div>\n<div><p>Gazing at the other students gathering for their group, Hirata continued.</p></div>\n<div><p>“Given the severe penalties in this Special Exam, I know it wouldn't be impossible for you to set a trap and expel someone from Class C, Ryūen-kun. However, the only reason you're keeping the option to target a lower-ranked class open is to inflict damage on Ayanokōji-kun. But even if you could freely pick off one of the four people in our group... or rather, one person from Class C, it wouldn't actually affect him. You wouldn't be scoring a real point against him, would you?”</p></div>\n<div><p>It was a simple truth. If Ayanokōji were in the same group and Ryūen managed to crush his strategy in a direct confrontation before expelling a Class C student, it would undoubtedly be a massive victory. But under the current rules, there were inevitable blind spots where they couldn't observe one another. Scoring a cheap hit while the demon was away was nothing to brag about.</p></div>\n<div><p>“If anything, it might just prove that you're a small fry,” Hirata added.<span></span></p></div>\n<div><p>“Don't make me laugh.” Opting to put his final decision on hold, Ryūen threw the threat back at him. “You want to protect this makeshift group so badly you'd go out of your way to provoke me? Then you're gonna have to show it with your actions first.”</p></div>\n<div><p>He calculated that if Hirata could actually operate as an ally rather than an enemy in this Special Exam, his utility value would be immense.</p></div>\n<div><p>As if anticipating this demand from the very beginning, Hirata gave a single, firm nod.</p></div>\n<div><p>“I know.”</p></div>\n<div><p>From the corner of his eye, Ryūen caught sight of Hirata’s rigid expression— so unlike the image he had held of him until now that, for the first time, he sensed within him a faint trace of murderous intent.<span></span></p></div>",
    "3": "<div><p>It was already past five in the evening.</p></div>\n<div><p>Even with the late midsummer sunset, there was no denying that dusk was beginning to settle over the island.</p></div>\n<div><p>Yet, far from recovering from the fatigue of the Survival Game, some students stepped directly into another special exam, still carrying all of their accumulated exhaustion.</p></div>\n<div><p>As the time to begin the exam drew near, the supervisors finally made their appearance.</p></div>\n<div><p>“My name is Urushibara,” one of the adults announced calmly as he stepped forward. “I will be serving as the supervisor for Group 3. I look forward to working with all of you.”</p></div>\n<div><p>He was a man I had never seen before. After introducing himself, he immediately began checking attendance with efficient professionalism.</p></div>\n<div><p>Out of the ten groups, four had apparently been assigned third-year homeroom teachers as supervisors.</p></div>\n<div><p>Urushibara belonged to the remaining six.</p></div>\n<div><p>Once he confirmed that everyone was present, he continued without delay.</p></div>\n<div><p>“In this special exam, you will challenge a variety of tasks in order to acquire tokens. These tasks are divided into three separate categories, so please listen carefully while I explain. The three categories are: <em>Individual, Group, </em>and <em>Team.</em></p></div>\n<div><p>“<em>Individual </em>category is the simplest to understand. These are assignments issued to students on a one-on-one basis. You may compete individually against someone from your own group, or against a student from another group.</p></div>\n<div><p>“Next is the <em>Group </em>category. These involve all sixteen members currently assembled here working together to complete tasks issued by the school, or competing directly against entire other groups.</p></div>\n<div><p>“And finally, <em>Team. </em>This category further divides the group according to class affiliation. In other words, students from the same class within the group will form smaller units. Since these tasks contain more specialized rules, detailed explanations will be given at the time those assignments are actually conducted.”</p></div>\n<div><p>After confirming everyone was following along without issue, the supervisor, Urushibara continued.</p></div>\n<div><p>“Now then, next I’d like to explain how tokens will be awarded. However, before we proceed, each class within the group must first select one ‘representative.’”</p></div>\n<div><p>Up until now, neither Mashima-sensei’s explanation nor the written materials had mentioned anything about a representative.</p></div>\n<div><p>Hearing this unfamiliar role for the first time, the students exchanged puzzled glances.</p></div>\n<div><p>“Does becoming the representative come with any benefits?” Sonoda asked cautiously. “Actually… if there are disadvantages too, I’d rather hear about those now.”</p></div>\n<div><p>Though conscious of the students around him, Sonoda took the initiative and asked the question.</p></div>\n<div><p>“No,” Urushibara replied calmly. “There are no particular advantages or disadvantages attached to the role itself. However, the system has been designed so that any tokens earned by a class are awarded in bulk to that class’s representative.”</p></div>\n<div><p>A ripple of confusion spread through the group.</p></div>\n<div><p>“This will become relevant during the <em>Group </em>and <em>Team </em>categories,” he continued. “For example, let’s say Class A earns ten tokens through a Group or Team assignment. If Ike-kun has been selected as Class A’s representative, then all ten of those tokens will first be awarded directly to him.”</p></div>\n<div><p>Up until that moment, every student there, including me, had naturally assumed that any tokens earned would be distributed directly to the individuals who participated.</p></div>\n<div><p>That fundamental assumption had just been overturned completely.</p></div>\n<div><p>Whether tokens were granted individually or concentrated in the hands of a representative was an enormous difference.</p></div>\n<div><p>“Hah? What the hell is that supposed to mean?” Ibuki snapped immediately, realizing how abnormal this system was, she glared suspiciously at Urushibara. “So if they wanted to, the representative could just pocket all the tokens for themselves?”</p></div>\n<div><p>“The school has no intention of encouraging such behavior,” Urushibara answered evenly. “However, under the rules, it is technically possible. Contribution levels during assignments may vary depending on the task, after all, so classes may need to discuss internally how tokens should be distributed afterward. In that sense, the representative role may require a certain level of integrity.”</p></div>\n<div><p>The supervisor gave a seemingly reasonable explanation, but this setup had caused the risks to skyrocket.</p></div>\n<div><p>Exactly as Ibuki feared, placing all token management in the hands of a representative meant there was no guarantee that tokens would ever actually reach the students who earned them.</p></div>\n<div><p>Only the <em>Individual </em>category seemed exempt from this structure.</p></div>\n<div><p>But assuming the rewards across all three categories were distributed relatively evenly, then that meant a student could directly control only about one-third of the tokens tied to their own survival.</p></div>\n<div><p>“However, there is one important point you all need to understand regarding front-side and back-side tokens,” Urushibara continued.</p></div>\n<div><p>“Any token earned through the <em>Individual </em>category will, without exception, count as a front-side token. But tokens earned through the <em>Group</em> and <em>Team</em> categories work differently. The total number of tokens earned in a given assignment will first be divided according to the number of participants involved. For instance, let’s say a Group-category assignment awards forty-eight tokens. Since there are four classes represented within the group, each class representative would temporarily receive twelve tokens. But since the group itself contains sixteen students, only three of those twelve tokens per student would qualify as legitimate front-side tokens. That number becomes the upper limit recognized as a properly earned individual contribution. If a student were to receive four tokens in that situation, then one of those tokens would automatically become a back-side token. The right to possess front-side tokens does not expire and continues accumulating over time. As such, there is no disadvantage regarding <em>when </em>representatives choose to distribute tokens.”</p></div>\n<div><p>Putting it simply, the rules worked like this:</p></div>\n<div><hr></div>\n<div><p><strong>Token Distribution Rules</strong></p></div>\n<div><p>Categories of Assignments:</p></div>\n<div><p><em>Individual, Group &amp; Team</em></p></div>\n<div><p><strong>Individual Assignments:</strong></p></div>\n<div><p><em>All tokens earned personally are treated as front-side tokens.</em></p></div>\n<div><p><strong>Group / Team Assignments:</strong></p></div>\n<div><p><em>All earned tokens are first funneled through the class representative.</em></p></div>\n<div><p><em>The maximum number of front-side tokens that may be distributed is determined by:</em></p></div>\n<div><p><em>Total Tokens Earned ÷ Number of Participants</em></p></div>\n<div><p><em>Any tokens distributed beyond that limit automatically become back-side tokens.</em></p></div>\n<div><p><strong>Front-Side Token Rights:</strong></p></div>\n<div><p><em>Front-side eligibility accumulates over time.</em></p></div>\n<div><p><em>Representatives are free to choose the timing of distribution.</em></p></div>\n<div><hr></div>\n<div><p>“This rule seriously sucks.” Ibuki muttered under her breath.</p></div>\n<div><p>The distinction between front-side and back-side tokens likely existed to prevent representatives from simply monopolizing all earned tokens and charging toward the Special Reward themselves.</p></div>\n<div><p>But even with that safeguard in place, the privileges granted to representatives were enormous, far greater than what Urushibara’s casual tone implied.</p></div>\n<div><p>They controlled the distribution of tokens tied to Private Point rewards, and could potentially even avoid expulsion from finishing last.</p></div>\n<div><p>Urushibara also clarified that indivisible remainders created during division would simply be ignored.</p></div>\n<div><p>So even if 41 tokens were earned, dividing them among four people would still only create a front-side limit of 10 per class student. The extra one token wouldn’t increase the cap at all.</p></div>\n<div><p>“Now then,” Urushibara said, “please discuss among yourselves and decide who will act as representative for each class. If a decision cannot be reached within the allotted time, a vote will be held among the relevant team members.”</p></div>\n<div><p>“So they’re intentionally concentrating token control into one person’s hands,” Sanada said grimly. “From the students’ perspective, this rule feels almost entirely disadvantageous.”</p></div>\n<div><p>“Feels like they’re trying to provoke infighting,” Yoshida added.</p></div>\n<div><p>In truth, that was likely the case.</p></div>\n<div><p>At its core, the exam was testing whether classmates could trust one another. And whether the person receiving that trust could actually live up to it.</p></div>\n<div><p>“I don’t know who’s going to become the representative,” Ibuki said, narrowing her eyes, “but you’d better make sure you hand over my tokens properly.”</p></div>\n<div><p>The rule had already planted distrust in her. Without bothering to hide it, she turned that suspicion directly toward her own Class B teammates.</p></div>\n<div><p>Katsuragi answered her in his usual calm manner.</p></div>\n<div><p>“Generally speaking, it shouldn’t become a situation where someone tries to bring down another person. And to make sure we don’t choose that kind of person as representative, we should decide through a fair method.”</p></div>\n<div><p>In other words, a simple majority vote.</p></div>\n<div><p>It was the most straightforward and acceptable selection method.</p></div>\n<div><p>Meanwhile, other classes had begun moving in their own ways.</p></div>\n<div><p>“I’m thinking I’ll become the representative,” said a sharp, intimidating voice from within the Class A team. “That’s fine, right, Mii-chan?”</p></div>\n<div><p>The voice belonged to Shinohara.</p></div>\n<div><p>“A-Y-Yes, I don't mind that, but…”</p></div>\n<div><p>Mii-chan nodded, looking slightly bewildered, but not particularly inclined to reject Shinohara’s candidacy. She was not the type who liked standing out in front of others. If someone else was willing to take on the role, then perhaps she thought it was better to simply let them do it.</p></div>\n<div><p>“Mii-chan says she’s fine with it too,” Shinohara said, a confident smile appearing on her face. “So it looks like there’s no problem.”</p></div>\n<div><p>She acted as though one hesitant opinion had already secured the position for her.</p></div>\n<div><p>“Um,” Mii-chan said, instinctively speaking up as she realized her single vote was about to be treated as final, “shouldn’t we check with Ike-kun and Kushida-san too—”</p></div>\n<div><p>But Shinohara paid her no mind.</p></div>\n<div><p>In this special exam, falling to the bottom in token count was directly tied to expulsion. When one thought several moves ahead, there was still reason to question whether Shinohara or Ike, for that matter, should be chosen so easily as representative.</p></div>\n<div><p>Kushida likely understood that as well. Precisely because she did, she must have recognized that allowing herself to be swept along like Mii-chan would be nothing short of risky.</p></div>\n<div><p>The brief silence that fell over Class A was heavy and delicately long, one that couldn't easily blend into the surrounding conversations from the other classes.</p></div>\n<div><p>Before anyone could even voice opposition, the atmosphere had already shifted.</p></div>\n<div><p>Mii-chan glanced once between Kushida and Shinohara before quickly lowering her eyes again.</p></div>\n<div><p>Maybe she simply wasn’t used to being put in a position where her judgment mattered.</p></div>\n<div><p>Or maybe she understood exactly how much weight a single opinion carried right now.</p></div>\n<div><p>Either way, she showed no sign of answering decisively.</p></div>\n<div><p>Shinohara, meanwhile, didn’t miss even that tiny hesitation.</p></div>\n<div><p>Even before the discussion had properly concluded, she prioritized steering the momentum toward herself.</p></div>\n<div><p>She held her gaze without wavering, applying quiet pressure that left little room to escape.</p></div>\n<div><p>Riding that wave of momentum she shifted her attention to Kushida without hesitation.</p></div>\n<div><p>“So what is it, Kushida-san?” Shinohara asked. “You don’t want me as the representative? Would it be inconvenient for you if I took the role?”</p></div>\n<div><p>It was phrased like a question, but in reality the range of acceptable answers had already been narrowed down.</p></div>\n<div><p>If Kushida answered yes, friction would immediately erupt.</p></div>\n<div><p>If she answered no, then she would effectively be conceding the position.</p></div>\n<div><p>By forcing that binary choice onto her, Shinohara was clearly trying to seize control of the conversation from the get go.</p></div>\n<div><p>“Um… well… it’s not that there’d be any inconvenience or anything,” Kushida replied carefully, “but actually, I was thinking about volunteering too…”</p></div>\n<div><p>She asserted her intentions in a modest, yet firm manner.</p></div>\n<div><p>However, upon hearing those words, Shinohara's expression stiffened in apparent dissatisfaction.</p></div>\n<div><p>“Why?” she asked. “Is it because you don’t trust me?”</p></div>\n<div><p>“No, it’s not like that,” Kushida answered without missing a beat. “ I just intended to run from the very beginning.\"</p></div>\n<div><p>“Hmm?” Shinohara let out a small laugh. “Because honestly, it kinda feels like I’m not being trusted here.”</p></div>\n<div><p>Kushida faltered for only a moment beneath the pressure.</p></div>\n<div><p>Even so, she still pushed back.</p></div>\n<div><p>“But if you put it that way…” she answered carefully, “doesn’t that also mean <em>you </em>don’t trust<em> me</em>, Shinohara-san?”</p></div>\n<div><p>Though Kushida seemed somewhat bewildered and overwhelmed by her intensity, she still didn't stop arguing back.</p></div>\n<div><p>“Ehh? It’s not like that though—”</p></div>\n<div><p>Shinohara smiled faintly, almost amused.</p></div>\n<div><p>Then her voice rose slightly.</p></div>\n<div><p>“But Kushida-san… do you seriously think people can trust you unconditionally?”</p></div>\n<div><p>The surrounding groups had not started paying attention yet.</p></div>\n<div><p>But if the conversation escalated any further, it would inevitably draw eyes and ears from nearby.</p></div>\n<div><p>“I… I do try my best to earn people’s trust,” Kushida answered. “That’s exactly why I thought it’d be better not to place an unnecessary burden on you, Shinohara-san.”</p></div>\n<div><p>With other classes in the mix, Kushida had no choice but to continue playing the role of the usual cheerful, considerate Kushida.</p></div>\n<div><p>And Shinohara understood that perfectly.</p></div>\n<div><p>Which was exactly why she could afford to press forward so aggressively.</p></div>\n<div><p>“Burden? What do you mean by that?”</p></div>\n<div><p>“Managing all the tokens sounds like a hassle,” Kushida explained gently. “Even if it’s called a representative, it’s basically just becoming the class errand runner. I thought it might be better if I handled it instead.”</p></div>\n<div><p>“It’s not a hassle at all,” Shinohara shot back immediately. “So don’t worry about me, Kushida-san. Just leave it to me.”</p></div>\n<div><p>Then Kushida turned slightly.</p></div>\n<div><p>“Mii-chan… what do you think?”</p></div>\n<div><p>The question sounded almost like a plea for help.</p></div>\n<div><p>But before Mii-chan, caught painfully between the two of them, could even open her mouth, Shinohara’s expression darkened with irritation.</p></div>\n<div><p>“You heard her agree to leave it to me, didn’t you?” Shinohara pressed immediately. “So why are you asking again? You really <em>don’t </em>trust me after all, do you?”</p></div>\n<div><p>“No, that’s not it,” Kushida answered gently. “I just wanted to properly confirm everyone’s opinion…”</p></div>\n<div><p>“Then why don’t you ask Kanji too?”</p></div>\n<div><p>Shinohara gave a small snort as she turned toward Ike, utterly convinced he would side with her.</p></div>\n<div><p>“Mm… Ike-kun, what do you think?”</p></div>\n<div><p>Closing the distance slightly, Kushida looked up at him with an almost pleading gaze.</p></div>\n<div><p>“Huh? Well, I mean…”</p></div>\n<div><p>The moment Kushida turned those eyes on him, Ike’s composure vanished. Even though everyone in the class had seen her true nature, Kushida was still an angel on the surface. When she looked at him as though she were relying on him, his cheeks reddened almost instantly.</p></div>\n<div><p>“Well, Kikyō-cha—uh, I mean Kushida wouldn’t be bad at all either, yeah.”</p></div>\n<div><p>“Hey, Kanji…?”</p></div>\n<div><p>Shinohara’s mood soured at once. Apparently displeased by his unexpected reaction, she grabbed his left ear and pulled hard.</p></div>\n<div><p>\"Ow, ow-ow-ow! That hurts, Satsuki!\"</p></div>\n<div><p>“Tell me honestly.” Shinohara’s voice was sweet only in shape. “Between me and Kushida-san, who is better suited to be representative?”</p></div>\n<div><p>“Of course, of course!”</p></div>\n<div><p>Still crying out in pain, Ike hurriedly corrected course.</p></div>\n<div><p>\"I-It's safe to just leave it to Satsuki!\"</p></div>\n<div><p>Subjected to Shinohara’s openly suspicious stare, Ike chose the answer that let him escape with the least damage.</p></div>\n<div><p>“So there you have it,” Shinohara said, turning back to Kushida with a satisfied look. “That’s fine, right, Kushida-san?”</p></div>\n<div><p>“Understood,” Kushida said after a small pause. “Yeah. If everyone is fine with that, then I’m fine with it too.”</p></div>\n<div><p>She likely harboured immense dissatisfaction.</p></div>\n<div><p>But Shinohara and Ike already controlled two votes. Even if Kushida persisted and somehow managed to pull Mii-chan to her side, the result would only be a split vote, and the representative still would not be decided. Worse, after rejecting Shinohara this strongly, provoking her any further would be a poor move.</p></div>\n<div><p>Kushida had no choice but to step back.</p></div>\n<div><p>Of course, at this point, neither Shinohara nor Ike were likely planning to cheat Kushida or Mii-chan through token management. Their intentions were probably still ordinary enough.</p></div>\n<div><p>But that was only because they had not yet been pushed into a corner.</p></div>\n<div><p>If, from here on, they failed to increase their tokens as planned, or if they began losing them, then the authority Shinohara held as representative could grow stronger, and more difficult to control.</p></div>\n<div><p>Once again, it became clear just how important the role of representative truly was.</p></div>\n<div><p>There were probably almost no current third-years who could not see at least that much.</p></div>\n<div><p>And that was precisely why Kushida, more than anyone, would have to move with extreme caution from this point forward.</p></div>\n<div><p>“Looks like they ended up choosing Shinohara over there,” Yoshida murmured after quietly listening in on the exchange. “Well, if you’re someone at risk of expulsion, wanting to become the representative is only natural. On the other hand, for someone like Wang or Kushida, this has to be a headache.”</p></div>\n<div><p>His analysis was calm and matter-of-fact.</p></div>\n<div><p>“So what should <em>we </em>do for now?” Yoshida continued, stepping closer and lowering his voice. “We’re making you the representative, right?”</p></div>\n<div><p>“You’re willing to follow my lead?”</p></div>\n<div><p>“Of course.” Yoshida answered without hesitation. “I was sweating a little during the Survival Game Special Exam when it looked like we might lose, but in the end we finished exactly where you planned, second place. Hard to complain about that.”</p></div>\n<div><p>He shrugged lightly.</p></div>\n<div><p>“And besides, you’re the leader for this exam. Ideally we want this group taking first place.”</p></div>\n<div><p>Standing beside him, Sanada nodded immediately in agreement.</p></div>\n<div><p>“Then I presume that makes me the Representative, yes?” Morishita concluded.<span></span></p></div>\n<div><p>“You can ignore this one,” Yoshida said bluntly, jerking a thumb toward her. “She’s not the type to step forward anyway.”</p></div>\n<div><p>Morishita stood with her arms folded, nodding repeatedly to herself as though she alone had reached some profound conclusion.</p></div>\n<div><p>“I believe Morishita-san understands as well,” Sanada added, smoothing over the moment with calm politeness, “that among us, entrusting this to Ayanokōji-kun is the best option.”</p></div>\n<div><p>It felt like they were deliberately putting me on a pedestal, but I didn't pay it much mind.</p></div>\n<div><p>“One final confirmation,” I said. “You’re really fine with leaving this to me? Once I become the representative, I’ll be able to distribute the tokens we earn however I like. I might act to protect myself.”</p></div>\n<div><p>Yoshida looked at me as if the answer was obvious.</p></div>\n<div><p>“You're the weirdo who willingly dropped down from Class A, right, Ayanokōji? If you pull a stunt like betraying us just to save yourself, you wouldn't be able to stay as the class leader anymore, at the very least. That's why we trust you, or rather, your position which won't allow for such selfishness.”</p></div>\n<div><p>That was Yoshida’s reasoning for accepting me as representative.</p></div>\n<div><p>Sanada nodded again, showing that he agreed.</p></div>\n<div><p>Their attitude did not come from blind faith. They had already resolved themselves to the fact that if they could not place complete trust in me, the class would never rise again.</p></div>\n<div><p>“I, for one, certainly do not trust you,” Morishita declared. “But very well, let us treat this as a test to see if you are truly fit to reign over our class.”</p></div>\n<div><p>“Understood,” I said. “If Yoshida and Sanada are willing to place that responsibility in my hands, then I’ll fulfill the role properly.”</p></div>\n<div><p>I informed Urushibara that I would be serving as Class C’s representative, then waited for the remaining teams to finish making their decisions.</p></div>\n<div><p>In the end, Class A selected Shinohara as representative.</p></div>\n<div><p>Class B settled on Katsuragi. Ibuki looked far from pleased with the result, but since the remaining two supported him, the decision was effectively made.</p></div>\n<div><p>As for Class D, Amikura assumed the representative role without the slightest dispute.</p></div>\n<div><p>Compared to the distorted power balance festering inside Class A, the other selections were probably more or less reasonable.</p></div>\n<div><p>“So you <em>are </em>going to divide the tokens fairly, right?” Ibuki demanded immediately, glaring at Katsuragi.</p></div>\n<div><p>“Of course,” Katsuragi replied calmly. “Although I cannot guarantee that my definition of fairness matches yours.”</p></div>\n<div><p>“Hah? What’s <em>that </em>supposed to mean?”</p></div>\n<div><p>“This is still a special exam,” he answered evenly. “I am merely the one entrusted with managing the class’s collective tokens. I intend to distribute them fairly according to contribution. Those who produce results will receive rewards appropriate to their efforts. Those who hold the group back will receive only the minimum necessary.”</p></div>\n<div><p>He held Ibuki’s gaze without flinching.</p></div>\n<div><p>“If you want enough tokens to avoid expulsion, then contribute to the class.”</p></div>\n<div><p>“Tch… fine.”</p></div>\n<div><p>A very Katsuragi-like policy.</p></div>\n<div><p>His equality was not equal shares for all. It was fairness measured by evaluation, with token distribution tied directly to contribution. Whether one liked it or not, the logic was consistent.</p></div>\n<div><p>Amikura, on the other hand, seemed to be taking the opposite approach.</p></div>\n<div><p>For her team, performance was irrelevant. Any tokens earned by the four of them would be divided evenly among the four.</p></div>\n<div><p>That, too, was a form of equality.</p></div>\n<div><p>Because there was already trust between them, and because each student’s abilities were relatively well balanced, there was likely no room for conflict to arise.</p></div>\n<div><p>Then there was Shinohara, the representative of Class A.</p></div>\n<div><p>On the surface, her stance was the same as Amikura’s: equal distribution among all members. But the conditions beneath that statement were entirely different. In terms of ability, Kushida and Mii-chan clearly held a far greater advantage over Shinohara.</p></div>\n<div><p>In other words, Shinohara was using the authority of the representative role to create a version of equality that favored her own side.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>With the representatives from all four classes assembled, the supervisor stepped forward to address us.</p></div>\n<div><p>“Now then, without further ado, we will have you begin the individual category tasks,” he announced. “You have a maximum of sixty minutes to deliberate and decide by majority vote where this group will travel first, choosing from a list of candidate locations. Once everyone agrees to proceed, you will cast your vote via your smartwatches and then head out to the winning destination,” he paused.</p></div>\n<div><p>“As for the rewards: any student who votes for the destination with the most votes will receive one token. If the vote is unanimous, everyone will receive two. Those who vote for a location other than the majority will receive three tokens. Finally, in the event that a destination receives exactly one vote, that lone voter will be rewarded with five tokens.”</p></div>\n<div><p>So, our first task was simply to decide Group 3’s destination.</p></div>\n<div><p>“A word of warning before you begin your discussions,” the supervisor continued. “If there is a tie for the most votes, meaning multiple locations receive the highest number of votes, the students who voted for those tied locations will receive zero tokens. In such a scenario, we will randomly select your destination from among the tied options.”</p></div>\n<div><p>In short, it was a system that guaranteed a payout of tokens for everyone, provided there wasn't a tie for first place.</p></div>\n<div><p>“We will not disclose who voted for which location under any circumstances. Furthermore, showing your watch’s screen to others while voting is strictly prohibited. Please be aware that any such violations will incur a separate penalty resulting in the loss of tokens.”</p></div>\n<div><p>If we knew who was voting for what in real time, coordinating our choices would be far too easy. This strict anonymity was likely a necessary measure to prevent exactly that.</p></div>\n<div><p>Having briskly wrapped up his explanation, Urushibara, our assigned supervisor, read the list of candidate destinations aloud.</p></div>\n<div><p>“There are five candidate locations for your first destination: B9, E12, F14, I10, and I13. Regardless of which area you choose, the contents of your upcoming tasks will remain exactly the same. However, any time spent traveling to your next destination is simply time wasted, so please keep that in mind.”</p></div>\n<div><p>Sanada unfolded the map provided with our materials, immediately checking the coordinates.</p></div>\n<div><p>The available options were scattered across the grid, ranging from relatively close spots to those a fair distance away. Some even looked like they would require considerable effort to reach.</p></div>\n<div><p>“I will now start the timer,” Urushibara said, checking his smartwatch without a moment’s delay. “You are free to begin your discussion.”</p></div>\n<div><p>Reacting naturally, our group of sixteen shifted into a circle so that we could all see each other’s faces.</p></div>\n<div><p>“It's obvious a nearby place is best for this. The tasks won't change, either,” Sonoda from Class B muttered, sounding more like he was thinking out loud than asking a question.</p></div>\n<div><p>Catching his words, Ike immediately agreed. “True. Even the teacher—er, the supervisor, just said that travel time is a waste.”</p></div>\n<div><p>The assertion that closer meant easier was typical of Ike, who despised anything troublesome.<span></span></p></div>\n<div><p>“So we all just vote for the closest area and call it a day? It'd be a quick discussion, and we'd all get two tokens,” Minamikata chimed in.</p></div>\n<div><p>A unanimous vote for the closest location. It was the first and most obvious choice that came to mind.</p></div>\n<div><p>While the guarantee that the upcoming task wouldn't change was certainly a solid deciding factor, if we chose a nearby destination based on that alone, there would be no need for this discussion at all.</p></div>\n<div><p>The school had gone out of its way to give us a lengthy sixty-minute deliberation period. There had to be a meaning behind it, or rather, making us <em>think </em>there was a deeper meaning was likely exactly what the school was aiming for.</p></div>\n<div><p>“Isn't blindly voting for the closest area a bit too simplistic?” Yoshida argued. “There's probably more to this than meets the eye.”</p></div>\n<div><p>If travel distance was the only difference between the options, no one would ever vote for a faraway spot. Suspecting a trap lay hidden behind such an obvious answer, Yoshida spoke up to rein them in.</p></div>\n<div><p>“I have to agree,” Katsuragi said, casting a brief glance at Ike and Sonoda. “We should thoroughly examine the other areas first.”</p></div>\n<div><p>“But... Urushibara-san said the destination and the tasks aren't connected...” Morofuji muttered from her spot beside Katsuragi.</p></div>\n<div><p>“In that case, we may need to consider factors outside of the tasks themselves,” Katsuragi replied. “We cannot blindly proceed without first verifying which destination will provide the greatest benefit to our group.”</p></div>\n<div><p>“Isn't that just a waste of time?” Sumida retorted. “This task is centered around the exchange of tokens. I think ‘closer is better’ is a perfectly fine answer.”</p></div>\n<div><p>It seemed the discussion was already beginning to fray.</p></div>\n<div><p>It was supposed to be a simple vote to decide our next destination, yet reaching a consensus wasn't going to be easy.</p></div>\n<div><p>“The supervisor called this an individual battle, didn’t he? Does that mean we’re supposed to outmaneuver each other through the voting process?”</p></div>\n<div><p>Sanada turned to me as he asked the question.</p></div>\n<div><p>“That’s undoubtedly one of the core mechanics, yeah,” I replied.</p></div>\n<div><p>“A unanimous vote yields a solid reward of two tokens, but it’s certainly not the highest payout,” Sanada noted.</p></div>\n<div><p>It was a natural progression for the majority of the students to favor a nearby location as their destination. Consequently, the votes were bound to concentrate there. While a unanimous choice would distribute tokens equally among all sixteen participants, a calculated betrayal guaranteed a far more lucrative payout for the defector. To make matters worse, such a betrayal would slash the payout of the majority voters down to a single token. And if multiple defectors emerged, it opened the door for opportunists to secure three or five tokens under the safety of complete anonymity.</p></div>\n<div><p>“It’s a simple but troublesome task,” Sonoda muttered again, several students nodding in agreement. “Our overall motives align, but the reward system actively discourages us from cooperating.”</p></div>\n<div><p>The optimal strategy was to avoid voting for the desired destination yourself, while persuading others into voting for it instead.</p></div>\n<div><p>“Wait, isn’t this impossible?” someone argued. “Nobody is going to want to waste their vote on the closest place.”</p></div>\n<div><p>Exactly. Everyone agreed that a shorter distance was better. But if prioritizing that convenience meant settling for just one token, people would inevitably be tempted to secure three or five tokens instead, not caring if they had to walk further as a result.</p></div>\n<div><p>“But... if everyone thinks like that, all the votes will end up going to the distant places instead, right?” Mii-chan pointed out, having apparently foreseen the logical conclusion of that train of thought.</p></div>\n<div><p>“If we all avoid the shortest route and vote for the distant ones, then a distant location will get the most votes? Man, that won't work either.”</p></div>\n<div><p>In a space where friend and foe were jumbled together, the students exchanged probing glances, sizing each other up.</p></div>\n<div><p>An uncomfortable silence fell over the group. Ten or twenty seconds passed, and just as it seemed the heavy atmosphere would drag on, Katsuragi quietly broke the silence.</p></div>\n<div><p>“Engaging in a clumsy battle of wits will only breed suspicion,” he said calmly. “If we end up casting our votes blindly, then just as Wang pointed out, we run the risk of earning no tokens while being forced to march a long distance. The simplest way to handle this is to keep our discussion to a minimum, prioritize cooperation above all else, and unanimously vote for the closest area. We might not maximize our token earnings, but it guarantees an outcome, and a travel distance, that everyone can be satisfied with.”</p></div>\n<div><p>Naturally, the majority of the group wasn’t going to just nod along and agree to Katsuragi’s proposal immediately. Katsuragi himself was fully aware of that, of course. It was safe to say he had simply offered a baseline argument to kickstart the real discussion.</p></div>\n<div><p>“That might be true, but in order to guarantee the most votes, we need at least nine people to vote for the same spot,” Ike argued. “Are you seriously suggesting we just hand over three or five tokens to the remaining seven people?”</p></div>\n<div><p>“Tokens can be transferred,” Katsuragi countered calmly. “We could agree to pool our winnings and distribute them evenly afterward.”</p></div>\n<div><p>“You’ve gotta be kidding me,” Ike shot back. “If tokens end up with someone from another class, there’s zero guarantee they’ll actually hand them over. The voting is strictly anonymous, which means someone is definitely going to pull a fast one on us. Take Ayanokōji, for example... Yeah, someone exactly like Ayanokōji!” he continued, turning his gaze toward me. “You’re absolutely gunning for the five-token payout, aren’t you?”<span></span></p></div>\n<div><p>Just as Katsuragi had predicted, his proposal acted as the spark that ignited a flurry of opposition, with Ike fiercely leading the charge.</p></div>\n<div><p>Since he was glaring in my direction and calling me out by name, I met his gaze, if only to acknowledge him.</p></div>\n<div><p>“Seems like your attitude has gotten even worse since you betrayed our class,” Ike sneered. “I mean, anyone who transfers from Class A to a lower class just because they think they’re a little smart is crazy to begin with.”</p></div>\n<div><p>Ever since our groups merged, Ike hadn’t stopped complaining about my attitude. I was perfectly fine letting it slide without offering a rebuttal, but Katsuragi stepped in to answer on my behalf.</p></div>\n<div><p>“You are free to think whatever you want about transferring to a lower class,” Katsuragi said, crossing his arms and narrowing his eyes sharply. “But if stepping down to a lower class makes someone crazy, then I suppose I am crazy as well.”</p></div>\n<div><p>Realizing he had just caught Katsuragi in the crossfire, Ike awkwardly averted his gaze.</p></div>\n<div><p>The fallout from this exchange didn't stop at just the two of them; it cast a faintly heavy atmosphere over the students from Class C. Yoshida and the others used to be Katsuragi's allies, and now that he was their enemy after a long series of twists and turns, they likely harbored some complicated feelings about the matter.</p></div>\n<div><p>Unable to bear the suddenly tense mood, Moriyama from Class D stepped in to mediate. “Let's all calm down for a second. I think cooperating like Katsuragi suggested is a valid option. It's the most straightforward approach, right?”</p></div>\n<div><p>“But isn't the whole problem that we <em>can't </em>do that?” Shinohara retorted. “Neither Kanji nor I want to throw our votes away on the most popular choice.”</p></div>\n<div><p>“Yeah, exactly!” Ike chimed in, vehemently backing up her protest.</p></div>\n<div><p>“Of course, anyone would feel that way,” Sumida reasoned. “But if we just dig our heels in, we'll get nowhere. We need to figure out where we can compromise and find a balanced voting strategy first. There might be a solution we can all accept.”</p></div>\n<div><p>“Sumida's right,” another agreed. “The total number of tokens we get as a group undoubtedly changes depending on how we vote. The real question is, what kind of voting patterns are actually on the table?”</p></div>\n<div><p>Assuming we could control everyone's votes, the group was starting to realize that the distribution method directly impacted our total payout. Seeing this, I lightly raised my hand before speaking up.</p></div>\n<div><p>“A simple, unanimous vote yields two tokens each,” I explained. “That’s a total payout of 32 tokens. However, if we intentionally scatter our votes, there are six different patterns that yield the absolute maximum payout of 40 tokens. For example, Pattern 1 would be 7 votes, 6 votes, and three 1-vote destinations. Pattern 2 would be 6 votes, 5 votes, 3 votes, and two 1-vote destinations, and so on. Regardless of which of the six patterns we use, the maximum yield remains capped at 40.”</p></div>\n<div><p>I paused for a moment before delivering the optimal strategy. “Out of all six patterns, the easiest one to coordinate is a 4-3-3-3-3 split. We send exactly one person from each of the four classes to vote for the top destination, giving it a winning total of 4 votes. The remaining twelve people divide into groups of three and vote for the other four destinations.”</p></div>\n<div><p>That would yield eight more tokens than a unanimous vote, which wasn't a bad deal for any of the classes involved.</p></div>\n<div><p>“The only drawback,” I continued, “is that dividing 40 tokens by 16 people equals 2.5, meaning an even distribution on an individual level is impossible. However, we <em>can </em>divide the class cuts equally, giving each of the four classes exactly 10 tokens to distribute amongst themselves.”</p></div>\n<div><p>Purely in terms of efficiency, this was the absolute optimal solution. Of course, regardless of the pattern, the hurdle of actually pulling it off was anything but low.</p></div>\n<div><p>“You're incredibly fast at calculating all that, Ayanokōji,” Katsuragi said, clearly impressed. A few other students agreed, clapping their hands in an exaggerated show of admiration.</p></div>\n<div><p>“You didn't have to go out of your way to explain every little detail. I could've figured out the patterns right away,” Ike muttered defensively. “No need to act so smug just because you can do a little math in your head. I mean, are you even sure that's right? Are you really that confident?”<span></span></p></div>\n<div><p>“Yeah. The math is correct,” I said flatly.</p></div>\n<div><p>“...Listen to him, so completely sure of himself. It'll be damn embarrassing if you're wrong after all that.” Ike clearly wanted me to be wrong. He started counting on his fingers, but almost immediately abandoned the effort.</p></div>\n<div><p>“Honestly, you <em>do </em>sound pretty arrogant, Ayanokōji-kun,” Shinohara chimed in, rushing to defend Ike. Her tone shifted from angry to exasperated. “You never used to give off this kind of impression. You always just seemed... harmless. Did becoming a leader change you, or did you just stop hiding your true colors?”</p></div>\n<div><p>The rest of the group looked back and forth between me and Shinohara’s clique.</p></div>\n<div><p>The old me would’ve preferred not to rock the boat; I would have likely just ignored her remarks and let it slide. But this time, I decided to take the bait.<span></span></p></div>\n<div><p>“Maybe so,” I said flatly. “My previous class was quite uncomfortable, after all.”</p></div>\n<div><p>“Wow, he actually just said that out loud. You really do have a terrible attitude,” Shinohara scoffed, her face twisting in disgust.</p></div>\n<div><p>Faced with my unyielding, unapologetic stance, it wasn’t just Mii-chan and Kushida who looked rattled; even my new classmates, like Yoshida, showed obvious signs of agitation.</p></div>\n<div><p>“Hey, shouldn't you dial it back a little?” Yoshida whispered, his face twitching slightly.</p></div>\n<div><p>“There's no need to worry. I'm just speaking my mind.”</p></div>\n<div><p>“No, man, that's exactly the problem...” he trailed off.</p></div>\n<div><p>The hostile atmosphere lingered in the air, thick and unresolved. But Katsuragi, who had likely been quietly verifying my math in his head the entire time, gave a deep nod and stepped back into the conversation.</p></div>\n<div><p>“It seems his calculations are indeed correct,” Katsuragi announced. “Splitting the five destinations into a 4-3-3-3-3 pattern is a solid strategy. We cannot avoid competing within the group eventually, but if there's a way for everyone to earn tokens at maximum efficiency right now, I see great merit in taking advantage of it. The most important thing is for each of us to increase our token count and avoid dropping to the bottom of the school year.”</p></div>\n<div><p>Katsuragi had fully understood the core policy of ‘earn while you can’ and actively embraced it.</p></div>\n<div><p>“I guess I agree too,” Sonoda said. “The only reason someone would break ranks and try to outsmart everyone else is to squeeze out an extra token or two, right? But honestly, I don’t think the risk is worth it. Splitting the votes would only increase the chances of a tie. Once you realize that, even someone planning to defect would understand that securing a reliable ten tokens for the class is the smarter choice, wouldn’t they?”</p></div>\n<div><p>Clearly eager to maintain harmony, Sonoda once again expressed his support for cooperation. The true brilliance of this 4-3-3-3-3 strategy lay in the fact that votes would be cast for every single destination. Because every location would receive a minimum of three votes, even if one person decided to play the traitor, it would be mathematically impossible for them to snatch up the five-token reward reserved for a solo vote. And even if a group of traitors wanted to coordinate an ambush, pulling off a flawless conspiracy using nothing but eye contact in this mixed group would be a Herculean task.</p></div>\n<div><p>“I still don't like it,” Ike grumbled. “Just going along with a plan pushed by Ayanokōji rubs me the wrong way.”</p></div>\n<div><p>“There is no need for baseless suspicion,” Katsuragi replied firmly. “I ran the numbers several times myself, and Ayanokōji's pattern and projected results are entirely correct. Rather than complain, you should look at the bright side: by providing us with a conclusion faster, he has saved us valuable time that we can now allocate to discussing the actual execution.”</p></div>\n<div><p>The realization that this distribution method offered the highest efficiency had finally sunk in for everyone. However, understanding the logic and agreeing to execute it were two different things.</p></div>\n<div><p>“Yeah, I fundamentally agree. Don't you?”</p></div>\n<div><p>“It's a hundred times better than voting blindly without a plan. I'm in.”</p></div>\n<div><p>As expected, Class D was straightforward; they weren't the type to oppose a proposal that clearly benefited the majority.</p></div>\n<div><p>Seizing the moment, I turned my gaze toward Yoshida and Sanada. “Now that you've heard the discussion so far, have you made up your minds?”</p></div>\n<div><p>“If I had to choose, I'm in favor of the four classes getting ten tokens each,” Yoshida replied. “If our opinions split, we risk getting zero tokens in the worst-case scenario. Plus, this setup seems like a solid deterrent against betrayal, right?”</p></div>\n<div><p>Following Yoshida's lead, the two of them offered no resistance, clearly leaning toward the most efficient strategy. Curiously, Morishita, who was usually loud enough to be a nuisance, remained completely silent.</p></div>\n<div><p>Having secured Class C's agreement with a light nod, Katsuragi next turned to his own Class B to solicit their opinions.</p></div>\n<div><p>“I-I feel like it's better than aiming for an uncertain unanimous vote...”</p></div>\n<div><p>“As long as it guarantees me tokens, I'm fine with it,” Ibuki added bluntly.</p></div>\n<div><p>While perhaps not as enthusiastic as Class D or C, Ibuki and the others expressed a relatively agreeable stance.</p></div>\n<div><p>Now, the only ones left were Class A, which included Ike and Shinohara, who had been the most vocal in their opposition.</p></div>\n<div><p>“I’d like to hear Kushida and Mii-chan’s opinions on the matter, too,” I said.</p></div>\n<div><p>“H-hey, hold on a second,” Ike stammered, stepping forward. “Between you ignoring our greetings earlier and now this, you’re purposely leaving Satsuki and me out of the loop, aren’t you?”</p></div>\n<div><p>“It’s for the exact same reason I didn't greet you,” I replied flatly. “My bad, but I have no desire to seek opinions from either of you.”</p></div>\n<div><p>“Are you seriously saying that right now, Ayanokōji?” Ike snapped. “You know this is a group task, right? Stop doing things that are just gonna cause a split among us! Weren't we just talking about everyone cooperating?”</p></div>\n<div><p>It was a perfectly sound argument that left little room for rebuttal, and the rest of the group began to show obvious sympathy for Ike's position.</p></div>\n<div><p>Seeing Ike clench his fists in agitation, Shinohara gently grasped his hand, mindful of the stares from the rest of the group.</p></div>\n<div><p>“Kanji, let's be the adults here,” she urged softly. “I was definitely hurt when he ignored us earlier, but you said it yourself: this is a group battle, right? Fighting over pointless things will only drag us down.”</p></div>\n<div><p>“But still...!”</p></div>\n<div><p>“I got a little worked up too, but wasn't it partly your fault, Kanji? You were the one provoking Ayanokōji-kun, saying he couldn't be trusted. Am I wrong?”</p></div>\n<div><p>“...Well... I guess...”</p></div>\n<div><p>Though his anger hadn't completely subsided, Ike's resentment softened slightly at Shinohara's gentle reprimand.</p></div>\n<div><p>“...Yeah, you're right. ...I get it.”</p></div>\n<div><p>Forcing himself to swallow his pride by saying it aloud, Ike slowly unclenched his fists. He gave a stiff, slight bow of his head and desperately pasted a bright expression onto his face.</p></div>\n<div><p>“Earlier, how should I put it... look, my bad for saying things that made it sound like I doubted you. Of course you'd get mad over that... For now, I agree that making sure all the classes get an equal share of tokens is the way to go. So, as a way to test our trust in each other, let's just try to get along this once.”</p></div>\n<div><p>Having regained his composure, Ike extended an olive branch. Shinohara nodded, clearly ready to second his attempt at making peace.</p></div>\n<div><p>Looking back to when we first enrolled, it was clear that Ike and Shinohara had grown mentally, albeit unsteadily. I had noticed it even during the greeting stage. To think they would brush off my blatant rudeness and actively try to compromise with me again. Moreover, it wasn't just surface-level posturing; even if they had to force it, they genuinely seemed to be convincing themselves to let bygones be bygones for the sake of the group.</p></div>\n<div><p>I could sense a palpable wave of welcome relief from Yoshida and my other classmates standing beside me.</p></div>\n<div><p>I turned my gaze toward Ike and Shinohara to give them my answer.</p></div>\n<div><p>“I agree with aligning our voting intentions,” I said coldly. “But unfortunately, I simply cannot trust either of you.”</p></div>\n<div><p>Without a shred of hesitation, I shattered the fragile peace their goodwill had just created, freezing the atmosphere instantly.</p></div>\n<div><p>“Wha—”</p></div>\n<div><p>Before Ike even had a chance to react, the tentative smile on Shinohara's face hardened into a mask of shock. The rest of the group stared at me, their initial astonishment quickly morphing into blatant dissatisfaction at my unapologetic hostility.</p></div>\n<div><p>“Ayanokōji, I feel that is going a bit too far,” Katsuragi interjected. “I don't know what happened between you as former classmates, but there is absolutely no merit in making an enemy of Class A here.”</p></div>\n<div><p>“He's right, Ayanokōji,” another student agreed. “No matter how you look at it, you're the one in the wrong here. It's just plain immature.”</p></div>\n<div><p>“I have no intention of making enemies of them,” I replied calmly. “However, if we want this discussion to proceed smoothly, it's meaningless unless the right people step forward. As long as Shinohara and Ike uselessly intrude as the representatives of Class A, any discussion we hold is just a waste of time. For a task focused on dialogue, the natural choice is to have Kushida lead the talks, with Mii-chan advising her as an assistant. If we take that approach, we can trust each other and progress smoothly.”</p></div>\n<div><p>My implication was clear: those two needed to know their place and step back like the supporting characters they were.<span></span></p></div>\n<div><p>“You... are seriously pissing me off, Ayanokōji!”</p></div>\n<div><p>Ike once again clenched his fists, ready to lunge forward, but Shinohara tightly grabbed his shoulder to hold him back.</p></div>\n<div><p>Unlike earlier, however, Shinohara looked as though she had reached the absolute limit of her patience.</p></div>\n<div><p>“What the hell is that supposed to mean?” she demanded, her voice trembling. “Are you saying we shouldn't even be allowed to speak? Isn't that completely unfair? Did we say something so horrible that you have to treat us like this?”</p></div>\n<div><p>“I... well, I also think Ayanokōji-kun's remarks were entirely out of line,” said Sanada, stepping in front of me, with a grim expression on his face.</p></div>\n<div><p>“All sixteen of us have an equal right to speak, and just as Shinohara-san said, I don't think there was any particular problem with the two of them. Isn't this completely uncharacteristic behavior for you, Ayanokōji-kun?”</p></div>\n<div><p>“I have to agree. I can't defend you on this one,” Yoshida added, shaking his head.</p></div>\n<div><p>It seemed all of my new Class C peers were harboring the exact same negative feelings toward me.</p></div>\n<div><p>“Honestly, this whole thing makes me anxious,” Shinohara said, staring at me. “Even when we tried to compromise, you threw that attitude in our faces. If you keep creating this toxic environment, there’s no guarantee your plan will actually work out. The upcoming vote is strictly anonymous, meaning if someone actually does betray us, we won’t be able to pinpoint who it was. Doesn't this whole strategy fall apart if there are people from other classes we can't trust?”</p></div>\n<div><p>Her eyes were faintly moist, and despite her defiant glare, it was as if she was trying to hide how deeply my words had hurt her.</p></div>\n<div><p>“I don't think I'm making a difficult demand,” I replied. “If you just let Kushida and Mii-chan take the lead, things will proceed smoothly.”<span></span></p></div>\n<div><p>No matter how much it worsened their impression of me, I reiterated my stance.</p></div>\n<div><p>“You just pick on us out of nowhere and make whatever demands you want... Isn't that a waste of time too!?” Ike shouted.</p></div>\n<div><p>“Ah… I see. So that's how it is. Fine, I get it,” Shinohara scoffed. “Let's just do what he wants, Kanji. Kushida-san is definitely a good girl, after all. She's a great talker, and she's cute.”</p></div>\n<div><p>Throwing in the towel, Shinohara gave up, deciding I was no longer worth arguing with.</p></div>\n<div><p>“Anyway, we'll leave this task to you. Can we count on you, Kushida-san?”</p></div>\n<div><p>“M-Me...?” Kushida blinked.</p></div>\n<div><p>“Well, it's what Ayanokōji-kun wants. Apparently, we aren't capable of moving the discussion forward ourselves.”</p></div>\n<div><p>“Y-Yeah, I'm fine with taking the lead, but... Ayanokōji-kun, I think you should apologize to those two first. I want us all to cooperate on good terms, you know—”</p></div>\n<div><p>Kushida was making it clear that cooperation would be difficult if I maintained the hostile attitude I'd used to force Ike and Shinohara to back down. For the sake of proceeding smoothly, this was probably the right time to pull back.</p></div>\n<div><p>“Understood. It's true that I went a little too far. Kushida is right.”</p></div>\n<div><p>“What the hell? When Kushida-san tells you to, you just apologize, just like that?” Shinohara snapped.<span></span></p></div>\n<div><p>“That's not it. Looking back on it, she simply made me realize my mistake.”<span></span></p></div>\n<div><p>“...I highly doubt that. It didn't look that way to me...” Shinohara muttered. “Well, fine. Whatever.”</p></div>\n<div><p>Rather than forgiving me, she replied coldly out of pure exasperation, clearly done talking to me.</p></div>\n<div><p>“My bad,” I added.</p></div>\n<div><p>At my brief apology, Shinohara merely snorted. She grabbed Ike by the arm and pulled him a step back, distancing themselves slightly from the circle.</p></div>\n<div><p>“So, we've accepted Ayanokōji-kun's <em>heartfelt </em>apology. Kanji and I will step back now. Though, of course, if we have something to say later, we'll still say it.”</p></div>\n<div><p>“Sorry, Kikyō-chan. We're leaving this to you,” Ike added.</p></div>\n<div><p>“No, don't worry about it at all. I'm not sure how reliable I'll be, but I'll do my best,” Kushida replied with a cute smile.</p></div>\n<div><p>Seeing her gentle demeanor, Ike's angry expression finally softened a little.</p></div>\n<div><p>“Oh, right! Why don't you suggest a good idea, Kushida-san?” Shinohara prompted. “It'd be best if we had some sort of risk management method to prevent betrayers from popping up, right?”</p></div>\n<div><p>It was a pointed remark from Shinohara. Was that jab aimed at me, the person who had been grating on her nerves this whole time? Or was it aimed at Kushida, my former class's <em>other </em>traitor? Either way, the group's gaze naturally gathered on Kushida. Looking slightly troubled, she began to think.</p></div>\n<div><p>“Let's see...” Kushida started. “We can't prevent betrayal completely, but we can lower the risk by making sure we can narrow down exactly <em>who </em>betrayed us. If we publicly announce and assign exactly who will vote for which destination in advance, we'll be able to narrow down the suspects if a discrepancy occurs in the final results.”</p></div>\n<div><p>Kushida explained that, for example, if we agreed on a 4-3-3-3-3 split but the actual result came out as 4-2-3-3-4, it would definitively prove that one of the three students assigned to the second destination had betrayed the group.</p></div>\n<div><p>“Umm, something like that anyway. I hope my logic is right, but... I don't really have a lot of confidence in it,” she added, looking perplexed as she lightly scratched her cheek with her index finger.</p></div>\n<div><p>“For a spur-of-the-moment idea, I'd say it's not bad,” I noted. “What do you think of Kushida's proposal, Katsuragi?”</p></div>\n<div><p>By passing the conversational baton to Katsuragi, I forcefully shifted the dynamic away from the 'Ayanokōji vs. Class A' narrative that had been dominating the air.</p></div>\n<div><p>“I agree as well,” Katsuragi replied. “It is certainly a measure we should implement. Though, of course, it cannot be said to be foolproof.”</p></div>\n<div><p>Although Kushida had likely just come up with the idea on the spot, she didn't say anything to undermine it, obediently nodding along instead. After all, there was no point in obsessing over catching a betrayer with absolute certainty. As long as the voting remained anonymous, finding a workable compromise within those constraints was far more important.</p></div>\n<div><p>“Just the fact that it increases our chances of narrowing down a betrayer serves as a massive deterrent,” Katsuragi concluded.</p></div>\n<div><p>“Hey,” Ibuki interjected, her brows furrowing slightly. “With the plan you just laid out, there are definitely going to be four people forced to vote for the most popular destination, right?”</p></div>\n<div><p>“That's what it comes down to, yes,” Katsuragi replied immediately. “They'll be allocated evenly, one per class. By sending exactly one person from each class to the four-vote destination, the burden remains equal. That way, the loss isn't being pushed onto any single group.”</p></div>\n<div><p>“You say ‘equal,’ but the guys voting for the top destination are only going to receive one token. That means they're temporarily taking a loss, right?” Ibuki challenged. “Assuming this plan even works, is there actually a guarantee that the tokens will be split with them later?”</p></div>\n<div><p>“Of course,” Katsuragi nodded. “However, as we've already established, each class will earn a total of ten tokens. Even if you distribute them evenly, giving two to each of the four members in your class, that leaves two tokens left over. How to handle those leftovers will be up to each individual class to decide.”</p></div>\n<div><p>Hearing Katsuragi's explanation, Ibuki paused for a beat.</p></div>\n<div><p>“Whatever. But just so we're clear, I'm voting for one of the places that pays out three tokens.”</p></div>\n<div><p>She made her stance clear, lightly sweeping her gaze to the side.</p></div>\n<div><p>It was true. If all the classes kept in step with the plan, one out of the four people from each class would have to cast their vote for the most popular destination, meaning that at the moment of the vote, they would only receive one token. Her blunt remark meant that if there was no hard guarantee the tokens would actually be shared later, she wanted to be on the side obtaining three tokens from the very start.</p></div>\n<div><p>Hating the idea of taking on a risky role, Ibuki had clearly stated her refusal.</p></div>\n<div><p>“Ah, then I call dibs on one of the three-token spots, too,” Ike quickly jumped in, still standing toward the back. “I trust my friends and all, but I don't want to get wrapped up in any trouble. No point taking on unnecessary risks, right?”</p></div>\n<div><p>Piggybacking off Ibuki's declaration, Ike made it clear that he had no intention of falling on his sword for the top destination either.</p></div>\n<div><p>The atmosphere of the place shifted, just slightly.</p></div>\n<div><p>“Since we won't know who voted for what, someone could easily play dumb and keep their extra tokens later,” Shinohara continued, crossing her arms. “Even if you argue it's fine because the class as a whole still gets ten tokens, there's obviously going to be a difference on an individual level. Whether or not someone actually compensates you for taking that loss is a separate issue, isn't it?”</p></div>\n<div><p>Though she framed it as a general observation, her gaze was faintly sharp.</p></div>\n<div><p>Katsuragi shot a brief glance in Shinohara's direction.</p></div>\n<div><p>“Ibuki and Shinohara are exactly right,” Katsuragi declared, jumping in without missing a beat. “This task is premised on the results at the class level. Since there is no mechanism to guarantee perfect fairness between individuals, a guarantee of trust is absolutely necessary. Any student who feels anxious about getting properly compensated should take the initiative, self-declare their intent, and secure one of the spots paying out three tokens. I will take on the burden of voting for the most popular destination for Class B.”</p></div>\n<div><p>We only needed one person from each class to shoulder the risk, allowing the other three to safely secure at least two tokens. Acting decisively, Katsuragi stepped forward to be the first volunteer.</p></div>\n<div><p>“I'll do it for Class C,” I said, turning to Yoshida and the others as the second volunteer. Amikura from Class D immediately followed suit.</p></div>\n<div><p>Now, only Class A remained. With Ike having already explicitly refused the role, all eyes naturally fell on the other three members.</p></div>\n<div><p>“If possible, I recommend having Ike or Shinohara take on the role,” I added casually.</p></div>\n<div><p>Hearing my unnecessary remark, Shinohara furrowed her brows. Our dispute had supposedly been put to rest after my earlier apology, but my words threatened to reignite the issue.</p></div>\n<div><p>Seeing this, Yoshida stepped in. “Hey, what Class A does is for Class A to decide.”</p></div>\n<div><p>“You're right,” I replied. “Just ignore what I said.”</p></div>\n<div><p>“No, I can't just 'ignore it,'” Shinohara snapped. “You've been spouting baseless claims that we can't be trusted, talking down to us as if we don't even belong in a discussion! What on earth is your deal? Did we do something to you, Ayanokōji-kun?”</p></div>\n<div><p>“I'm not targeting you two specifically,” I replied smoothly. “I simply believe that people who lack the trust of the group should take the initiative to act in a way that <em>earns </em>that trust.”</p></div>\n<div><p>“Then let me ask you this: what about Ibuki-san?” Shinohara shot back, pointing an accusatory finger. “Ibuki-san explicitly refused to take on the role, yet you completely ignored that! Shouldn't you be forcing her to vote for the top spot instead of Katsuragi-kun?”</p></div>\n<div><p>Unexpectedly dragged into the crossfire, Ibuki glared at Shinohara, making no effort to hide her irritation.</p></div>\n<div><p>“Class B's internal dynamics are slightly complicated,” I explained calmly. “While I believe Katsuragi is a highly trustworthy individual, from Class B's perspective, he is still a transfer student who joined their ranks midway. Stepping up of his own volition to build up trust with his new classmates isn't a bad move on his part.”</p></div>\n<div><p>“I still don't buy it...” Shinohara muttered.</p></div>\n<div><p>“To begin with, the situation is entirely different from Class A's. If I were still a student in that class, voting for the primary destination and walking away with a single token wouldn't cause me a moment's hesitation. The reason is simple: as long as Kushida is an ally, I would have an absolute guarantee that she would distribute tokens to cover the deficit afterward. Even if I were intent on securing three tokens, should Kushida fail to provide two, I could simply request them from Mii-chan. In short, there would be absolutely no reason to fear being shortchanged.”</p></div>\n<div><p>The only people who couldn't be trusted were Ike and Shinohara, the very two who were explicitly scheming to snatch up three tokens for themselves if given the chance.</p></div>\n<div><p>“Conversely,” I concluded, “not assigning Ike or Shinohara to the top destination is a clear detriment to the group.”</p></div>\n<div><p>“...Hah. So the reason you're doubting Kanji and me so much is because you care so deeply about Kushida-san and Mii-chan?” Shinohara asked, narrowing her eyes in suspicion.</p></div>\n<div><p>“They are precious group members,” I replied flatly. “Naturally, I want to cooperate with them in any way I can.”</p></div>\n<div><p>“I thought this earlier, too, but you are awfully trusting of Kushida-san, aren't you?”</p></div>\n<div><p>“I am simply stating the facts. If you refuse to accept my assessment, you are free to ask Katsuragi, Sonoda, or anyone else from the other classes. Ask them who they think is more trustworthy: the duo of Shinohara and Ike, or Kushida and Mii-chan.”</p></div>\n<div><p>“Twenty minutes have passed. Forty minutes remaining.”</p></div>\n<div><p>The supervisor, who hadn't uttered a single word until now, muttered the time check, a stark reminder that the clock was steadily ticking down.</p></div>\n<div><p>“We stand to gain very little by succumbing to paranoia right now,” Katsuragi stated firmly, cutting through the tension. “Since the transfer of tokens is allowed, any final adjustments and compensations can be handled after the exam. The problem at hand is making sure our strategy doesn't collapse before we even reach that stage.”</p></div>\n<div><p>Katsuragi was making it clear: prioritize solving the group's problem first, and handle internal class disputes on your own time.</p></div>\n<div><p>“I agree. It's better to leave some time on the clock for the actual tasks,” Sumida said with a shrug, showing no hesitation.</p></div>\n<div><p>Moriyama took a short breath and immediately backed him up. “Likewise. I don't see any point in dragging out useless bargaining right now.”</p></div>\n<div><p>The members of Class D were practically unanimous. Because the four of them fully trusted one another, this entire debate was likely nothing but a waste of time from their perspective.</p></div>\n<div><p>“I think it’s about time we moved on,” Sanada said, glancing around the circle before focusing on the final group. “As for the remaining Class A...”</p></div>\n<div><p>“I am absolutely not doing it,” Shinohara stated flatly.</p></div>\n<div><p>“I’ll take it on,” Kushida volunteered.</p></div>\n<div><p>The resolute rejection from Shinohara and the self-sacrificing offer from Kushida overlapped perfectly. At the sheer contrast between their 180-degree different answers, Shinohara shot Kushida a mild glare.</p></div>\n<div><p>“I just don't want to see everyone arguing anymore...” Kushida added with a reserved smile, officially putting herself forward. “If I can be of use to the group right now, this is the least I can do.”</p></div>\n<div><p>“Is this acceptable to you, Ayanokōji-kun?” she asked.</p></div>\n<div><p>“If that's what you want, I won't stop you. Once the tokens are distributed, it becomes an internal class issue,” I replied, reiterating the risk one last time. “Just remember that I won't lift a finger to help when you inevitably argue over the payouts.”</p></div>\n<div><p>“Tch,” Ike clicked his tongue softly, clearly annoyed by my relentless warnings. “Don't worry, Kikyō-chan. Unlike a certain someone who betrayed his class, I'll absolutely share my tokens with you.”</p></div>\n<div><p>“Yeah, I completely trust you, Ike-kun. And Shinohara-san and Mii-chan, too, of course.”<span></span></p></div>\n<div><p>The students outside of Class A silently praised Kushida for taking the initiative and shouldering the risk. She seemed entirely genuine when she said she didn't doubt a single person in her class.</p></div>\n<div><p>Logic and emotion. The gap between the two could never be perfectly bridged. Still, the group managed to move on to the next stage, leaving behind only the faintest lingering friction.</p></div>\n<div><p>Our next order of business was deciding which of the candidate locations we would actually crown with the most votes and travel to.</p></div>\n<div><p>“Just to be absolutely clear: the contents of our upcoming tasks are not linked to our destination, correct?” Sanada asked, turning his head toward the supervisor.</p></div>\n<div><p>Naturally, the supervisor gave no reply. The silence itself was the only confirmation we needed.</p></div>\n<div><p>“In that case, I believe it's best to consolidate our votes on the closest destination to minimize our stamina consumption,” Sanada proposed to the group. “But if anyone has objections, I'd like to hear them.”</p></div>\n<div><p>Prompted by Sanada's logic, several students looked back down at the map. There were five candidate destinations, each presenting a distinct set of pros and cons.</p></div>\n<div><p>Should we choose the closest location? Or should we swallow the travel cost and hike to a further point? At this stage, there simply wasn't enough information to determine a definitively ‘correct’ answer. As a result, each student's personality and thought process bled directly into their opinions.</p></div>\n<div><p>“I'm good with Sanada's plan,” Sonoda was the first to speak up. Staring down at the map, he offered a frank, pragmatic take, wanting no part in unnecessary fatigue. “This exam is four days and three nights, right? It's obvious we're going to be exhausted by tomorrow. Besides, if we don't even know what the next task is, we should save every bit of stamina we can.”</p></div>\n<div><p>His words were unvarnished, but they perfectly captured the unspoken feelings of many students present. Setting aside those who had retired early, the sheer fatigue and exhaustion everyone had accumulated from the recent Survival Game Special Exam was no small matter. A distance that looked like a trivial gap on paper could hardly be ignored when actually hiking it on foot.</p></div>\n<div><p>“I agree, too...” Mii-chan nodded gently. Tracing a spot on the map with her fingertip, she quietly explained her reasoning. “Based purely on the information we currently have, there's very little reason to throw away the obvious advantage of a shorter distance. That holds especially true if the explanation about the destinations not affecting future tasks is accurate.”</p></div>\n<div><p>Her tone was soft as always, but her stance firmly supported taking the nearest route. She eliminated unnecessary speculation, drawing a logical conclusion based solely on the conditions presented to us. In that regard, her thought process was very similar to Sanada's and Moriyama's.</p></div>\n<div><p>On the other hand, there were naturally those who refused to simply follow the flow.</p></div>\n<div><p>“But that's assuming we take the supervisor's words at face value, right?” Sumida said, lifting his gaze from the map. Rather than outright opposition, his voice oozed with caution. “He said the <em>contents </em>of the tasks wouldn't change, but he never said the ease of travel or future developments wouldn't be indirectly affected. Isn't it just as dangerous to pick a spot simply because it's close?”</p></div>\n<div><p>It was a highly plausible point. In fact, during these special exams, looking for loopholes in the rules and doubting the exact wording used by the school was practically second nature. The moment someone voiced that suspicion out loud, the seed of doubt, <em>the what if, </em>took root in the group's mind.</p></div>\n<div><p>“He's right. That sounds exactly like something this school would pull, just like they always do.”</p></div>\n<div><p>Ike immediately bit onto the idea. Still dragging along some of his lingering hostility from earlier, he quickly hopped onto an argument that suited his sensibilities.</p></div>\n<div><p>“Going with the closest spot just 'cause it's the normal thing to do is <em>too </em>normal, you know? In exams like this, there's always a pattern where the guys who pick the ‘normal’ option end up getting screwed over.”</p></div>\n<div><p>He didn't have any concrete basis for the claim. However, it was incredibly easy to intuitively agree with him. After all, trying to read between the lines to uncover a hidden trap felt much more fitting for a special exam than simply choosing the most obvious, optimal route.</p></div>\n<div><p>Katsuragi crossed his arms, dropping his gaze as he pondered the point. “It’s true that we cannot completely rule out a trap. Given the nature of our past special exams, it is perfectly natural to try and read into the rules that aren't explicitly stated.”</p></div>\n<div><p>It wasn't quite an agreement; it was more like he was leaving the possibility open. Yet, just having one vague affirmation of Ike's paranoia was enough to thin out the prevailing ‘nearest spot only’ atmosphere.</p></div>\n<div><p>Sumida slid his gaze back to the map. “Be that as it may, if we overthink this, the discussion is going to spiral out of control. As long as distance is the only metric we actually have to compare, any other theory is purely speculation, right?”</p></div>\n<div><p>Several students nodded silently in agreement with his sharp, dividing logic. It was easy to doubt the rules, but once you started doubting, there was no end to the rabbit hole. What the group needed right now wasn't necessarily the ‘correct’ answer, but a unified standard they could base their votes on.</p></div>\n<div><p>In that sense, Sumida's words had pulled the group slightly back to reality.</p></div>\n<div><p>“I...” Kushida spoke up, her voice soft.</p></div>\n<div><p>She interjected so naturally that it didn't disrupt the flow of the conversation, yet her words carried an undeniable weight.</p></div>\n<div><p>“I feel like we won't find an answer even if we keep agonizing over things we simply don't know right now. Of course, being cautious is important, but the fact that a closer destination reduces our physical burden is indisputable. If saving stamina gives us more leeway for whatever comes next, I personally think we should prioritize that.”</p></div>\n<div><p>It was a gentle, tactful way of speaking that rubbed no one the wrong way. She hadn't shut down anyone else's opinion, yet she smoothly steered the conclusion back toward supporting the nearest destination. Her ability to navigate these kinds of social situations was as masterful as ever.</p></div>\n<div><p>“Well, if Kikyō-chan says so, maybe that's the way to go,” Ike said, his expression immediately softening as he effortlessly abandoned his previous stance.</p></div>\n<div><p>Shinohara shot him a side-eye but remained silent. No, it was more accurate to say she actively swallowed her words. The look on her face made it clear she didn't want to ruin the mood over something trivial.</p></div>\n<div><p>Ibuki had been watching the entire exchange with profound boredom, but eventually, she sighed in annoyance and spoke up. “At the end of the day, no one here can actually name a single real benefit to hiking all the way to a distant spot right now, can they? If that's the case, then going to a closer place is fine. If it turns out to be a trap, I'll be pissed, but for now, I'd rather just walk a shorter distance.”</p></div>\n<div><p>Her argument was rough around the edges, but it was rare for Ibuki to reach a conclusion so quickly. She was clearly exhausted and had zero patience for pointless deliberation.</p></div>\n<div><p>Sonoda nodded in agreement. “Right. At the very least, using distance as our core metric is the easiest way to move the discussion forward. Even if we can't get everyone to completely agree on the ‘why,’ using the closest spot as our baseline makes it much easier to reach a consensus.”</p></div>\n<div><p>With that, support for prioritizing a nearby location had grown significantly. Even if it wasn't a flawless, unanimous agreement, the momentum was strong enough to adopt it as our guiding principle.</p></div>\n<div><p>Of course, the matter wasn't quite simple enough to end there.</p></div>\n<div><p>Which of the ‘nearby’ places should we choose? And exactly how far were we willing to hike before a location was no longer considered ‘close’? In reality, executing the 4-3-3-3-3 voting distribution across those locations was going to be the real problem.</p></div>\n<div><p>Taking stock of the room's atmosphere, Yoshida once again pointed to the candidates on the map. “I'm going to sound like a broken record, but are we <em>really </em>sure it's that simple? Unlike the Uninhabited Island exam where we were free to roam, there's absolutely no guarantee we'll be allowed to move around freely this time. What if positioning ourselves as close to the center of the island as possible gives us a massive advantage later on?”</p></div>\n<div><p>“Isn't there also a chance that the further we travel, the better our rewards will be?” Shinohara chimed in.</p></div>\n<div><p>Everyone wanted to earn tokens efficiently, and they all understood the voting distribution required to make that happen. But as long as the lingering possibility remained that our destination might impact the rest of the special exam, it was only natural for the group's opinions to remain divided.</p></div>\n<div><p>“I understand the concerns raised by Yoshida and Shinohara,” Katsuragi countered calmly. “However, those concerns are entirely based on unsupported speculation. Whether we head toward the center of the island or hike to its outer edges, we haven't been given a single clue about what lies ahead in this task. The only concrete, undeniable difference is the travel distance. Thinking rationally, selecting a nearby location is the absolute optimal choice.”</p></div>\n<div><p>“You know, you’re pretty damn stubborn, Katsuragi,” Yoshida scoffed. “Have you already forgotten that that exact rigid way of thinking is the reason you got booted from our class in the first place?”</p></div>\n<div><p>“Let’s drop it, Yoshida-kun. That was uncalled for,” Sanada reprimanded.</p></div>\n<div><p>Ever since transferring, I felt I had come to understand my new classmates to a certain degree. Unlike me, Katsuragi hadn't willingly betrayed his class; he had been the one forced out. Yet, the hostility directed at him was surprisingly intense. I could easily imagine him repeatedly clashing with his old classmates whenever opinions were divided over class policies.</p></div>\n<div><p>“I'm casting my vote with Katsuragi,” Ike declared, watching the two glare at each other as if the conflict had nothing to do with him. “Like the man said, it doesn't matter where we go, since we have no idea what's coming next anyway.”</p></div>\n<div><p>Despite the various opinions presented so far, it was painfully obvious that our group was not in step. If we proceeded to the vote right now, there was a high chance things wouldn't go according to our initially solid strategy. It would only take one person changing their destination on a whim to cause the entire 4-3-3-3-3 structure to collapse.</p></div>\n<div><p>Letting their imaginations run wild, these students were desperately trying to convince themselves that reading into the exam's nonexistent subtext was the ‘correct’ choice.</p></div>\n<div><p>It was the epitome of confirmation bias.</p></div>\n<div><p>Opting for the closest destination was a perfectly sound, logical choice. Yet, people couldn't help but prioritize narrative over simple probability and efficiency. They wondered if heading further away might yield a hidden reward, or if choosing a spot nobody else would pick might somehow be to their advantage. They were being drawn in by the allure of an uncertain gamble.</p></div>\n<div><p>Of course, we simply didn't know if our choice of destination would influence the rest of the task or not. The only thing I knew for certain was that we were actively losing a precious resource with every passing second.</p></div>\n<div><p>“Personally, I'd like to value our time,” I interjected. “We were thrust into this Special Exam immediately after the Survival Game Special Exam, without even being given a proper chance to rest. I would highly appreciate it if we could move on to the voting sooner rather than later.”</p></div>\n<div><p>Precisely because it truly didn't matter which of the five options we chose, I considered this entire discussion a monumental waste of time.</p></div>\n<div><p>“Heh, if that's the case, maybe it's actually in our best interest to drag this out as long as possible,” Ike laughed, clearly still annoyed by my earlier cold shoulder.</p></div>\n<div><p>“This is a group battle, Ike,” Katsuragi warned him. “There is absolutely nothing to be gained from pointless bickering.”</p></div>\n<div><p>“Ayanokōji's the one who's been picking a fight with me this whole time!” Ike shot back. He looked like he was about to keep arguing, but instead, he just scratched the back of his head and sighed. “Ah, whatever. This is probably useless anyway. Let's quit talking and just get to the voting.”</p></div>\n<div><p>Following Katsuragi's lead, we finalized our class-based adjustments and cast our votes.</p></div>\n<div><p>“Since everyone has finished voting, I will announce the results,” the supervisor stated. “The final tally is: 3 votes for B9, 4 votes for E12, 3 votes for F14, 3 votes for I10, and 3 votes for I13. From here, Group 3 will proceed to E12. We will now distribute tokens to each student in accordance with these results.”</p></div>\n<div><p>“It seems safe to assume that everyone played their part perfectly,” Katsuragi noted.</p></div>\n<div><p>Our group had managed a safe start, perfectly executing the split. Every class walked away with ten tokens, and no difference was created whatsoever.</p></div>\n<div><p>Satisfied with the result, Katsuragi gave a deep nod of approval. Despite their various dissatisfactions, the other students had ultimately prioritized securing the guaranteed tokens dangling right in front of them.</p></div>\n<div><p>“None of the betrayers you were so worried about showed up. Good for you, Ike,” Katsuragi said.</p></div>\n<div><p>“Well... yeah, but that's because the idea to prevent betrayals came from <em>my </em>class, right?” Ike argued. “Before you start complaining to me, you should thank Kikyō-chan. Thanks, by the way.”</p></div>\n<div><p>While pushing back against Katsuragi, Ike forcefully asserted that their success was entirely thanks to Kushida.</p></div>\n<div><p>“No, not at all,” Kushida replied, maintaining her flawless, gentle smile amidst the mixed group of classmates and outsiders. “I really wasn't confident in the idea, but I'm just happy I was able to be of use to everyone.” She played the part of the slightly embarrassed, humble girl to perfection.</p></div>\n<div><p>“Yeah, yeah. Kushida-san really did think of a great way to prevent betrayals, didn't she? I guess the way she sees things is just... completely different from the rest of us,” Shinohara remarked.</p></div>\n<div><p>It was a stinging, pointed jab delivered in a way that only the members of Horikita's class would understand. Was it simply because she harbored lingering resentment toward Kushida, or was she annoyed that Ike was so openly praising her?</p></div>\n<div><p>Either way, Kushida didn't let her mask slip in the slightest, effortlessly letting the comment slide.</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>By the time we finished our trek, it was already past 6:00 p.m.</p></div>\n<div><p>Following the supervisor's instructions, we decided to pitch our tents here for the night. The students set about erecting tents and installing temporary toilets with practiced efficiency, naturally segregating the living areas by class.</p></div>\n<div><p>Within the main campsite, the territory was loosely partitioned into four distinct sections, one for each class.</p></div>\n<div><p>However, the moment Ike spotted me, he shot me a glare and immediately started in on me.</p></div>\n<div><p>“I'm only gonna say this once, Ayanokōji: don't come anywhere near our tent without permission. And about what happened earlier too—”</p></div>\n<div><p>“I have no intention of making enemies out of you outside of the exam tasks.”</p></div>\n<div><p>“Like anyone would believe that. If you think you're gonna get me expelled, you've got another thing coming.”</p></div>\n<div><p>“I suppose telling you I have absolutely no intention of doing that wouldn't convince you.”</p></div>\n<div><p>“No shit! Even the way you were acting today—”</p></div>\n<div><p>Unable to just sit there and listen to Ike's rising hostility, Katsuragi stopped what he was doing and rose to his feet.</p></div>\n<div><p>“Need I remind you that, for the time being, we are allies in the same group?”</p></div>\n<div><p>Katsuragi delivered his warning firmly. Still, having felt repeatedly made a fool of, Ike’s anger wasn't going to cool down that easily.</p></div>\n<div><p>“Look, I am calm. But there's no way I can see him as an ally. Ayanokōji is a traitor to the class, and he treats us like idiots. You can't let your guard down around him. Who knows when he might try to slit our throats in our sleep?” Ike turned to me before continuing. “Anyway, sorry, but just keep away from us unless it's absolutely necessary.”</p></div>\n<div><p>“If one of the sixteen people in this group was guaranteed to be expelled, I might understand your hostility, but…”</p></div>\n<div><p>“It's fine, Katsuragi. What Ike is saying is fundamentally correct.”</p></div>\n<div><p>After that, I grabbed my bags and ducked into our newly assembled three-person tent. A moment later, Yoshida followed me inside.</p></div>\n<div><p>“Still, Ayanokōji... Do you have some kind of grudge against Class A? Or rather, against Ike and Shinohara?”</p></div>\n<div><p>“I don't hold any grudges. Though, considering the circumstances, they have plenty of reasons to hold one against me.”</p></div>\n<div><p>“Well, yeah, I guess that's true. But if that's the case, what was up with your attitude during the task earlier? You went a bit far, and some of the things you said didn't even make logical sense. Are you dealing with some kind of issue or special circumstance you can't easily talk about?”</p></div>\n<div><p>Even though I had answered him honestly, Yoshida didn't seem entirely convinced.</p></div>\n<div><p>“I mean, going out of your way to leave Class A is pretty bizarre in itself.”</p></div>\n<div><p>I paused my unpacking and looked over at Yoshida. He met my gaze with a serious expression and continued.</p></div>\n<div><p>“How do I put this... watching you just made me wonder if you really made the right call. With your abilities, you could've comfortably graduated as a member of Class A.”</p></div>\n<div><p>“Being in Class A doesn't mean much to me. Even without using class privileges, there are plenty of alumni who have successfully made it into university.”</p></div>\n<div><p>“Sure, someone like you could probably pass the entrance exams for a top-tier college on your own. Still... after enrolling in a tough school like this, don't you think you might as well take advantage of the Class A privileges while you're at it?”</p></div>\n<div><p>“Fair point. I won't deny that.”</p></div>\n<div><p>“You're not even gonna deny it?!” Yoshida laughed, landing a playful smack on my shoulder.</p></div>\n<div><p>“I'm sure the other guys have already grilled you about this, but have you decided where you're going after graduation?”</p></div>\n<div><p>“I'll be going to university. I just haven't decided exactly where yet.”</p></div>\n<div><p>Even though I knew university life was completely irrelevant to my future, I had done a fair bit of research on the subject just so I wouldn't slip up and expose my ignorance.</p></div>\n<div><p>For a third-year high school student, summer was the crucial period to narrow down their top-choice schools. From what I’d read, it was standard practice to have those choices locked in by November at the latest.</p></div>\n<div><p>\"Have you finalized your choice yet, Yoshida? You mentioned before that any decent university would be fine.\"</p></div>\n<div><p>“Nah, nothing's changed. If I had to pick, I'd say I kinda want to stay in Tokyo. That being said, if I can't graduate from Class A, worst-case scenario is I end up at some local college back home.”</p></div>\n<div><p>Unlike regular high schools, this school offers a unique perk: the Class A graduation privilege.</p></div>\n<div><p>Yoshida’s case, for example. His plan was to take the entrance exams for a local college and try to get in on his own merit first. I didn't know if this had always been the rule, but under the school's current system, the final Class A standings are locked in on March 1st, right before graduation. If a student chooses to exercise their privilege at that point, they bypass the standard admission process entirely and are accepted into their university of choice under a special quota.</p></div>\n<div><p>Naturally, entering a university that far exceeds your actual academic level comes with serious drawbacks. You'd be playing catch-up against fast-paced lectures, the higher comprehension levels of your peers, and your own lack of prerequisite knowledge. There would be no shortage of hurdles requiring immense effort to overcome. But ultimately, surviving that environment simply comes down to how hard you're willing to work once you're in.</p></div>\n<div><p>Under normal circumstances, high schools and universities have strict enrollment caps, meaning the number of accepted applicants is ruthlessly narrowed down. Add in the pressure of make-or-break entrance exams and the fact that the higher a university's prestige, the fiercer the competition, and the barriers to entry become incredibly steep. But if you can skip all those hurdles and guarantee your enrollment, all you have to do is push forward with everything you have.</p></div>\n<div><p>Granted, this strategy wouldn't work for every academic path. Forcing your way into medical school or certain highly specialized majors without the necessary foundation might not lead to a very bright future. For students lacking confidence in their academics, rather than half-heartedly using the Class A privilege to struggle through college, it would be far more valuable to use it to secure a job at a major corporation straight out of high school.</p></div>\n<div><p>“Well, before we start talking about our dreams, we actually have to win this special exam first,” Yoshida sighed, flopping down onto his side in our relatively spacious tent.</p></div>\n<div><p>I immediately told him to get up, prompting him to lift his upper torso back off the floor.</p></div>\n<div><p>“What is it?”</p></div>\n<div><p>“You're right. Winning this exam is crucial,” I said, holding out my smartwatch for him to see. “Fortunately, the other classes are tucked away in their own tents right now. There are a few things I want to test out while we have the chance, so keep me company for a bit.”<span></span></p></div>\n<div><p>“I don't really get it, but I'm guessing you've thought of something? Alright, let's do this.”</p></div>\n<div><p>Pushing past his exhaustion, Yoshida sat up across from me as we spent the next little while running through my tests.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>By 7:00 p.m., it was time for dinner. Rations in hand, I headed over to the girls' side of the camp and called out to Kushida, who was mid-conversation with Amikura.</p></div>\n<div><p>“Would you like to eat together?”</p></div>\n<div><p>Amikura's smile seemed to stiffen for a fraction of a second, <em>perhaps the invitation had brought someone else to mind? </em>but she quickly smoothed over her expression and urged Kushida to go ahead.</p></div>\n<div><p>Looking suitably bewildered, Kushida grabbed her meal and followed me. We walked until we were safely out of earshot, at which point she stopped, keeping a deliberate distance of about a meter between us.</p></div>\n<div><p>“What are you trying to pull, Ayanokōji-kun?”</p></div>\n<div><p>“Didn't you say you wanted to discuss our plans for tomorrow?”</p></div>\n<div><p>“I never said that. Besides, it's not like you actually need my help, right? Honestly, you're just being a massive pain.”</p></div>\n<div><p>“Is that so? I figured that giving you a chance to prove your worth to the group would satisfy your need for approval. I thought you'd be happy.”</p></div>\n<div><p>“Don't make me laugh. If it were just you, Ayanokōji-kun, that’d be one thing, but do you have any idea how agonizing it is to be put on a pedestal in front of Shinohara and the others when they already know my true nature? They're just messing with me for their own amusement.”</p></div>\n<div><p>She punctuated her rant by narrowing her eyes into a vicious glare.</p></div>\n<div><p>“Though, I suppose I understand that you can't exactly rely on Shinohara or Ike…” she muttered with an exasperated sigh, grudgingly accepting that she had been chosen by process of elimination. “Putting that aside, it looks like you're adjusting quite nicely to your new class.”</p></div>\n<div><p>“With Sakayanagi gone, they lost their safety net. They probably would’ve rallied around anyone in that position, wouldn’t they?”</p></div>\n<div><p>“You don't say,” she scoffed.</p></div>\n<div><p>Her response was brief, followed by a fleeting moment of hesitation. </p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"https://cdn.sanity.io/images/m1xj6lbt/production/19d2178379335e1edfc4c70580bf31039197ffa7-1852x2832.webp\"><span></span></div>\n<div><p>Yet, just as quickly as her guard had wavered, her usual composure returned.</p></div>\n<div><p>“If there's something you want to ask, go ahead.”</p></div>\n<div><p>“It's nothing in particular,” she fired back instantly. But sensing that I'd already caught her hesitation, she let out a quiet sigh. “It's just... the rumors about you right now are endless. I don't believe all of them, obviously, but I've been hearing plenty of things from Class D as well.”</p></div>\n<div><p>She shifted her gaze toward Amikura and the rest of Ichinose's class as she spoke.</p></div>\n<div><p>“Still—” Her expression shifted as she deliberately changed the subject. “Having my true nature exposed has been almost entirely a nightmare... but having moments like this where I can just drop the act and speak my mind might be the only salvation.\"</p></div>\n<div><p>Forcibly ending the conversation there, she took a step back. She still hadn't touched a single bite of her dinner.</p></div>\n<div><p>“Sorry, but I'm heading back. I really don't want to draw any more unnecessary heat from Shinohara and the others.”</p></div>\n<div><p>“Your double life sounds exhausting.”</p></div>\n<div><p>“It's a little late for that.”</p></div>\n<div><p>With that, Kushida turned on her heel and headed back to Amikura's group.</p></div>\n<div><p>It was true that Shinohara was partly using Kushida as an outlet for the frustration she felt toward me. Kushida obviously wouldn't enjoy being collateral damage in that conflict.</p></div>\n<div><p>Still, that didn't mean I was going to leave her out of things from tomorrow onward. This special exam carried a guaranteed penalty: someone was going to be expelled.</p></div>\n<div><p>Normally, the strategy would be to hunker down, protect everyone in your own group, and just pray that the last-place student comes from a different group or class. But I had no intention of playing it that way.</p></div>\n<div><p>It was far more rational to take control and select the expulsion target myself from among the fifteen other students in my group. I wouldn't neglect laying the groundwork so that anyone could be chosen, depending on how the situation unfolded.</p></div>\n<div><p>While her priority was low, Kushida was naturally one of those candidates. That was just the reality of the situation.</p></div>\n<div><h2>Part 4</h2></div>\n<div><p>As we finished our dinner, the supervisor approached our group, tablet in hand.</p></div>\n<div><p>“Seeing as you've all finished your meals, we will now have you take on a new individual category task,” the supervisor announced. “Since you will continue to work together as a group to tackle tasks from tomorrow onward, I would like you to officially elect a ‘Popular Person’ and an ‘Unpopular Person.’ Each of you will cast one vote for the Popular Person and one vote for the Unpopular Person. The student crowned the Popular Person will be happily rewarded with five tokens upon the task's completion. Conversely, the student chosen as the Unpopular Person will, unfortunately, lose half of their current tokens. As a relief measure, anyone holding only a single token will not lose anything. However, if the unfortunate student possesses an odd number of three or more, any fractions of their remaining tokens will be rounded down, meaning they could potentially lose more than half their stash. Finally, any student who votes for the overall Popular Person will be awarded two tokens.”</p></div>\n<div><p>A task to decide the most and least popular among us. Naturally, the eyes of the students from the other classes gravitated toward Kushida. Meanwhile, Ike, Shinohara, and Ibuki all shot me meaningful glances.</p></div>\n<div><p>“If there is a tie for the Popular Person, no tokens will be awarded,” the supervisor continued. “Conversely, should there be a tie for the Unpopular Person, all tied individuals will have their tokens halved. You will have thirty minutes for discussion, and the voting method will remain the same as before. Furthermore, whoever secures the title of Popular Person will be exempt from being designated as the Unpopular Person. In such a scenario, the Unpopular penalty will automatically cascade to the individual with the next highest vote count. You may now begin.”</p></div>\n<div><p>Between the previous task and this one, a sense of déjà vu drifted over the group.</p></div>\n<div><p>“We've done a special exam like this before, haven't we?” Yoshida, who was seated next to me, muttered under his breath to Sanada.</p></div>\n<div><p>“Yes, it's extremely similar,” Sanada replied softly. “It's possible that this entire special exam is designed to mirror the special exams we've faced in the past. If you think about it, the format of this mixed four-class group is quite close to the Mixed Training Camp, so it makes sense.”</p></div>\n<div><p>It was still too early to draw any definitive conclusions, but the plausibility of that was steadily increasing.</p></div>\n<div><p>If that really was the case, then from tomorrow onward, we might be hit with tasks mirroring the rules of the Paper Shuffle, the Event Selection Exam, or the Cooperative Comprehensive Written Test, albeit on a much smaller scale.</p></div>\n<div><p>Regardless, speculating about the future wouldn't help us right now. We needed to focus on the task directly in front of us, the one where the Popular Person raked in tokens.</p></div>\n<div><p>Unlike the previous task, which had been structured so that everyone could easily reap the benefits, only a single person would walk away with these five tokens. The reward couldn't be split among the fifteen of us. Given that reality, everyone naturally wanted to be voted the Popular Person.</p></div>\n<div><p>However, the reality was that very few students possessed the confidence to brazenly assert their own popularity.</p></div>\n<div><p>More often than not, those who loudly declared themselves popular were the very ones who ended up ostracized.</p></div>\n<div><p>Even Ike, despite his obvious urge to speak up, chose to keep his hand down. He was well aware that the Popular Person title was entirely out of his reach. More than that, he was terrified that drawing attention to himself would backfire, turning him into a prime candidate for the Unpopular Person votes.</p></div>\n<div><p>“This task is going to be a headache,” someone muttered. “If we all coordinate and vote for the same Popular Person, we each get two tokens, but the winner walks away with five. Reaching an agreement on who gets the lion's share won't be easy.”</p></div>\n<div><p>“If we're going to struggle to reach a consensus, wouldn't voting for Kushida be the safest bet, assuming we're basing this strictly on popularity?” I interjected, hoping to cut down on a drawn-out discussion.</p></div>\n<div><p>“M-Me?” Kushida blinked, feigning surprise.</p></div>\n<div><p>Actually, she might have been genuinely surprised. After all, every single student in Horikita's class had already witnessed the real Kushida. While she likely interpreted my suggestion as a surface-level endorsement of her ‘sweet’ persona, the raw surprise in her eyes suggested she was frantically trying to deduce my underlying motive.</p></div>\n<div><p>At the same time, Yoshida and my classmates were visibly taken aback. Recommending a student from a rival class essentially meant willingly handing over the biggest payout.</p></div>\n<div><p>While Kushida directed a suspicious gaze at me, I also felt the inward pressure of her asking <em>What are you plotting?</em> It might just be my imagination, so I ignored it and continued speaking.</p></div>\n<div><p>“Of course, this is just a suggestion. If anyone has a more suitable candidate in mind, I have no objections.” By framing it this way, I made it seem as though I wasn't forcing the issue. Even so, the first idea tossed into the ring inherently sets the baseline for the rest of the debate.</p></div>\n<div><p>“No, you're definitely right!” Ike immediately latched onto the idea. “Kikyō-chan is super popular. She gets along with everyone and never gets involved in unnecessary drama.”</p></div>\n<div><p>Glossing over the fact that it was my suggestion, he cheerfully voiced his support.</p></div>\n<div><p>Kushida possessed two faces. Even though everyone in her class knew about her true nature, as long as the other classes remained in the dark, her public persona was an asset that could be exploited. Ike understood that much perfectly well. Furthermore, his inherently high affection for Kushida was likely fueling his eagerness.</p></div>\n<div><p>“You... think so? I'm not really sure,” she murmured.</p></div>\n<div><p>“Nah, out of everyone here, it absolutely has to be you, Kikyō-chan. No question about it!” Ike nodded along enthusiastically, his face lit up with a wide grin.</p></div>\n<div><p>When Kushida responded with a bashful, sheepish smile of her own, Ike’s expression melted even further, his eyes crinkling with sheer delight as a goofy smile spread across his face.</p></div>\n<div><p>While Ike's endorsement was unmistakably providing tactical covering fire for the class, from the perspective of his girlfriend, Shinohara, there was absolutely nothing amusing about it.</p></div>\n<div><p>It was painfully obvious that her frustration was spiking at the sight of her boyfriend fawning over another girl. Under normal circumstances, she probably would have dragged him off by the ear and hurled a few insults his way. However, securing the Popular Person spot for Kushida directly benefited their own class.</p></div>\n<div><p>“Well... yeah,” Shinohara sighed, unable to keep a hint of sourness out of her voice. “It'd be a different story if someone like Ichinose-san were here, but out of this group, isn't Kushida-san the safest choice?” Swallowing her personal irritation, she opted to back up Ike's proposal.</p></div>\n<div><p>Naturally, this momentum didn't sit well with anyone outside of Class A. Pushback began almost instantly.</p></div>\n<div><p>“Hold on a second. I get why you'd say Kushida is popular, and I'm not denying that, but just handing her our votes like this is a bit…” Yoshida trailed off, his hesitation clear as he struggled to voice a solid counterargument.</p></div>\n<div><p>“Then who else are you gonna vote for?” Ike challenged. “Name one person here who's more popular than Kikyō-chan. Go on, I'll wait.”</p></div>\n<div><p>“That's…” Yoshida scanned the circle. He was looking for someone who could rival, or perhaps even surpass, Kushida's widespread appeal. But even if he tried to bluff, no such student existed in our current lineup.</p></div>\n<div><p>“See? No matter how you slice it, there aren't any other candidates. So it's decided, decided!”</p></div>\n<div><p>“I'm really not all that great, though…” Kushida offered another modest smile, but her denial was flimsy. Her demeanor clearly left the door wide open for her to accept the nomination.</p></div>\n<div><p>And that very vulnerability gave Ike and the rest of Class A all the more reason to keep pushing for her.</p></div>\n<div><p>“I get where you're coming from, Yoshida, but realistically, there's no better candidate than Kushida.” I offered this dry defense for the benefit of Class A, though I was ultimately just stating the facts.</p></div>\n<div><p>“If only Shiraishi were here…” Yoshida muttered under his breath, his quiet frustration slipping past the others' notice.</p></div>\n<div><p>I wouldn't go so far as to say Shiraishi was unpopular, but Yoshida's imaginary vote was fueled entirely by his own personal bias.</p></div>\n<div><p>“...I see.” Katsuragi, who had been quietly observing the exchange, finally spoke up. He stood with his arms crossed, his sharp gaze fixed directly on me. “Your logic certainly holds up. However, there is one glaring flaw in this discussion.”</p></div>\n<div><p>As expected, it seemed Katsuragi was the first to notice.</p></div>\n<div><p>“We are letting ourselves be misled by the words ‘Popular’ and ‘Unpopular,’ completely blinding ourselves to the conflicting interests of our respective classes.” His voice was quiet, yet the sheer weight of his words anchored the room. “This group is a mixture of all four classes. Naturally, depending on the outcome, some classes will profit while others will suffer losses.”</p></div>\n<div><p>“Well, that can't be helped, right? Kikyō-chan <em>is </em>actually popular—”</p></div>\n<div><p>“That's exactly my point. Her actual popularity is entirely irrelevant.” Katsuragi cut Ike off without hesitation. “True, the exam tasks us with electing a ‘Popular Person,’ but there is absolutely no rule stating the nominee must actually fit that description.”</p></div>\n<div><p>“Huh...? But the supervisor literally said we had to properly decide so we could tackle the task.”</p></div>\n<div><p>“So what? That was merely an instruction to complete the objective. I didn't interpret that statement as anything more or less than what it was, did you?”</p></div>\n<div><p>He had hit the nail on the head. This wasn't a genuine popularity contest. At its core, it was simply a contest over who could hoard tokens and who would be stripped of them. As long as we remained distracted by the superficial wording, we would never have a meaningful discussion.</p></div>\n<div><p>“Voting for Kushida simply benefits Class A.” Katsuragi's gaze sharpened slightly. It was more of a check than a mere point out.</p></div>\n<div><p>“Oh, so that's how it is…” someone murmured as the realization set in. “Right. Whether they're actually popular or not doesn't matter at all.”</p></div>\n<div><p>“Then the idea is rejected. Rejected,” Ibuki spat, not wasting a single second. But simply shooting it down wasn't enough for her. “Seriously, why the hell should we go out of our way to hand tokens over to Kushida, to a rival class? Are you guys actually idiots for almost getting swept along by that?”</p></div>\n<div><p>It was a blatant, visceral rejection now that the illusion was shattered. She wasn't arguing with logic anymore; it was pure, unadulterated emotion.</p></div>\n<div><p>But that was fine. If anything, that raw emotion was exactly what I needed to shift the dynamic.</p></div>\n<div><p>While things were playing out exactly as I intended, Katsuragi's intense focus shifted back to me.</p></div>\n<div><p>“There is no way Ayanokōji wouldn't realize something of this level. Am I the only one who thinks so?” He fired the accusation point-blank, questioning exactly why I had nominated Kushida in the first place.</p></div>\n<div><p>\"You aren't secretly colluding with Kushida-san behind our backs, are you, Ayanokōji-kun?\" Shinohara, who had been nominally on Kushida's side as a fellow classmate until now, suddenly pivoted, aiming her suspicion straight at me.</p></div>\n<div><p>“Eh, w-what do you mean, Shinohara-san?” Seeing the crosshairs drift her way, Kushida immediately cranked up her performance of flustered bewilderment.</p></div>\n<div><p>But Shinohara ignored the act entirely. “I meant exactly what I said. Well, I suppose there's no way Kushida-san would actually stoop to something like that.”</p></div>\n<div><p>“Of course not, We had no way of knowing what kind of tasks were coming up in the first place.”</p></div>\n<div><p>“Yeah, Satsuki, you're taking it a bit too far.”</p></div>\n<div><p>“And why exactly are you taking Kushida-san's side?!” Shinohara snapped.</p></div>\n<div><p>“Whoa, hey, wait a sec! There's no need to get so combative, right? I mean, I was thinking the same thing as Ayanokōji, so maybe he really was just trying to pick the safest option?”</p></div>\n<div><p>“I highly doubt that. Don't think I haven't noticed you doing nothing but staring at Kushida-san this whole time, Kanji!”</p></div>\n<div><p>“T-That's not true at all! I swear, seriously, I swear!”</p></div>\n<div><p>As the atmosphere rapidly deteriorated into a petty lovers' quarrel that threatened to derail the discussion, Ibuki snapped and kicked the ground in aggravation.</p></div>\n<div><p>“Whatever, the point is, I absolutely refuse to hand tokens over to Class A.”</p></div>\n<div><p>“Agreed. We're against it too,”</p></div>\n<div><p>One after another, the members of Class B voiced their dissent, and the remaining classes quickly followed suit. They showed no signs of backing down.</p></div>\n<div><p>“Man, come on... this is still better than getting into some weird, messy conflict, right?” Turning his back to actively dodge Shinohara's terrifying glare, Ike desperately tried to placate the group. “What's the point of jumping straight at each other's throats right from the start? For one thing, we'll never reach an agreement like this.”</p></div>\n<div><p>“Then we should just stop talking in circles,” Ibuki declared bluntly, having zero patience for drawn-out discussions. “Let's just pick whoever we actually want to vote for and be done with it.”</p></div>\n<div><p>If talking it out couldn't yield a favorable outcome, she preferred to level the playing field. To her, a straightforward clash was the simplest path forward and offered the cleanest chance of winning.</p></div>\n<div><p>Katsuragi quietly processed her suggestion. “Simply nominating whoever we please might actually be the safest option.”</p></div>\n<div><p>“I mean, if the whole point is that the Popular Person gets tokens, then voting normally makes the most sense. Not that I care how the results shake out,” Ibuki agreed with a casual nod, treating it as the most natural conclusion.</p></div>\n<div><p>“However, taking that route practically guarantees that each class will just consolidate their votes,” Sanada pointed out. “Even if we don't say a single word, it's easy enough to coordinate our votes through eye contact alone.”</p></div>\n<div><p>He was right. If we divided along class lines, it would only result in up to four ‘Popular People’ receiving three votes each. A multi-way tie meant zero tokens awarded across the board.</p></div>\n<div><p>“Yeah, exactly!” Ike seized the opening. “If we do that, the votes will just split, and nobody gets anything. In that case, it's absolutely better to pool our tokens on Kikyō-chan and boost the group's overall total! This special exam isn't just about individuals hoarding tokens, right? It's about helping each other out!”</p></div>\n<div><p>“You have a point, Ike,” Sonoda from Class B interjected. “I get what you're trying to say. But if pooling points is the goal, then someone from Class B... hell, even <em>I </em>would be fine. The total number goes up either way, so it's the exact same thing.”</p></div>\n<div><p>“Uh, that's actually a little different, Sonoda-kun,” Shinohara shot back. “Helping each other out means trusting that the person will actually lend a hand when someone is in trouble. No offense, Sonoda-kun, but you aren't exactly trustworthy. Kushida-san, on the other hand, is. Isn't that right, Ayanokōji-kun?”</p></div>\n<div><p>She was smoothly weaponizing the exact logic I had laid out earlier regarding Kushida's reliability, turning it directly back on Sonoda.</p></div>\n<div><p>“Yeah, that logic holds up,” I agreed.</p></div>\n<div><p>If Kushida was crowned the Popular Person, she would gain five tokens. While those tokens would ostensibly belong to Class A, if Sonoda or anyone else were to fall into a desperate situation later on, Kushida possessed the reputation of someone who would return the favor and bail them out. It served as a form of insurance for the future.</p></div>\n<div><p>“Sure, maybe it means our class gets a few more tokens right now,” Shinohara continued, pressing her advantage. “But you can think of it as a value of trust. Right, Kushida-san?”</p></div>\n<div><p>“I... I really don't know if I'm suited to be the Popular Person,” Kushida replied, her voice soft and earnest. “But if anyone ever found themselves in trouble, I would absolutely want to help them.”</p></div>\n<div><p>A heavy silence fell over the area, the sheer weight of their competing arguments lingering in the air.</p></div>\n<div><p>Those were the words of arguably the most trustworthy person in the entire group. Yet, despite that, the other classes couldn't bring themselves to simply nod in agreement.</p></div>\n<div><p>The core issue was the inevitable disparity in tokens. Handing Kushida the win meant willingly allowing a gap to form between the classes within our group, a scenario they desperately wanted to avoid. Even if it meant forfeiting the reward entirely by forcing a tie, stalling the creation of a clear hierarchy felt safer. The debate had shifted entirely from <em>‘who is popular’ </em>to <em>‘are we fine letting Class A take the lead?’</em></p></div>\n<div><p>“What do we do, Ayanokōji?” Yoshida whispered under his breath, leaning in so the others wouldn't hear. “Do you have some kind of plan?”</p></div>\n<div><p>I didn’t answer. I merely let my gaze drift sideways, observing the distance between Ike, Shinohara, and Kushida, who remained just beyond them.</p></div>\n<div><p>A very slight, yet undeniable gap had formed among the three, a subtle rift that hadn't been there moments before. For the purposes of this task, that alone was sufficient.</p></div>\n<div><p>It was nothing more than a tiny seed of discomfort right now, but given enough time and the right circumstances, it would inevitably blossom into something far more tangible.</p></div>\n<div><p>With no clear compromise in sight, the clock continued to tick down. One minute passed, then two.</p></div>\n<div><p>“Seriously, what are we doing here? We can't move forward if we don't actually decide on something,” Ike finally snapped, his patience wearing thin.</p></div>\n<div><p>However, the edge in his voice wasn't fueled by genuine anger. Rather, it was a desperate impatience to just get it over with, proof that he couldn't stomach the suffocating tension in the room for another second.</p></div>\n<div><p>“Regarding the Popular Person, it really feels like that's our only viable option,” Shinohara added, her gaze flicking up slightly.</p></div>\n<div><p>Naturally, a few sets of eyes immediately gravitated toward her. A clear sense of caution still lingered in those looks, but for the time being, that was fine.</p></div>\n<div><p>“Basing the vote solely on Kushida's personal trustworthiness, you say…” Katsuragi mused, his arms still crossed. “True, if you frame it strictly from that angle, the logic is sound, but…” His eyes remained narrowed, silently probing my intentions. It was obvious he still wasn't entirely sold on the idea.</p></div>\n<div><p>“I don't care if the class votes end up splitting or whatever. It just means we're stuck picking randomly in the end anyway, right?” Ibuki scoffed. “So why are we still rambling in circles? This is so stupid.”</p></div>\n<div><p>“Right? We basically just have to decide what's better: letting the votes split so nobody in the group gets any tokens, or giving the win to Class A so the group's overall total goes up,” Ike said, offering a quick shrug. “Trying to pull off some weird mind game and completely whiffing it is way worse.”</p></div>\n<div><p>“Besides, if the group is bringing in tokens, we should normally be grateful for it,” Shinohara chimed in with a small nod of agreement. Her comment sounded casual, but it carried exactly enough weight to decisively tip the scales.</p></div>\n<div><p>By shifting the focus to a simple, easily digestible matter of total profit, the resistance from the other classes weakened considerably.</p></div>\n<div><p>“...I can't say my objections have completely vanished,” Katsuragi finally conceded. “But seeing as there is no clear counter-proposal on the table at this moment... I am willing to tentatively accept this.”</p></div>\n<div><p>“Alright, then— are we officially good with Kikyō-chan as the Popular Person?”</p></div>\n<div><p>When no one voiced a direct objection to Ike's confirmation, a few seconds of heavy silence ticked by before it was quietly processed as unanimous approval.</p></div>\n<div><p>With that, the first major hurdle was cleared.</p></div>\n<div><p>“I guess that's fine,” Ibuki said suddenly, leaning forward. “But by the way, what exactly are we doing about the Unpopular Person?”</p></div>\n<div><p>The atmosphere changed instantly, the air around us growing noticeably heavier.</p></div>\n<div><p>If anything, one could argue that <em>this </em>was the true crux of the matter for Ibuki.</p></div>\n<div><p>Unlike with the Popular Person, no one dared to casually open their mouths this time.</p></div>\n<div><p>And naturally so. This wasn't about uplifting someone; this was a discussion about tearing someone down. There was no way this could end peacefully, which was precisely why everyone knew they had to tread carefully.</p></div>\n<div><p>“A debate where we just try to forcefully shove the penalty onto someone else will only end in a fruitless, ugly conflict. The simplest resolution is for someone willing to take the loss to step forward,” Katsuragi stated, deliberately cutting to the chase in an effort to prevent the atmosphere from turning hostile.</p></div>\n<div><p>“...Well, I suppose that's true,” a Class C student muttered, and the rest of his classmates mirrored his complicated, uneasy expression.</p></div>\n<div><p>“Locking in the Popular Person during this discussion is enough,” Katsuragi added after a brief pause. “As for the Unpopular Person vote, we simply need to let everyone judge the situation for themselves and cast their votes however they see fit.”</p></div>\n<div><p>“So it's a ‘no hard feelings’ kind of deal, right?” Shinohara confirmed, though a slight edge of irritation bled into her voice. She wasn't dumb; she knew perfectly well that if she voiced a strongly negative opinion right now, she would instantly paint a target on her own back.</p></div>\n<div><p>Ibuki, who had been the one to bring the issue up in the first place, also kept her mouth shut after that. Unlike Kushida, who had cleanly secured the Popular Person spot, Ibuki was exactly the type of student who was at high risk of gathering the Unpopular votes.</p></div>\n<div><p>“That's what it comes down to,” Katsuragi confirmed.</p></div>\n<div><p>“I see…” Sanada murmured, summarizing the strategy aloud. “By choosing not to unify our votes, we are conversely leaving room for mind games.” He gave a small nod, looking thoroughly convinced.</p></div>\n<div><p>He was right. If we forcefully nominated a single sacrifice right now, the thought process for everyone would remain simple and straightforward.</p></div>\n<div><p>But by dispersing the target, we were forcing everyone to read between the lines.</p></div>\n<div><p>And those readings… would inevitably become distorted.</p></div>\n<div><p>Ike relaxed his shoulders, and Shinohara mirrored him with a small sigh of relief. They exchanged a brief look. It was a perfect display of silent communication, a phenomenon the other classes were now unconsciously beginning to mimic.</p></div>\n<div><p>Claiming we would leave the unfortunate role up to luck without singling anyone out was nothing but a convenient facade.</p></div>\n<div><p>In reality, coordinated voting blocs form just as easily for negative penalties as they do for positive rewards. In fact, the psychological mechanics behind a negative vote drive an even stronger need for collusion. ‘Voting as you please’ sounded perfectly fair on paper, but in practice, it immediately sparked a web of mind games. Predictions are made, and people naturally piggyback on those predictions to protect themselves. If that bandwagon effect is left unchecked, it inevitably converges on a single point: the absolute safest, most convenient target.</p></div>\n<div><p>There was no need to wonder who that unlucky target would be.</p></div>\n<div><p>Ike and Shinohara were going to vote for me with one hundred percent certainty. Ibuki would read that and cast a third vote my way.</p></div>\n<div><p>Furthermore, astute students like Katsuragi would anticipate this exact flow and steer their own votes to push me securely into the Unpopular spot.</p></div>\n<div><p>This silent consensus was already spreading rapidly among the students outside of Class C. It was no wonder Sanada looked a bit anxious as he sensed the current solidifying against us, but he couldn't raise an objection. Since we had ostensibly agreed to leave the vote up to individual discretion, he had no grounds to stop it.</p></div>\n<div><p>“Well then, since that's settled, let's just get to voting,” Ike prompted.</p></div>\n<div><p>Short murmurs of agreement echoed around the circle, and the momentum of the room shifted entirely toward executing the vote. Kushida for the Popular Person, and individual discretion for the Unpopular Person.</p></div>\n<div><p>As a discussion, it was over. At least on the surface. Not everyone was entirely satisfied, but digging any deeper would inevitably expose the ugly reality that someone was about to be deliberately sacrificed. Given that fact, it was only natural that the group wanted to slap a lid on the debate while things were still relatively peaceful.</p></div>\n<div><p>In truth, cutting the conversation short here was the correct move for the majority. Probing too deeply could cause the wind to shift in an unpredictable direction. Precisely because they had just openly colluded to concentrate their Popular votes onto a single person, no one wanted to touch the Unpopular vote with a ten-foot pole. The superficial declaration of ‘not deciding’ was functioning perfectly as a collective safety measure.</p></div>\n<div><p>However, naturally, for me who was being targeted, I had no intention of letting the discussion end here.</p></div>\n<div><p>“I'd like to confirm one last thing before we proceed,” I spoke up, cutting through the final moments before the vote. “If we actually leave this up to individual discretion, the Unpopular votes will split. That means multiple students could end up having their tokens halved. Isn't that the absolute worst-case scenario?”</p></div>\n<div><p>“What gives? You're still dragging this out?” Ike groaned. “Enough already. It's not like we've decided the Unpopular Person is gonna be someone from Class C or anything.”</p></div>\n<div><p>His words were laden with thinly veiled subtext. What he was really saying was: <em>You're going to be the Unpopular Person, so a split vote isn't going to happen anyway.</em></p></div>\n<div><p>“I really don't wish to dig this back up either,” Sanada interjected, likely sensing this was his only window of opportunity. “But... in that case, what do you believe is the correct course of action, Ayanokōji-kun?”</p></div>\n<div><p>You could practically feel the irritation rolling off the other classes. This was a topic they desperately wanted to sweep under the rug.</p></div>\n<div><p>“It's a difficult problem,” I answered without missing a beat. “The reality is, being chosen as the Unpopular Person carries nothing but severe demerits.”</p></div>\n<div><p>“Which is precisely why we are conducting an equal, open vote,” Katsuragi stated. “If that results in a tie and multiple people take the penalty, then it simply cannot be helped.”</p></div>\n<div><p>Katsuragi's sharp gaze locked onto mine. His words carried an unmistakable, silent challenge: <em>Show me how you plan to maneuver out of this situation. Let's see how you turn the tide.</em></p></div>\n<div><p>“We concentrate our votes on Kushida, who naturally draws the fewest objections as the ‘Popular Person’ in both name and reality. That guarantees two tokens for all fifteen of us. Up to that point, there’s no problem,” I began, first laying out the premise.</p></div>\n<div><p>“The issue lies with the remaining Unpopular vote. If the votes split apart, there’s a real chance that two or three students could each lose half their tokens instead. To avoid that, we need to predetermine a single Unpopular Person from the very beginning, just as we did for the Popular vote.”</p></div>\n<div><p>“Huh? We're only having this conversation because we <em>can't </em>do that,” Ike scoffed. “What are you—”</p></div>\n<div><p>“I'm not finished,” I cut him off, turning back toward the group. “Therefore, our class will willingly take on the role of the Unpopular Person.”</p></div>\n<div><p>Rather than trusting our fate to some superficial illusion of equality, I was deliberately reaching out to claim the penalty. By doing so, I could steer the situation toward a conclusion that appeared similar, but was fundamentally different.</p></div>\n<div><p>“By accepting the Unpopular penalty in advance, we can establish a framework where the other classes are absolutely guaranteed to suffer zero casualties,” I explained.</p></div>\n<div><p>“Well, yeah. I agree, I totally agree! Right, Satsuki?”</p></div>\n<div><p>“Yeah, I think it's fine. If Class C is willingly volunteering for it, I don't have any complaints.”</p></div>\n<div><p>Since Ike and Shinohara had already internally cast their Unpopular votes for me anyway, neither of them raised a single objection.</p></div>\n<div><p>“However, in exchange for taking the hit, I want Kushida to transfer two tokens to our side after the task ends,” I added. “She will gain five as the Popular Person. Even if she hands over two, she still walks away with three, meaning her individual cut will still be the largest among everyone here.”</p></div>\n<div><p>“Well, if Class C is taking the penalty, I don't mind that condition at all, but…” Kushida began, showing her intent to consent, only for Ike to immediately interrupt.</p></div>\n<div><p>“Hold on, why does Kikyō-chan have to bear the burden for that? That's totally messed up!”</p></div>\n<div><p>“It's not messed up in the slightest,” I countered smoothly. “We are sacrificing ourselves to ensure that multiple Unpopular penalties aren't triggered. I am merely asking her for a slight compensation to mitigate our damage.”</p></div>\n<div><p>Since my role as the Unpopular Person was already locked inside Ike's head, it was no wonder he perceived the tax on Kushida as an utterly meaningless burden.</p></div>\n<div><p>“The logic appears sound,” Katsuragi mused. “In reality, even if Class C receives two compensatory tokens, they won't end up with a net positive. The number of tokens each student possesses at the start differs, but even assuming all four of them started with the bare minimum of two, combined with the earlier reward, their current stash would be three or more. The moment that count is halved, they will lose a minimum of two tokens. The net balance is zero. And if their starting count was any higher, the tokens they lose will only increase.”</p></div>\n<div><p>Because none of the sharper students had started this special exam with the bare minimum of two tokens, it likely hadn't even crossed their minds that someone could mathematically manipulate the penalty to result in a net balance of zero.</p></div>\n<div><p>“But something about this is weird! It might be a trap!” Ike protested.</p></div>\n<div><p>“I don't mind if you doubt my intentions,” I replied. “But if you don't like the proposal, Ike, then <em>you </em>are more than welcome to step up and take on the role of the Unpopular Person. Naturally, you would also be entitled to those two extra tokens as compensation.”</p></div>\n<div><p>“Th-That's... impossible! There's no way I can do that!” Ike immediately backed down, rejecting the offer vehemently.</p></div>\n<div><p>And rightly so. Ike almost certainly held more tokens than the proposed compensation would cover. If he was going to suffer a net loss of even a single token after having his stash halved and gaining the two extras, there was zero chance he would accept the deal.</p></div>\n<div><p>During the Survival Game Special Exam, students like Katsuragi and Ike had managed to survive for a decent chunk of time without getting eliminated. Consequently, they had started this current exam with a comfortable cushion of tokens. It was perfectly understandable if the idea of someone having three or fewer tokens at this stage had completely slipped their minds.</p></div>\n<div><p>Because there wasn't a single student in the other classes who could stomach having their tokens halved, it was practically impossible for them to reject the condition I had proposed.</p></div>\n<div><p>“I wondered how you were going to resolve this deadlock,” Katsuragi said, a hint of begrudging respect in his voice. “I see. So there was that perspective as well.”</p></div>\n<div><p>Even if the other classes wanted to complain out of sheer dissatisfaction, they couldn't offer themselves up as substitutes. Nor could they openly assert that I was going to be the Unpopular Person anyway without exposing their blatant collusion. I had completely cut off any avenue for a counterattack.</p></div>\n<div><p>“Well then, I guess I'll take on the role of the Unpopular Person,” Yoshida announced, raising his hand as if this was exactly the moment he had been waiting for. “Kushida, I'll be counting on those two tokens later.”</p></div>\n<div><p>At his overly casual volunteer, the atmosphere froze for a split second.</p></div>\n<div><p>Logically, everyone understood the concept of someone deliberately taking a loss for the group, but it was rare to see someone actually offer it out loud. Much less in a high-stakes situation where the results directly dictated the immediate loss of one's own tokens.</p></div>\n<div><p>“Hey, if someone has to do it anyway, it's better to just decide quickly and move on,” Yoshida said, looking directly at Ike and Shinohara, who had shown the strongest resistance thus far. “Besides, as far as our class is concerned, it wouldn't be amusing in the slightest if Ayanokōji somehow ended up gathering all the Unpopular votes by some crazy coincidence.”</p></div>\n<div><p>While volunteering subtly hinted that Yoshida possessed a comfortable amount of tokens to burn, it served as an incredibly strong deterrent.</p></div>\n<div><p>“...Well, in terms of actually being the ‘Unpopular Person,’ maybe they aren't wrong, right?” Shinohara muttered. “I still think it's way more natural to just leave it up to everyone and let the votes fall where they may.”</p></div>\n<div><p>Her desire to strike me while the iron was hot was entirely transparent; she wasn't even trying to hide it.</p></div>\n<div><p>“I thought a group was supposed to cooperate wherever possible, right?” Yoshida challenged lightly, flashing a small shrug. “If we just leave it to ‘chance’ here, and by some crazy coincidence a certain someone ends up gathering twelve whole votes... well, that's gonna look more like an organized voting than a coincidence. And honestly, I'd really hate for our cooperative relationship to completely fall apart moving forward.”</p></div>\n<div><p>There was no trace of seriousness in Yoshida's attitude. He hadn't been forced into the role; he had perfectly established the outward appearance of a man undertaking the burden entirely of his own volition for the sake of his class.</p></div>\n<div><p>Since the interests of the four classes would never perfectly align, situations where someone simply had to yield were inevitable. But since someone had stepped up and willingly volunteered to fall on their sword, any remaining justification to drag the discussion out completely evaporated.</p></div>\n<div><p>“You make a fair point. If that is the arrangement, I have no objections,” Katsuragi said with a quiet nod.</p></div>\n<div><p>Sonoda, Minamikata, and the rest of the Class B students exchanged looks, but none of them voiced any strong opposition. Even if they weren't entirely satisfied with the outcome, they likely judged that with no better alternatives on the table, they had no choice but to accept the compromise.</p></div>\n<div><p>Ibuki, too, simply offered a tiny shrug, making no move to interject. She knew perfectly well that pushing the issue any further ran the risk of turning the spearhead back toward herself.</p></div>\n<div><p>As for Class A, even if Ike and Shinohara stubbornly cast their Unpopular votes for me now, there was no guarantee I would rack up more votes than Yoshida. If a clumsy two or three stray votes landed on me, it would only breed suspicion and ultimately shatter our tenuous cooperative relationship.</p></div>\n<div><p>“Fine, I get it,” Ike grumbled. “We just have to vote for Yoshida, right?”</p></div>\n<div><p>And with that, the targets were officially locked in: Kushida, whom the group trusted, and Yoshida, who had stepped up as the sacrificial lamb.</p></div>\n<div><p>Not everyone was thrilled with the result, but it landed squarely on the minimum acceptable line for all four classes. It was a fragile equilibrium, maintained by the mutual understanding that pushing even an inch further would cause the entire discussion to collapse.</p></div>\n<div><p>Following the supervisor's instructions, we all dropped our gazes to our smartwatches. The input process was incredibly simple: one vote for the Popular Person, one vote for the Unpopular Person.</p></div>\n<div><p>In the brief window before the results were finalized, a heavy silence wrapped the space; no one dared to speak.</p></div>\n<div><p>And so, the task reached its conclusion.</p></div>\n<div><p>Once the results were confirmed and the suffocating tension finally broke, Yoshida casually flicked his gaze in my direction. Locking eyes with me for just a split second, he offered a quick thumbs-up.</p></div>\n<div><p>To anyone else watching, it was easily brushed off as the small, self-satisfied gesture of a guy who had just taken a hit to protect his class leader. To the rest of the group, Yoshida's volunteer act looked like a genuine, albeit minor, self-sacrifice. Even if they assumed his token stash was relatively low, they knew he mathematically couldn't profit from the exchange.</p></div>\n<div><p>But the reality was the exact opposite. Yoshida was actually walking away with a pure profit.</p></div>\n<div><p>That was because, through a few prior adjustments behind the scenes, I had already lowered Yoshida's token count down to the absolute minimum of one.<span></span></p></div>\n<div><p>According to the rules, anyone holding only a single token was exempt from the halving penalty. Therefore, even after being officially crowned the Unpopular Person, Yoshida lost absolutely nothing. In fact, since he was now guaranteed to receive those two compensatory tokens from Kushida, the entire maneuver carried zero hidden risks.</p></div>\n<div><p>Shortly before this task began, while we were still inside the tent, Yoshida and I had repeatedly tested the token transfer mechanics. We discovered a few key details. First, the basic condition for a transfer required both parties to operate their smartwatches and physically tap them together, which triggered a default notification sound. However, we realized this chime could be easily muted by simply turning the watch's volume down to zero beforehand.</p></div>\n<div><p>If transfers could be executed just by brushing two watches together, silencing the notification would be a massive security flaw. But since both parties were required to input their personal PINs to authorize a transaction, there was no risk of tokens being stolen in secret. Thus, the school had made the sound notification entirely optional.</p></div>\n<div><p>Next, we tested the actual speed and frequency of the transfers. While the system required you to input your PIN again after each completed transaction, there was practically zero lag. Once we got the hang of it, we found we could continuously fire off transfers in about ten seconds flat. You could send tokens one at a time on loop, or dump them all in a single lump sum.</p></div>\n<div><p>During our testing, we also discovered that the system threw up a severe warning error if you attempted to initiate a transfer when your balance was already down to one token.</p></div>\n<div><p>The fact that this special exam carries a risk of reducing tokens to zero implies that the rules allow for them to be stripped away during the challenges, not just through peer-to-peer transfers.</p></div>\n<div><p>However, if a challenge capable of draining three or four tokens were introduced right at the outset, students who started with a baseline of only two would face an immediate checkmate.</p></div>\n<div><p>My modeling of the school's habits suggested as much. If they intended to inject a negative element this early, they would opt for a mechanism like ‘halving’ to ensure a zero-balance was impossible.</p></div>\n<div><p>Still, to think I would be able to exploit that exact mechanic this early in the exam... things had worked out almost a little too perfectly.</p></div>\n<div><h2>Part 5</h2></div>\n<div><p>The previous task had barely concluded before the supervisor began tapping away at his tablet, offering no hint of a dismissal.</p></div>\n<div><p>“I have officially recorded the results and distributed your tokens,” he announced. “Now, we will take a brief five-minute intermission, after which we will commence the final individual task of the day. Thank you for your cooperation.”</p></div>\n<div><p>“You've gotta be kidding me. There's <em>another </em>one?”</p></div>\n<div><p>Groans of dismay rose from the girls first, who had clearly assumed we would be moving straight into free time before bed. Echoing their sentiment, murmurs of discontent began rippling through the boys as well.</p></div>\n<div><p>It was a four-day, three-night special exam. Tomorrow would likely be the main event, but even for a day focused mostly on talking, this schedule was relentless.</p></div>\n<div><p>True to her word, Kushida transferred two tokens to Yoshida. While some students killed the brief intermission by checking their smartwatch balances, it wasn't long before the exam was set in motion once more.</p></div>\n<div><p>“I will now explain the final task,” the supervisor began. “This one leans closer to a gamble, relying heavily on elements of luck. You can think of it as a simple game. However, because of its nature, I must first confirm whether or not each of you actually wishes to participate. Should you choose to play, you will be required to wager, and potentially lose, two tokens upon defeat.”</p></div>\n<div><p>“So participation is entirely voluntary... right?” Sanada asked cautiously.</p></div>\n<div><p>The supervisor gave a curt nod. “Yes. For instance, if you currently hold two or fewer tokens, you may choose to sit this one out. Alternatively, if you simply do not wish to shoulder the risk of losing, you are well within your rights to decline. However, choosing to abstain carries a penalty: you must pay one token as compensation.”</p></div>\n<div><p>We were faced with a choice: risk losing two tokens for a chance at victory, or pay a flat fee of one token to guarantee your safety.</p></div>\n<div><p>“I mean, you'd normally just play, right? Isn't it completely stupid to spend a token just to <em>not </em>participate?” Ike scoffed.</p></div>\n<div><p>“I wouldn't be so sure,” Katsuragi countered. “True, if your sole focus is hoarding personal tokens, maximizing your participation is the mathematically correct choice. However, if your absolute priority is avoiding expulsion at all costs, paying one token to sidestep a two-token loss is equally valid.”</p></div>\n<div><p>It was a running theme today, dilemmas where a single, objective ‘correct answer’ simply didn't exist. Regardless, the harsh reality was that very few students in our group could actually afford to casually bleed a token just to sit on the sidelines. In the end, everyone opted to participate.</p></div>\n<div><p>The supervisor announced the winner's reward, a handsome five tokens, and the task officially began.</p></div>\n<div><p>“I hold in my hands sixteen folded slips of paper,” the supervisor said, fanning them out. “There are exactly two slips for each number between one and eight. You will be facing off against the student who draws the same number as you. I will explain the rules shortly, so for now, please come forward and draw your lot. Do not unfold your paper until I give the signal.”</p></div>\n<div><p>Without any designated order, the students closest to the front stepped up first. I went sixth, drawing a folded slip and returning to my spot.</p></div>\n<div><p>“You may now check your numbers,” the supervisor instructed. “I will collect the slips afterward, so please refrain from tearing or crumpling them.”</p></div>\n<div><p>Bathed in the pale moonlight, the sixteen members of Group 3 simultaneously unfolded their slips. I glanced down at my palm. The number written there was ‘4’.</p></div>\n<div><p>“Please sit facing your designated opponent, arranged in numerical order starting from pair number one. I will now collect your slips.”</p></div>\n<div><p>As the supervisor gathered the scrap paper, he distributed a hand of five playing cards to each student. The backs featured a uniform, standard pattern, but the faces were unique: each card bore a single odd number— 1, 3, 5, 7, and 9— arranged sequentially in our hands. Catching a glimpse of the students to my left and right, I confirmed their hands consisted of the exact same 1-through-9 odd-number lineup.</p></div>\n<div><p>The matchups were as follows: Pair 1 was Katsuragi and Morishita. Pair 2 was Ibuki and Morofuji. Pair 3, Minamikata and Sonoda. Pair 4 was me and Wang. Pair 5, Ike and Kushida. Pair 6, Amikura and Shinohara. Pair 7, Yoshida and Sumida. And rounding it out, Pair 8 was Sanada and Moriyama.</p></div>\n<div><p>“Umm, Ike-kun and I are both in Class A,” Kushida raised her hand tentatively. “Do we still have to play against each other?”</p></div>\n<div><p>“Yes. Your class affiliations are completely irrelevant for this task,” the supervisor replied flatly.</p></div>\n<div><p>Given the bare-minimum explanation, Kushida blinked in mild bewilderment but obediently nodded her understanding.</p></div>\n<div><p>“The rules are simple,” the supervisor continued. “In each round, both players will select one card from their hand and place it face down. You will then reveal them simultaneously. The player who plays the higher number wins the round. If the numbers match, the round is a draw. Once a card has been played, it is consumed and cannot be used again. The first student to secure two wins will be declared the overall victor. The winner will acquire five tokens, while the loser will forfeit the two tokens they initially wagered. In the rare event of a complete draw after all five cards are consumed, you will retrieve your hands and play an overtime match until a single win is secured. Excluding the overtime match, please aim to finish within approximately 5 minutes.\"</p></div>\n<div><p>By giving a soft five-minute guideline rather than a hard limit, the school was implicitly warning us against deliberately stalling or overthinking. If a match dragged on for seven or eight minutes, it probably wouldn't result in an instant disqualification, but it wouldn't be surprising if a penalty was slapped onto whichever player was burning the clock.</p></div>\n<div><p>“I-I look forward to our match.” Wearing an incredibly nervous expression, Mii-chan offered a slight bow from across.</p></div>\n<div><p>She was clutching her five cards tightly to her chest; naturally, from my seated position, the numbers facing her were completely hidden from view.</p></div>\n<div><p>“Likewise,” I replied evenly.</p></div>\n<div><p>Then, at the supervisor's signal, the eight matches began simultaneously.</p></div>\n<div><p>I didn't hesitate. I instantly pulled the ‘7’ from my hand and slapped it face down on the ground.</p></div>\n<div><p>“Th-That was fast,” Mii-chan stammered, clearly taken aback.</p></div>\n<div><p>“It's purely a game of luck, anyway. I'm just thinking we should get this over with quickly,” I replied smoothly.</p></div>\n<div><p>I could hear some of the other students already starting to chatter, trying to engage their opponents in conversational mind games to fish for tells within the allotted time. I had no intention of doing that.</p></div>\n<div><p>“R-Right... umm, umm, then I'll…”</p></div>\n<div><p>Based on Mii-chan's personality alone, it was impossible to deduce whether she would open with a weak card or come out swinging with a strong one. There simply wasn't enough data. However, knowing her timid nature, it was incredibly easy to predict exactly how my words and actions would influence her.</p></div>\n<div><p>By declaring right out of the gate that this was a game of pure luck and actively shutting down any attempt at conversational strategy, I forced her to subconsciously accept that she had to play the same way. Granted, she wasn't the type to excel at that kind of verbal sparring anyway, but my dismissal completely sealed her lips. Furthermore, because her opponent had played a card instantly, she was suddenly hit with a wave of mounting pressure to hurry up and match my pace.</p></div>\n<div><p>Her fingertips hovered hesitantly over her hand. But she couldn't afford to take her time.</p></div>\n<div><p>Her hand darted out, grabbing the card perfectly in the center of her fan and placing it face down.</p></div>\n<div><p>“I'll go with this one…”</p></div>\n<div><p>“Let's flip them, then.”</p></div>\n<div><p>“Y-Yes.”</p></div>\n<div><p>Without even pausing to ask if she wanted to swap her card, we executed our first round. We were the fastest out of all eight pairs by a massive margin. The sheer speed of our match was so jarring that it actually drew the attention of Shinohara and the others sitting nearby.</p></div>\n<div><p>The cards were revealed. Naturally, mine was the ‘7’. Mii-chan's was a ‘5’.</p></div>\n<div><p>“Ah―”</p></div>\n<div><p>“Let's move right to the next one,” I said, cutting off any emotional reaction to the win or loss.</p></div>\n<div><p>Now, I immediately set my ‘9’ card face down.</p></div>\n<div><p>Faced with my relentless pace, Mii-chan's thought process clearly short-circuited for a second.</p></div>\n<div><p>The moment I clinched the opening round by crushing her ‘5’ with my ‘7’, the tide of the entire match swung heavily in my favor. As long as my ‘9’ wasn't canceled out by a tie, my overall victory was mathematically guaranteed.</p></div>\n<div><p>Looking flustered, Mii-chan gave a small, nervous gulp before decisively slapping her next card face down on the ground.</p></div>\n<div><p>The moment her hand left the card, I snatched my ‘9’ back up, swapping it for a different card from my hand and setting it face down instead.</p></div>\n<div><p>“You're... changing it?” she blinked.</p></div>\n<div><p>“There's no rule saying I can't swap my card before we reveal,” I pointed out. “If you want to change yours, Mii-chan, you're more than welcome to.”</p></div>\n<div><p>“Eh? Umm... no, I'm fine with this…”</p></div>\n<div><p>“Let's flip them, then.”</p></div>\n<div><p>Having obtained mutual consent, we turned the cards over. My number was ‘1’. Mii-chan's was ‘9’.</p></div>\n<div><p>With that, we were tied at one win apiece. However, because she had just burned her strongest card, my victory was now entirely locked in the moment I played my ‘9’.</p></div>\n<div><p>“Auu... I lost,” Mii-chan realized, her shoulders slumping.</p></div>\n<div><p>“Let's just play the final round properly as a formality,” I said.</p></div>\n<div><p>“...Okay.”</p></div>\n<div><p>Before a completely frozen Mii-chan, I quickly placed my third card face down.</p></div>\n<div><p>Naturally, that number was ‘9’. The card Mii-chan despairingly revealed was her ‘7’.</p></div>\n<div><p>“We're finished,” I reported to the supervisor, my tone flat.</p></div>\n<div><p>At this point, most of the other pairs were still just finishing up their opening rounds.</p></div>\n<div><p>Right now, Mii-chan was probably lamenting her terrible luck, convinced that the game had just been an unfortunate turn of events.</p></div>\n<div><p>But that wasn't true at all.</p></div>\n<div><p>Precisely because the game was so mind-numbingly simple, it was incredibly easy to overlook a fatal flaw in the initial setup: the default structure of the hand.</p></div>\n<div><p>When the supervisor dealt the five cards, they were perfectly arranged in numerical order. From the exact second the cards were handed to Mii-chan, I had been watching exactly how she held them. If she had shuffled her hand, or hidden the cards behind her back to reorder them, keeping track of their locations would have become impossible. However, she had gripped the cards in her hand exactly as they were dealt.</p></div>\n<div><p>Under normal circumstances, once the match officially started, she probably would have unconsciously shuffled her hand out of habit. But by playing my card instantly and aggressively rushing her, I completely deleted the concept of ‘shuffling’ from her mind. By making her feel like rearranging her hand was pointless since her opponent was already waiting, I crushed her under the pressure to simply play a card <em>now.</em></p></div>\n<div><p>From there, the rest was practically automatic. Because I knew exactly where every number was in her hand, all I had to do was observe which card she pulled and swap my own card to guarantee the highest possible win rate. If she had managed to shake off the pressure in the second round and scrambled her hand, I would have simply pivoted my strategy to using conversation to fish for tells.</p></div>\n<div><p>It just so happened that this time, even that wasn't necessary.</p></div>\n<div><p>Shortly after our match concluded, the other pairs began to settle their games sequentially. While a few cases dragged into overtime, the final victors were Katsuragi, Morofuji, Minamikata, Ike, Amikura, Yoshida, and Sanada.</p></div>\n<div><p>Chapter 2 Ends. Join our Discord (<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://discord.gg/v9kBpcCH2Y\">https://discord.gg/v9kBpcCH2Y</a>) to get information on release dates and to have fun with fellow cote fans!</p></div>",
    "4": "<div><p>At six-thirty on the second day, the sun crested over the island, signaling the arrival of morning.</p></div>\n<div><p>The light was still young, pale at the edges, filtering through the fabric of the tent in a muted glow. I woke to the faint sound of footsteps approaching through the quiet morning air, then slowly pushed myself upright.</p></div>\n<div><p>Beside me, Yoshida and Sanada were still asleep. Their breathing remained calm and even, completely undisturbed by the presence outside.</p></div>\n<div><p>Peering out of my tent, I found Katsuragi standing nearby.</p></div>\n<div><p>For a brief moment, a faint look of surprise crossed his face, as though he hadn't expected me to emerge so quickly. But he quickly composed himself and offered a brief greeting.</p></div>\n<div><p>“Good morning.”</p></div>\n<div><p>I returned the greeting and stepped out into the morning air.</p></div>\n<div><p>“Sorry,” Katsuragi said. “Did I wake you up?”</p></div>\n<div><p>“I was already awake.”</p></div>\n<div><p>“I see.” He paused briefly before continuing. “I hate to ask this first thing in the morning, but I’d like a little bit of your time. There’s something I want to discuss regarding this special exam before the second day’s assignments begin.”</p></div>\n<div><p>Whether he had spent the night reaching his own conclusions, or if Ryūen had fed him instructions behind the scenes, I couldn’t tell.</p></div>\n<div><p>Still, I nodded and quietly followed him. Once we were a safe distance away from the tents, Katsuragi stopped and turned to face me.</p></div>\n<div><p>“In this special exam, there are several penalties that carry the risk of expulsion,” he began. “Among them, the only one that absolutely cannot be avoided is the expulsion tied to finishing in last place. Even if every student were to tie, it still cannot be bypassed. However, depending on the circumstances, I'm sure you understand that it can be overcome rather easily, don’t you?”</p></div>\n<div><p>“A student with a Protection Point could become the scapegoat instead,” I said. “Assuming things work out cleanly enough to make that possible.”</p></div>\n<div><p>“That’s right.” Katsuragi gave a small nod. “If this were only a problem within a single class, self-sacrifice would be a highly viable strategy. But in a competition involving the entire grade, that kind of sacrifice could easily end up benefiting the enemy.”</p></div>\n<div><p>“If there’s anyone who’d self-sacrifice without caring whether it benefited allies or enemies, it would probably be someone from Ichinose’s class.”</p></div>\n<div><p>Hearing that, Katsuragi fell silent for a moment.</p></div>\n<div><p>“…Is there anyone in Ichinose’s class who has a protection point?”</p></div>\n<div><p>There were certain details that had not been disclosed to the other classes. Katsuragi slipped the question in casually, as though it were nothing more than a natural extension of the conversation.</p></div>\n<div><p>“Sorry, but I wouldn’t know,” I replied. “And even if I did, I wouldn’t tell you.”</p></div>\n<div><p>“…Fair enough.”</p></div>\n<div><p>The internal situation of Ichinose’s class wasn’t something I could casually discuss with a rivalling class.</p></div>\n<div><p>In truth, I had already confirmed that, at present, no one in Class D possessed a protection point, not even Ichinose. Unfortunately, that meant executing such a strategy was entirely off the table.</p></div>\n<div><p>“This is just my own speculation,” I continued, “but regardless of whether she has a protection point or not, I believe Ichinose will hold off on making a move until the bitter end. While she wouldn’t hesitate for a second if it meant protecting her own classmates, the current Ichinose isn’t about to extend that same courtesy to the other classes.”</p></div>\n<div><p>“If your prediction holds true,” Katsuragi mused, “then unless a student with a Protection Point coincidentally ends up at the bottom, there’s a very high chance someone gets expelled the day after tomorrow. And since nobody can see the total token counts across the entire grade, students will naturally focus less on token multipliers and more on simply avoiding last place within their own group.”</p></div>\n<div><p>That alone would become enough of a psychological anchor.</p></div>\n<div><p>If someone could confirm they possessed even slightly more tokens than another student, it would at least provide temporary reassurance.</p></div>\n<div><p>Of course, reality was nowhere near that simple.</p></div>\n<div><p>Unless you physically verified someone’s token count, certainty was impossible.</p></div>\n<div><p>Furthermore, since tokens could be freely transferred twenty-four hours a day, that underlying anxiety surrounding the rankings could never truly be dispelled.</p></div>\n<div><p>“So, what do you plan to do?” Katsuragi asked.</p></div>\n<div><p>“That’s a rather straightforward question,” I replied. “Are you really that curious about my next move?”</p></div>\n<div><p>“There’s only so much I can do,” Katsuragi said calmly. “I don’t want anyone from Class B getting expelled, but I can’t keep track of classmates outside my own group. So at the very least, I want to make sure nobody in the group I’m assigned to gets expelled.”</p></div>\n<div><p>Katsuragi wasn't the only one who felt that way. In fact, the vast majority of the student body likely shared his sentiment.</p></div>\n<div><p>Allowing an expulsion to emerge from your own group carried a heavy burden of collective responsibility. That’s why it was only natural to want to save those within one's reach.</p></div>\n<div><p>“The way you went after Ike and Shinohara yesterday…” Katsuragi continued. “Wasn’t there a reason behind that as well?”</p></div>\n<div><p>The way Katsuragi framed the question made it clear he didn't believe I had picked a fight for no reason, nor did he think my attitude was born from petty personal grievances.</p></div>\n<div><p>However, I gave a light shake of my head, brushing off his suspicions.</p></div>\n<div><p>“If that’s what you thought, then I'm afraid you’re overestimating me,” I said. “Those two and I simply don’t get along.”</p></div>\n<div><p>“Are you saying you provoked your own group members based on personal feelings?” Katsuragi frowned slightly. “That seems highly uncharacteristic of you. I always thought you were the calm and quiet type.”</p></div>\n<div><p>“Ike and the others said it too, didn’t they?” I replied. “That maybe I revealed my true colours after becoming the class leader.”</p></div>\n<div><p>Katsuragi fell silent for a moment, studying me.</p></div>\n<div><p>“…I find that rather hard to believe,” he said at last. “But fine.”</p></div>\n<div><p>Perhaps sensing that pressing any further wouldn't get him any closer to the truth, Katsuragi steered the conversation forward.</p></div>\n<div><p>“Whatever your true intentions may be, our fundamental priorities should still align. Neither of us wants to see our classmates expelled. With that as a given, surely there’s room for us to cooperate in certain areas?”</p></div>\n<div><p>“It’s true that as members of the same group, there are areas where we can work together,” I replied. “But on a fundamental level, your way of thinking about the penalties differs greatly from mine. Joining hands might prove difficult.”</p></div>\n<div><p>“Differs...?”</p></div>\n<div><p>“Katsuragi, your desire to avoid expulsions stems entirely from the fact that they’re your classmates.”</p></div>\n<div><p>I paused briefly before continuing.</p></div>\n<div><p>“But drawing an arbitrary line between your own class and the others misses the point entirely. The real question is whether or not a student actually has the value required to survive this special exam. Whether they’re a member of the same group or the same class is irrelevant. If they don’t measure up to that standard, then their expulsion is simply inevitable.”</p></div>\n<div><p>Katsuragi listened quietly before responding.</p></div>\n<div><p>“I won’t deny that logic,” he said. “But treating everyone with perfect objectivity is far easier said than done. Furthermore, prioritizing one’s allies is not wrong. Rather, it’s a completely natural instinct. That isn’t just a rule born of this special exam; if you look back through human history, you’ll find the exact same principle at work.”</p></div>\n<div><p>Whether they shared the same birthplace. The same race. The same nation.</p></div>\n<div><p>Humanity has always drawn a line somewhere. Once those boundaries were set, people fought with everything they had to protect those they deemed allies, and struck down those they recognized as enemies.</p></div>\n<div><p>“I’m not saying that you have to think the same way,” Katsuragi concluded. “But that is what I believe the natural order should be.”</p></div>\n<div><p>It wasn't about forcing a specific outcome upon anyone.</p></div>\n<div><p>Rather, within the natural framework of society itself, those destined to receive penalties would emerge on their own, and those unfit to remain would quietly disappear.</p></div>\n<div><p>“So then, are you saying you would be fine with a student from Class C finishing last and being expelled in this exam?” Katsuragi’s brow furrowed. “If that is the case, then perhaps our views on penalties really are different.”</p></div>\n<div><p>His voice remained calm.</p></div>\n<div><p>“But if you truly think that way, I have to say… I’m somewhat disappointed.”</p></div>\n<div><p>“Eliminating those who lack ability or who disrupt the harmony of the class often triggers a self-purifying effect,” I replied with ease. “Of course, I’m not saying every student expelled so far fell into that category. But at the same time Yamauchi, Sakura, and Maezono disappeared. And though it happened before you transferred, Manabe was cut from Ryuen’s class as well. While losing numbers puts a class at a disadvantage, looking at the bigger picture, it isn't entirely a net loss.”</p></div>\n<div><p>It wasn’t the kind of logic that would ever resonate with someone like Katsuragi, who sought to protect his comrades. Then again, very few people would ever enjoy hearing something so callous.</p></div>\n<div><p>“Sorry for taking up your time so early in the morning.”</p></div>\n<div><p>It was a brief exchange, lasting less than five minutes. Katsuragi gave a single, curt nod, offered a brief apology, and walked back to his tent, making no effort to hide his disappointment in me.</p></div>\n<div><p>By the time we separated, it was just past seven in the morning.</p></div>\n<div><p>After waiting a short while, I returned to Class C’s tent. Yoshida was already awake, busying himself outside the tent with breakfast preparations. Sanada was up as well, working on some chores a short distance away.</p></div>\n<div><p>“Looks like you and Katsuragi were talking for quite a while, huh?” Yoshida remarked.</p></div>\n<div><p>“You noticed?”</p></div>\n<div><p>“After you left the tent, I heard Katsuragi’s voice for a bit,” he said. “I was curious, but I figured it’d be rude to interrupt. Was it about the special exam?”</p></div>\n<div><p>Since he already knew I had gone outside to talk, there was probably no need to hide it.</p></div>\n<div><p>“He asked whether we could cooperate to prevent expulsions from our classes.”</p></div>\n<div><p>“So, are you planning to team up with Class B?”</p></div>\n<div><p>There was no approval or objection in Yoshida’s voice. He simply seemed interested in what decision I would make as the leader.</p></div>\n<div><p>“Unfortunately, the negotiation broke down,” I said. “This isn’t a problem that can be solved between two classes alone anyway. Still, on this second day, we may start seeing movements in various places as people attempt for that kind of cooperation.”</p></div>\n<div><p>“Then we’d better keep our eyes peeled.”</p></div>\n<div><p>Yoshida’s expression hardened as he cast a wary, sweeping glance toward the tents of the other classes.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>Shortly after finishing breakfast with Yoshida and the others, the supervisor’s instructions echoed across the campsite.</p></div>\n<div><p>“Now then, I would like to announce the first task of the day. You will be taking on a large number of tasks starting this morning, so please remain focused and approach them with care.”</p></div>\n<div><p>Retrieving four tablets, he distributed one to each class representative.</p></div>\n<div><p>“For this ‘Team’ task, four classes will compete in a simple academic test, taking turns using a tablet. The order in which the four members of each team take the test is completely random. First place will receive 3 tokens, second place 2 tokens, third place 1 token, and fourth place will receive no reward.”</p></div>\n<div><p>With that preface complete, the supervisor started announcing details.</p></div>\n<div><p>If all four members of a class won their rounds, the class could earn twelve tokens. On the other hand, if all four finished last, they would walk away with nothing.</p></div>\n<div><p>There was no direct risk attached to the task. Even so, it was the kind of test that could create subtle disparities in the number of tokens held by each class.</p></div>\n<div><p>The important thing was the order in which we tackled the test. Rather than having top-tier students clash head-to-head, the ideal scenario was to be paired against opponents you could edge out by a narrow margin. For our Class C lineup, the randomized order fell to Morishita, Sanada, Yoshida, and myself.</p></div>\n<div><p>True to the supervisor’s word, the format was remarkably simple. Each round consisted of ten multiple-choice questions with five possible answers, drawn from a specific subject. If two or more students had the same number of correct answers, their ranking would be decided by the time taken to complete all ten questions.</p></div>\n<div><p>Morishita placed third in her round, and Sanada took first in his. Yoshida went next, but his opponents were Katsuragi, Mii-chan, and Amikura. With that lineup, he ended in fourth place. Finally, I anchored the group and secured a first-place finish.</p></div>\n<div><p>In total, Class C walked away with seven tokens. Over in Class A, despite Ike and Shinohara finishing dead last in their respective rounds, Kushida and Mii-chan were blessed with favorable matchups and both secured first place, bringing their total to six tokens. Class B earned five, while Class D matched Class A with six.</p></div>\n<div><p>All things considered, the opening task had produced almost no significant difference between the classes.</p></div>\n<div><p>“The gap didn’t widen nearly as much as I expected,” Yoshida muttered.</p></div>\n<div><p>He was right. As a single task, the difference amounted to only one or two tokens, well within the margin of error.</p></div>\n<div><p>However, judging from how smoothly the first task had been carried out, it was unlikely that things would end with just this.</p></div>\n<div><p>“Now then, we will move on to the next task. The order will once again be randomized.”</p></div>\n<div><p>The supervisor announced that the subject would change, and there on the uninhabited island, we once again turned toward the tablets.</p></div>\n<div><p>In total, we repeated the same process five times.</p></div>\n<div><p>At first, the results had been separated by only narrow margins. But as luck and ability began to show their uneven distribution, the scores gradually converged toward what could be called their natural expected values.</p></div>\n<div><p>From the second round onward, the tasks proceeded without changing format, but their underlying nature had certainly transformed. While the luck of the matchups and coincidence had influenced the results in the first round, as the rounds repeated, those elements were gradually filtered out, allowing each individual's pure academic and processing abilities to manifest directly as their rankings.</p></div>\n<div><p>The simple structure of ten multiple-choice questions stripped away any room for bluffing.</p></div>\n<div><p>Since ties in correct answers were decided by time, nearly perfect scores became the standard among the top students. Ultimately, the deciding factor became how efficiently one could process the questions without wasting time.</p></div>\n<div><p>The lack of hesitation, the speed of grasping the question's intent, and the accuracy in eliminating options. A slight delay in any one of those areas alone was enough to make someone fall one or even two ranks lower.</p></div>\n<div><p>Among all of them, the two who consistently remained near the top were Sanada and Katsuragi.</p></div>\n<div><p>Sanada was consistent from beginning to end. No matter what kind of question appeared before him, his judgment never dulled.</p></div>\n<div><p>The efficiency with which he operated made it seem as though his answer had already been decided the instant he finished reading the question, placing him far above the others in balancing speed and precision.</p></div>\n<div><p>Katsuragi, meanwhile, approached the competition differently.</p></div>\n<div><p>Rather than securing a perfect score, he prioritized staying firmly in the upper ranks. By dedicating time only to the necessary portions, he optimized his overall processing. As a result, he displayed great strength in time-based tie-breakers and made remarkably few mistakes.</p></div>\n<div><p>Just beneath those two, another layer of students gradually began to emerge:</p></div>\n<div><p>Mii-chan and Kushida.</p></div>\n<div><p>Neither possessed blistering speed, but they rarely misread a question. Their unshakeable grasp of the fundamentals ensured they never suffered any major collapses.</p></div>\n<div><p>Kushida finished last in the second round, but from the middle stages onward, she regained her balance. Once her rhythm returned, she began steadily stacking up correct answers, one after another.</p></div>\n<div><p>Mii-chan, meanwhile, progressed through the problems at the same rhythm throughout, leading to minimal fluctuations in her ranking, fulfilling a role where she steadily picked up 2nd and 3rd place finishes.</p></div>\n<div><p>In a prolonged competition like this, the existence of students who simply remained consistent and didn’t make mistakes translated directly into a steady accumulation of tokens.</p></div>\n<div><p>Of course, not everyone adapted so smoothly.</p></div>\n<div><p>As the rounds continued, the faces repeatedly settling near the bottom also became increasingly clear.</p></div>\n<div><p>Among them, Ibuki’s decline stood out the most.</p></div>\n<div><p>The questions themselves weren’t exceptionally difficult.</p></div>\n<div><p>Even so, Ibuki had a terrible habit of abandoning a problem before fully grasping its intent. The moment her understanding faltered, she'd simply give up and select an answer, practically leaving the outcome to chance.</p></div>\n<div><p>At first glance, that kind of decision-making might have looked efficient. It certainly allowed her to move quickly. But without any solid reasoning backing her choices, her results were inherently unstable.</p></div>\n<div><p>While she occasionally managed to scrape together a correct answer by sheer fluke, those fleeting moments of luck didn’t continue. As the rounds piled up, probability smoothed out the fluctuations, and her ranking naturally drifted to the bottom.</p></div>\n<div><p>It wasn't a temporary stroke of bad luck, but rather the consequence of her deeply flawed approach.</p></div>\n<div><p>What came as a mild surprise was the performance of Ike and Shinohara, two students who similarly struggled with academics.</p></div>\n<div><p>Contrary to initial expectations, they didn't throw in the towel on the questions, maintaining their stance of trying to get as close to the correct answer as possible within their limited knowledge. They scrutinized the options one by one, and while hesitating, attached reasoning to narrow down their answers. Their process could by no means be called efficient, and there were many moments where they needed time to make a decision, but at the very least, they did not abandon thinking.</p></div>\n<div><p>Unfortunately, their earnest effort didn't directly translate into favorable results. They simply couldn't bridge the gap left by their lack of foundational knowledge, which put a hard ceiling on their total correct answers. Furthermore, their extreme caution severely inflated their completion times, putting them at a massive disadvantage whenever a tie-breaker occurred.</p></div>\n<div><p>Consequently, they remained firmly entrenched in the lower ranks. While they rarely sank to dead last like Ibuki, they could never quite manage to break out of the bottom two or three spots.</p></div>\n<div><p>By the time all five trials had concluded, a gradual yet undeniable gap in the token counts had emerged between the classes.</p></div>\n<div><p>In the first round, differences of one or two places had been no more than margins of error. But with each repetition, those small differences accumulated. Eventually, they turned into a gap that could no longer be ignored.</p></div>\n<div><p>The divide wasn't overwhelmingly dramatic, but that was precisely what made it so difficult to overturn. More than anything, it was a perfectly accurate reflection of genuine ability.</p></div>\n<div><p>In other words, success here wasn’t determined by one standalone win, but by who could keep performing under pressure and produce results consistently.</p></div>\n<div><p>It ultimately boiled down to one single metric: the fundamental ability of the students.</p></div>\n<div><p>And those who failed to meet that standard were quietly and inevitably left behind.</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>Up until now, the uninhabited island exam had been a primarily physical ordeal. Following this abrupt shift to intense mental exertion, the exhausted students simply collapsed right where they stood the moment a break was called.</p></div>\n<div><p>Unlike the sharp, burning ache of physical fatigue, this prolonged mental strain left a dull, lingering heaviness in the back of their minds. Unable to immediately shift gears and plan their next move, everyone simply surrendered to the brief, heavy silence.</p></div>\n<div><p>During this respite, the students naturally gravitated toward their own classmates, keeping a wary distance from the other groups. The class representatives then began the meticulous work of distributing the tokens earned from the tasks, adhering to their own pre-established rules.</p></div>\n<div><p>Our Class C was no exception.</p></div>\n<div><p>I took our total earnings and divided them by four, handing out the respective shares to Yoshida, Morishita, and Sanada. I intentionally opted for a completely even split, choosing not to stagger the distribution based on individual performance.</p></div>\n<div><p>“Ike keeps glancing over here,” Yoshida muttered.</p></div>\n<div><p>“Don’t worry about it,” I replied. “It isn’t just us. He’s curious about all three classes.”</p></div>\n<div><p>After all, the distribution of tokens was far more than a simple payout of rewards. It was a display of one's contributions laid bare as a numerical value. Naturally, people couldn't help but unconsciously fixate on the shares their peers were taking home.</p></div>\n<div><p>“It is a battle against the fear of ending up last, after all,” Sanada said.</p></div>\n<div><p>Perhaps his lenses had become dirty, as he quietly removed his glasses and wiped them with the edge of his shirt.</p></div>\n<div><p>“I have no idea who’s getting how many tokens,” Yoshida said after checking the amount he had been given. His eyes drifted, casually toward the other three classes. “Even looking at it by class, it’s getting harder to tell how much of a gap has opened up.”</p></div>\n<div><p>Since most of our focus had been devoted entirely to the tests themselves, it wasn’t surprising that nobody had perfectly tracked who placed where in every round.</p></div>\n<div><p>“I’m starting to feel a little anxious myself,” Morishita said. “Please give me five extra tokens for emotional stability.”</p></div>\n<div><p>I decided to ignore her unreasonable demand.</p></div>\n<div><p>More than the rankings themselves, what lingered in everyone’s minds were fragmented impressions and half-seen results. People tried piecing those fragments together to grasp the larger picture, but there simply wasn’t enough information to arrive at certainty. And that looming ambiguity only fanned the flames of everyone's anxiety.</p></div>\n<div><p>“Katsuragi-kun, Wang-san, and Kushida-san all seemed to be steadily taking higher places,” Sanada said. “So if we look at it by class, there may not actually be as much of a gap as we think.”</p></div>\n<div><p>Sanada, who had a clearer grasp of the situation than Yoshida, answered with calm precision.</p></div>\n<div><p>His words merely traced the facts. Even so, there was more behind them. On one hand, they carried the reassurance that, at this moment, no decisive gap had yet formed. On the other, they implied that precisely because things remained close, the next move could cause everything to shift at once.</p></div>\n<div><p>Of course, it was true that the gaps between classes were widening little by little.</p></div>\n<div><p>But each task offered only a limited number of tokens, so the difference had not yet opened dramatically. That much was also true.</p></div>\n<div><p>However, that applied only when looking at the whole. When viewing the results by team.</p></div>\n<div><p>Since each individual’s performance appeared directly as numbers, the situation within each class was different. Even among classmates, differences had begun to spread quietly, but surely.</p></div>\n<div><p>If we turned our attention to the individual level, the gaps were probably reaching the point where they would begin to widen faster than expected.</p></div>\n<div><p>“Wait a second!” Ibuki’s voice suddenly cut through the break. “What do you mean I only get two?!”</p></div>\n<div><p>Under normal circumstances, the exact number of tokens someone received was not information that should be allowed to leak to other classes. It was strategic data, the kind of thing better kept hidden.</p></div>\n<div><p>But in a class where distribution itself was based on comparing individual contributions, complete secrecy was rather difficult to maintain. And when the result was one a student could not accept, dissatisfaction had a way of spilling out before anyone could contain it.</p></div>\n<div><p>Ibuki, furious, seemed to have no thought at all for the information she was exposing. She rounded on Katsuragi and began shouting loudly enough for everyone nearby to hear.</p></div>\n<div><p>Her emotions had overtaken her. Profit, loss, risk, none of that seemed to matter in the moment. The only thing driving her actions was the fact that she could not accept the result.</p></div>\n<div><p>“I told you from the very beginning,” Katsuragi replied firmly. “Tokens would be distributed fairly, based on your performance. The tasks thus far have centered entirely around academics, which is your weak point, and you significantly dragged us down. You finished last every time. If anything, I could say I judged you leniently by giving you a reward at all.”</p></div>\n<div><p>His words contained no visible emotion. But for that very reason, they allowed no ambiguity. Katsuragi did not try to soften the truth or dress it in comfort. He simply placed the facts before her and, by doing so, closed off any room for rebuttal.</p></div>\n<div><p>The remaining two members of Class B seemed to have no objection to his reasoning. If anything, they appeared to agree.</p></div>\n<div><p>As long as the standard for distribution was clear, introducing personal feelings into it would only create the possibility that they themselves might be disadvantaged later. There was no reason for them to deny Katsuragi here.</p></div>\n<div><p>They had seen it themselves. Ibuki had finished last in every round.</p></div>\n<div><p>In other words, the number of tokens Ibuki had personally earned was zero. From that perspective, giving her even two tokens could only be described as Katsuragi’s generosity.</p></div>\n<div><p>\"Are you trying to make me come in last or something?\" Ibuki snapped.</p></div>\n<div><p>“Don’t be ridiculous,” Katsuragi replied. “I have not the slightest desire to see anyone from our class expelled. However, if I distributed tokens equally even to a student who dragged us down, I would be causing trouble for Sonoda and Morofuji.”</p></div>\n<div><p>His gaze remained steady.</p></div>\n<div><p>“This is a special exam where expulsion is at stake. I absolutely cannot endanger those two with an unfair judgement.”</p></div>\n<div><p>For Katsuragi, too, this was a bitter decision. That was the part he emphasized.</p></div>\n<div><p>To protect someone, another person had to swallow their dissatisfaction.</p></div>\n<div><p>That structure remained constant throughout the entire exam. This situation was no exception.</p></div>\n<div><p>“Then…” Ibuki said, her voice lower now, though the anger had not disappeared. “If I actually contribute properly, you’ll give me more, right?”</p></div>\n<div><p>“Of course.”</p></div>\n<div><p>Katsuragi answered without the slightest hesitation.</p></div>\n<div><p>Ibuki clicked her tongue sharply, then turned and walked away.</p></div>\n<div><p>Her back showed her dissatisfaction and frustration plainly. But at the same time, she understood the reality in front of her. If she wanted to overturn Katsuragi’s judgment, words would not be enough.</p></div>\n<div><p>She would have to do it by producing results.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>The sun was already high overhead, and the air across the island was beginning to feel humid.</p></div>\n<div><p>The clock had only just passed nine in the morning, yet the quiet hours of dawn already felt strangely distant.</p></div>\n<div><p>A breeze slipped through the gaps between the trees, brushing faintly against our sweat-damp skin. Under normal circumstances, the sensation might have been pleasant. Now, it only seemed like one more thing dulling the mind.</p></div>\n<div><p>After so many mentally demanding assignments in a row, everyone’s concentration had clearly been worn thin. The brief silence before the next physical task felt stretched out far longer than it actually was.</p></div>\n<div><p>Nobody could fully relax while waiting for the next task, and everyone remained where they were carrying an awkward lingering tension.</p></div>\n<div><p>“From this point onward,” Urushibara announced, “you will be taking on several physically oriented tasks.”</p></div>\n<div><p>The atmosphere among certain students visibly lightened. After being forced through round after round of mental battles, the prospect of a physical challenge offered relief to those who had been bottling up frustration.</p></div>\n<div><p>For anyone who had fallen behind in academic contests, this was finally their chance to show what they were truly capable of.</p></div>\n<div><p>“This will also be a Team task,” Urushibara continued. “Each class will form pairs of two. Just like before, the pairs will be selected randomly by us. This task will test your core strength. The pair that can stand on one leg the longest without putting a foot down will win. The class with the first-place pair will receive ten tokens, second place will receive five, and third place will receive three. The class with the last-place pair will have two tokens withdrawn from their representative.”</p></div>\n<div><p>The rules were simple enough.</p></div>\n<div><p>If either member of a pair placed both feet on the ground, that pair lost.</p></div>\n<div><p>It was classified as a physical challenge, but there was room for strategy. As long as one foot remained raised, students were apparently allowed to hold hands, link shoulders, or use whatever method they preferred. The details were left to each pair.</p></div>\n<div><p>At a glance, it looked like a straightforward test of physical endurance.</p></div>\n<div><p>However, it demanded compatibility and coordination between partners.</p></div>\n<div><p>Individual ability alone wouldn’t be enough. Victory would depend on whether each pair could adjust to the other’s condition and distribute the strain properly.</p></div>\n<div><p>“Huh? Pairs? Why isn't it individual...?”</p></div>\n<div><p>For someone as confident in her physical ability as Ibuki, being forced to cooperate with another person was a clear disadvantage.</p></div>\n<div><p>Depending on her partner, she might end up carrying a heavy burden, or worse, being dragged down entirely.</p></div>\n<div><p>It was only natural that she wasn’t pleased.</p></div>\n<div><p>The more confident someone was in winning alone, the more they hated uncertain variables like other people.</p></div>\n<div><p>For Ibuki, this kind of cooperation was less an advantage than a restriction.</p></div>\n<div><p>Meanwhile, I was paired with Sanada, and Yoshida ended up with Morishita.</p></div>\n<div><p>Considering Sanada’s build, his higher center of gravity, and the likely limits of his endurance, trying to support each other evenly would be unwise. The most stable approach would be for me to serve as the axis while absorbing as much of the strain as possible.</p></div>\n<div><p>Ibuki, who had already been muttering complaints, made no attempt to hide her disappointment and anger once she learned that Morofuji would be her partner.</p></div>\n<div><p>Given Morofuji’s temperament, it was obvious that any emotional instability would directly affect her posture.</p></div>\n<div><p>For Ibuki, it was probably one of the pairings she least wanted to draw.</p></div>\n<div><p>“So, what would be the optimal approach here?” Sanada asked. “There’s a bit of a height difference between us, so linking shoulders seems like it would throw off our balance… Also, to tell you the truth, I’m not very confident.”</p></div>\n<div><p>If the rules allowed one person to drop out while the other continued, then the best strategy would simply be for me to stand alone.</p></div>\n<div><p>In fact, I’d prefer not to have unnecessary support or cooperation at all.</p></div>\n<div><p>But if Sanada went down, I’d automatically be eliminated with him.</p></div>\n<div><p>Since there was no point in only one of us remaining, everything came down to how we designed the load distribution.</p></div>\n<div><p>“We should avoid clinging too tightly to each other,” I said. “That kind of strategy only works when both people are at high risk of falling.”</p></div>\n<div><p>“So you’re confident in standing on one leg?”</p></div>\n<div><p>“More or less.”</p></div>\n<div><p>I shifted my weight lightly.</p></div>\n<div><p>“Think of me as an object fixed in place, like a tree. Do whatever you need to stay balanced on one leg for even a second longer.”</p></div>\n<div><p>“You mean I can hold on or lean against you however I like… Are you sure?”</p></div>\n<div><p>“Yeah. As a pair, that’s probably the optimal solution available to us.”</p></div>\n<div><p>By taking on Sanada’s burden myself, we could extend our total endurance.</p></div>\n<div><p>It was a setup to prevent a collapse in the long term, rather than seeking short-term stability.</p></div>\n<div><p>“Now then,” Urushibara called. “We will begin the task. Ready— start.”</p></div>\n<div><p>At the supervisor’s signal, all sixteen students lifted one foot into the air at once.</p></div>\n<div><p>While everyone moved at the same time, the real differences wouldn’t reveal themselves immediately. The question was how long each pair could hold out.</p></div>\n<div><p>At the start, there was no major gap between any of the pairs. Some supported each other. Some kept their distance. Some rested their weight against each other’s shoulders. Their chosen methods differed, but none of their postures looked fragile enough to fall apart right away.</p></div>\n<div><p>The real problem lay beyond that. After several dozen seconds, or once the first minute passed, the tiniest distortions in posture would begin to accumulate.</p></div>\n<div><p>Those distortions wouldn’t be large enough to be noticed at a glance, but they would definitely become the seeds leading to a collapse. If they failed to correct their posture in time, a chain reaction would send them tumbling to the ground.</p></div>\n<div><p>The strain concentrated in the supporting leg increased steadily with every passing second.</p></div>\n<div><p>The sensation of the sole against the ground began to blur. The ankle, which had been quietly making tiny adjustments, could no longer fully suppress the tremors.</p></div>\n<div><p>The balance they had initially maintained through conscious effort eventually gave way, plunging them into a desperate, agonizing struggle just to stay upright.</p></div>\n<div><p>The transition from merely maintaining a pose to desperately enduring it. How quickly a student could adapt to that shift would dictate how long they could survive.</p></div>\n<div><p>“S-sorry, Kikyō-chan,” Ike said, “You know… we kind of ended up pressed close together like this.”</p></div>\n<div><p>Whether it was for the tokens, or because the task had given him a legitimate excuse to press close to her, Ike tried his best to sound calm.</p></div>\n<div><p>His voice betrayed him anyway. An unmistakable pitch of excitement had already slipped into it.</p></div>\n<div><p>Under the pretext of maintaining their posture, Ike’s shoulder touched Kushida’s. It was obvious that he was far too conscious of the sensation carried through that contact, and of the distance, or lack of it, between them. His eyes weren’t focused on the task in front of him either. They kept drifting toward Kushida beside him.</p></div>\n<div><p>The moment his attention had strayed from where it ought to be, the risk had already taken root.</p></div>\n<div><p>The problem was that Ike himself didn’t realize it.</p></div>\n<div><p>“That bastard Ike…” Yoshida muttered beside me while struggling together with Morishita. “Honestly, I’m kind of jealous…”</p></div>\n<div><p>Perhaps he had imagined himself paired with Shiraishi, the girl he had his eye on. Or perhaps he simply couldn’t stand the fact that Ike had been paired with a cute girl at all.</p></div>\n<div><p>“You’re legally allowed to touch my body right now, you know,” Morishita said. “Deep down, you are actually thrilled about it, aren’t you?”</p></div>\n<div><p>“Who the hell would be thrilled, idiot?!”</p></div>\n<div><p>His denial came out too forcefully.</p></div>\n<div><p>Whether that brief outburst disrupted his core or threw off his focus, Yoshida’s balance faltered. Morishita, dragged along by the movement, ended up putting her foot down as a result.</p></div>\n<div><p>They were eliminated.</p></div>\n<div><p>But perhaps realizing that raising their voices might disturb Sanada, who was still fighting to hold on, both of them immediately sealed their mouths shut.</p></div>\n<div><p>A single reaction from the losers could break the concentration of those still remaining. Their silence came from understanding that much.</p></div>\n<div><p>Kushida, meanwhile, showed no sign of rejecting Ike’s behavior. Nor did she give him any special encouragement.</p></div>\n<div><p>She simply smiled naturally, treating the closeness as nothing more than part of the cooperation required for the task.</p></div>\n<div><p>Her sense of distance was exquisite. Not too close and not too far. She maintained a position that allowed the other person to mistake it for permission. He was not being rejected at least. That alone was enough for someone like Ike to interpret the situation positively, and perhaps that thought accelerated his awareness of her even further.</p></div>\n<div><p>He nearly lost his balance for a moment, but somehow managed to recover.</p></div>\n<div><p>“Uwooooh! I'm not done yet!”</p></div>\n<div><p>Shinohara, who was paired with Mii-chan, glared sharply at Ike as he got carried away. But perhaps because she had no room to carelessly call out to him, she remained silent.</p></div>\n<div><p>Even so, her gaze carried unmistakable emotion.</p></div>\n<div><p>She was desperately enduring, trying not to lose her balance, yet part of her attention remained fixed on Ike and Kushida. She should not have had any spare room to be distracted by something unnecessary, but the sight in her field of vision was impossible for her to ignore.</p></div>\n<div><p>As a result, subtle disturbances began creeping into Shinohara’s posture.</p></div>\n<div><p>She tried to correct it, but Mii-chan was pulled along as well, her own concentration chipped away by the movement. The situation grew increasingly difficult for both of them.</p></div>\n<div><p>As long as they were a pair, one person’s instability would inevitably spread to the other.</p></div>\n<div><p>Here too, the very burden they shared became their weakness.</p></div>\n<div><p>Unaware of the strain those two were suffering through, Ike kept his arm around Kushida’s shoulder and whispered near her ear.</p></div>\n<div><p>“Heh… Maybe we’re actually more compatible than I thought.”</p></div>\n<div><p>“Mm, maybe so,” Kushida replied with a soft smile. “You’re really good at this, Ike-kun, so that helps a lot. Let’s keep going as long as we can.”</p></div>\n<div><p>“O-of course. I’ll keep going… even one second longer…!”</p></div>\n<div><p>A single compliment was enough to warp his concentration even further.</p></div>\n<div><p>What he needed to maintain was his posture, but his attention had already been pulled somewhere else entirely.</p></div>\n<div><p>One minute passed then two.</p></div>\n<div><p>A one-legged stance that would never last long alone was being prolonged through cooperation between partners.</p></div>\n<div><p>From this point onward, it was no longer a contest of stamina, but of how long they could postpone collapse.</p></div>\n<div><p>Still, standing on one leg was never something the human body could maintain indefinitely. Even with mutual support, the time gained wasn’t dramatic. As the three-minute mark approached, one pair fell. Then another.</p></div>\n<div><p>Limits did not arrive equally for everyone. The moment of collapse in a person came suddenly and often chained down the other one as well.</p></div>\n<div><p>The next pair to fall was, as expected, Shinohara and Mii-chan.</p></div>\n<div><p>The instant one of them lost balance, that tremor propagated directly to the partner, and they collapsed in a chain reaction without any room to correct it. The choice to support each other was effective, but at the same time, it carried the risk of falling together.</p></div>\n<div><p>Conversely, pairs that kept too much distance soon began to drop out as well. Relying on individual stability alone made the opening moments easier, but as time passed, the burden of standing alone accumulated. Once one person reached their limit, if support did not arrive in time, the end came immediately.</p></div>\n<div><p>The remaining pairs all occupied the space between those extremes.</p></div>\n<div><p>They didn't completely support each other, nor were they completely independent. They only made contact and distributed the load when necessary. Whether or not they could make those adjustments became the difference here.</p></div>\n<div><p>“Get it together,” Ibuki snapped. “Don’t you dare put your foot down until I say it’s okay. We’re absolutely winning this!”</p></div>\n<div><p>In contrast to Ibuki’s fierce determination, Morofuji’s face was already twisted in pain.</p></div>\n<div><p>“This is… actually really tough…”</p></div>\n<div><p>Mental pressure and physical exhaustion were hitting her at the same time.</p></div>\n<div><p>Sanada, who was gripping onto me, was in a similar state. The strain on the sole and ankle of his supporting right foot had clearly become too much to bear, and little by little, more of his weight began shifting onto me.</p></div>\n<div><p>“Sorry,” Sanada said, his voice strained. “I think this is starting to get a little hard for me too…”</p></div>\n<div><p>“Just hold out as long as you can.”</p></div>\n<div><p>“But Ayanokōji-kun…” His small tremors had begun to increase. “Are you still all right?”</p></div>\n<div><p>I answered only with a slight glance.</p></div>\n<div><p>Of course, supporting an unstable Sanada meant I could not continue indefinitely either. No matter how steady I kept myself, absorbing another person’s shifting weight would eventually consume stamina.</p></div>\n<div><p>The pairs still holding on were Ibuki and Morofuji, and Amikura and Minamikata.</p></div>\n<div><p>Third place wouldn’t have been a bad result, but this was probably the moment to make a move. If there was a chance to raise our ranking by even one place, it was worth taking.</p></div>\n<div><p>The question was how to make that happen.</p></div>\n<div><p>“Morofuji.”</p></div>\n<div><p>I deliberately called out her name.</p></div>\n<div><p>There was no rule forbidding students from speaking while standing on one leg.</p></div>\n<div><p>The moment she heard her name, Morofuji’s shoulders jolted, and her gaze, until then fixed desperately on her footing, snapped toward me.</p></div>\n<div><p>All I needed was to divert her attention.</p></div>\n<div><p>That alone was enough to disrupt balance.</p></div>\n<div><p>“W-ww-what?”</p></div>\n<div><p>The fear Morofuji had carried toward me ever since our group first formed was still there.</p></div>\n<div><p>I said nothing more. Instead, I simply held her gaze and continued staring directly into her eyes.</p></div>\n<div><p>She seemed to have a strong sense of discomfort around me, that was enough.</p></div>\n<div><p>Fear, by itself, places a burden on both mind and body.</p></div>\n<div><p>And what she was supporting now wasn’t only physical weight.</p></div>\n<div><p>“H-hey, Morofuji, you’re wobbling!” Ibuki snapped.</p></div>\n<div><p>Ibuki herself still had some room to spare. But once her partner’s core began to collapse, the burden on her increased sharply. A disturbance on one side led directly to collapse.</p></div>\n<div><p>Meanwhile, Sanada no longer had the room to pay attention to an opponent’s movements.</p></div>\n<div><p>“Why is this so tough...ugh…”</p></div>\n<div><p>The surrounding noise no longer seemed to reach him. His awareness had turned inward, toward the battle with his own body.</p></div>\n<div><p>Core strength mattered, but the calves and ankles bore more strain than most people imagined. In an extreme state, outside information was discarded. Only the battle within remained.</p></div>\n<div><p>Sanada’s weight gradually leaned toward me.</p></div>\n<div><p>Each time it did, I used a small amount of strength to correct it. A slight adjustment of the shoulder. A minor shift through the hip. A quiet compensation through the leg acting as my axis.</p></div>\n<div><p>None of it was large on its own.</p></div>\n<div><p>But the accumulation of those small corrections rapidly whittled away at my physical strength. The limit of an individual.</p></div>\n<div><p>Before long, Sanada reached his limit and put his foot down.</p></div>\n<div><p>Fortunately, Morofuji had done the same just moments earlier.</p></div>\n<div><p>Thanks to that, we managed to slip into second place.</p></div>",
    "5": "<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/shiinamashiro.webp\"><span></span></div>\n<div><p>It was eleven in the morning.</p></div>\n<div><p>High above the decks of the passenger ship, where the sea breeze softened against glass walls and the sunlight spilled cleanly across the water, lay a completely secluded private pool.</p></div>\n<div><p>Appearing a little ahead of the appointed time, there was Amasawa Ichika of Class 2-A. </p></div>\n<div><p>Already changed into her swimsuit, she stepped out into the deserted oasis.</p></div>\n<div><p>“Being in a private rental really does feel special~” she said, her voice bright and teasing as she glanced around the empty poolside. “You're seriously footing the bill for this, right, Nanase-chan?”</p></div>\n<div><p>Arriving at the pool just a step behind her was Class 2-D’s Nanase Tsubasa.</p></div>\n<div><p>“Yes,” Nanase replied with her usual composure. “Since I was the one who selfishly called you out here today, please do not worry about the expense.”</p></div>\n<div><p>Nanase had booked the private pool for a sixty-minute block. With another student scheduled to take over right at noon, their time here was strictly limited.</p></div>\n<div><p>“This place was twenty thousand points last year, but now it costs twenty-five thousand, doesn't it? It's hilarious how the rental fee just casually went up. Looks like the wave of inflation has even reached us out here~”</p></div>\n<div><p>But the clock was ticking, even as they made small talk. Amasawa immediately claimed a lounge chair and snatched up a menu.</p></div>\n<div><p>“I'm totally ordering something expensive,” she hummed, tapping her index finger against the glossy pictures as she pondered her options.</p></div>\n<div><p>“Please, order whatever you like,” Nanase replied. “Though, from the standpoint of preventing food waste, I ask that you try not to leave any leftovers.”</p></div>\n<div><p>“So <em>that's </em>what you're worried about. Must mean you have plenty of Private Points saved up, nya?”</p></div>\n<div><p>“Not necessarily. I am simply a saver by nature,” Nanase answered with cool indifference.</p></div>\n<div><p>Hearing this, Amasawa narrowed her eyes in a sly smile.</p></div>\n<div><p>“In that case, you must have paid for all this because you decided a little private time with me was worth the splurge.”</p></div>\n<div><p>Keeping her gaze glued strictly to the menu, Amasawa casually guided the conversation forward.</p></div>\n<div><p>“That is correct.” Nanase said. “I intend to make our time together worthwhile.”</p></div>\n<div><p>Intentionally avoiding Nanase's expression, Amasawa gave a small nod and snapped the menu shut with a definitive <em>thwack.</em></p></div>\n<div><p>“I think I'll go with a melon cream soda! What about you, Nanase-chan?”</p></div>\n<div><p>She held the menu out to Nanase, who accepted it only to place it back onto the table unopened.</p></div>\n<div><p>“I am fine, thank you.”</p></div>\n<div><p>“Hmm, really? Well, suit yourself~”</p></div>\n<div><p>After casually placing the order for her melon cream soda, Amasawa turned her attention back to the girl standing beside her. Slowly, deliberately, she let her eyes roam up and down the length of Nanase's body, her appraising gaze trailing over her as if licking her from head to toe.</p></div>\n<div><p>Nanase’s face remained a completely blank slate. Betraying neither anger nor amusement, she kept her true feelings perfectly concealed behind an emotionless facade.</p></div>\n<div><p>Driven by an irresistible urge to peel that mask away, Amasawa lowered her gaze.</p></div>\n<div><p>“But seriously, Nanase-chan, haven’t you grown another cup size this past year?” Amasawa teased. “I think I’ve developed pretty well myself, but... it looks like you've got me beat~”</p></div>\n<div><p>“That is sexual harassment.”</p></div>\n<div><p>“Oh, come on. It’s your fault for having the kind of body that is just asking for it~”</p></div>\n<div><p>“Under normal circumstances, that would be an unforgivable statement,” Nanase replied coldly. “I do not believe I am at fault in the slightest.”</p></div>\n<div><p>An ordinary high school girl would have reacted with intense embarrassment or disgust. Yet, Nanase radiated absolutely nothing. It wasn’t that Amasawa thought she was completely devoid of emotion; rather, whenever Nanase flipped a certain internal switch, her mental defenses became impenetrably high.</p></div>\n<div><p>“That swimsuit is pretty bold, too. Quite the aggressive fashion statement.” Fully expecting a reprimand, Amasawa forcefully pressed the attack, desperate to find a crack in the Nanase's armor.</p></div>\n<div><p>“I merely rented a design that a classmate recommended. Is there a problem with that?”</p></div>\n<div><p>“Not a <em>problem, </em>exactly. I just figured the boys wouldn't know where to look.”</p></div>\n<div><p>“Are you not in the exact same situation, Amasawa-san?”</p></div>\n<div><p>It was a fair point. Amasawa was wearing a swimsuit a full grade flashier than any of the other girls they’d seen at the pool, proving her tastes were just as daring as Nanase's.</p></div>\n<div><p>“In my case, it's totally fine, because I'm showing off on purpose!” Amasawa laughed. “The boys stare at me with lust in their eyes, and the girls glare at me with raging jealousy. I love being the center of attention.”</p></div>\n<div><p>“...Is that so?”</p></div>\n<div><p>Perhaps unable to process that particular brand of exhibitionism, a slightly troubled frown flickered across Nanase's face. It was the first genuine display of emotion she had shown, but just as quickly as it appeared, her rigid, stoic mask slammed back into place.</p></div>\n<div><p>“Anyway, to change the subject for a sec…” Amasawa hummed. “I heard someone from Class 2-D was forced to say bye-bye during the Special Exam the other day. Is your class holding up okay, nya?”</p></div>\n<div><p>The question wasn't born out of genuine interest. Amasawa was simply tossing it out as a way to kill time until her drink arrived.</p></div>\n<div><p>For a fraction of a second, Nanase’s expression stiffened. Letting out a soft exhale, she averted her eyes and stared off into the distance.</p></div>\n<div><p>While the third-year students had landed on an uninhabited island to begin their survival exam, the second-years had been locked in a fierce competition of their own through a unique Special Exam. The results had been definitive: Class A secured first place, Class C took second, and Class B came in third. That left Nanase’s Class D sitting dead last.</p></div>\n<div><p>Up until this point, the dynamic among the second-years had been a slow, steady crawl, with Class A gradually pulling away from the rest of the pack. Now, however, that gap was widening into a chasm. But this latest exam had been more than just a simple defeat for Class D. During the course of the trial, an expulsion had been finalized. They had suffered a casualty.</p></div>\n<div><p>“The class itself is functioning without issue,” Nanase replied quietly. “However, since the responsibility for his expulsion ultimately lies with me, I am left with mixed feelings on the matter.”</p></div>\n<div><p>“Wait, it's <em>your </em>responsibility, Nanase-chan? Was that how the story went? I thought he broke a rule or something.”</p></div>\n<div><p>Amasawa hadn't paid much attention to the Special Exam, but she had overheard a few rumors regarding the circumstances of the expulsion.</p></div>\n<div><p>“In truth,” Nanase said. “another student was supposed to be expelled.”</p></div>\n<div><p>“That's a pretty provocative way of putting it. Are you saying <em>you </em>tried to get someone expelled, Nanase-chan?”</p></div>\n<div><p>“That is correct.”</p></div>\n<div><p>It was the kind of statement that would earn a harsh scolding even if said as a joke, yet Nanase affirmed it instantly, without a shred of hesitation.</p></div>\n<div><p>“However, my target realized my intentions early on and devised countermeasures,” Nanase explained. “Then, as a warning, they cornered a student in Class D who had absolutely nothing to do with the incident. Knowing full well the severe penalty he would face, the expelled student must have been driven into such a mental corner that he felt he had no other choice but to break the rules.”</p></div>\n<div><p>Having her curiosity slightly piqued, Amasawa sat up from her lounge chair and scrutinized Nanase's face.</p></div>\n<div><p>While she couldn't detect any hints of guilt or regret in Nanase's eyes, there was an undeniable frustration seeping through her rigid mask.</p></div>\n<div><p>“Doesn't sound like a very peaceful story.”</p></div>\n<div><p>“Does that interest you?”</p></div>\n<div><p>“Eh? Sorry, not really.” Sensing she was about to be dragged into something tedious, Amasawa offered a dismissive reply.</p></div>\n<div><p>But Nanase had clearly anticipated the evasion and pressed on without hesitation. “You are not entirely divorced from this incident, Amasawa-san. In fact, you already know the details, do you not?”</p></div>\n<div><p>“My heart belongs solely to Ayanokōji-senpai,” Amasawa answered, her tone dripping with mock devotion. “I couldn't care less about silly squabbles between classmates, y'know?”</p></div>\n<div><p>Unfazed by the flippant deflection, Nanase continued. “The student I was trying to expel was from Class 2-A.”</p></div>\n<div><p>“Ah, so <em>that's </em>where the ‘not divorced’ part comes in. Sorry to disappoint, but I seriously had no clue. Nor do I care about this even a tiny bit. Still... who were you targeting?”</p></div>\n<div><p>Amasawa tilted her head, genuinely curious as to who in her class could have possibly provoked Nanase into wanting them expelled.</p></div>\n<div><p>“Ishigami-kun,” Nanase replied.</p></div>\n<div><p>“Ishigami?” Amasawa repeated. “The cool, handsome guy? He doesn't exactly seem like the type to make moves out in the open.”</p></div>\n<div><p>Despite sharing a class with him for over a year, Amasawa had practically zero contact with the boy. In truth, she had absolutely no interest in anyone in her own grade. Because she never bothered interacting with her peers, she barely even knew their basic personalities. It was safe to say the girl standing right in front of her was her one and only object of interest in the entire second year.</p></div>\n<div><p>As these thoughts drifted casually through Amasawa's mind, she noticed Nanase fixing her with a razor-sharp glare.</p></div>\n<div><p>“He is far sharper than one might imagine,” Nanase warned.</p></div>\n<div><p>“Hmm. Well, I know he's essentially in a leader-like position, but Ishigami-kun, huh... So, what made you decide to pick a fight with him? Y'know, just to pry a little.”</p></div>\n<div><p>“There are... certain circumstances behind it.”</p></div>\n<div><p>The atmosphere around Nanase underwent a subtle shift. Instantly, Amasawa became absolutely certain that this topic, one she had brought up purely to kill time, was the actual reason she had been summoned here today.</p></div>\n<div><p>“I'm starting to get the feeling that this little story and my invitation to the pool are connected.”</p></div>\n<div><p>“Just to be absolutely certain,” Nanase said, her voice dropping a fraction, “you were not involved in this incident, were you, Amasawa-san?”</p></div>\n<div><p>“Do I really look like a suspect here?” Amasawa asked.</p></div>\n<div><p>“If you truly mean it when you say you only have eyes for Ayanokōji-senpai... then I concluded your involvement was a distinct possibility.”</p></div>\n<div><p>Normally, if a girl was strictly interested in Ayanokōji, it would stand to reason that someone like Ishigami wouldn't matter to her in the slightest. Yet, Nanase’s tone implied a completely different, paradoxical logic: <em>If </em>you were deeply obsessed with Ayanokōji, <em>then </em>you would naturally be deeply concerned with Ishigami.</p></div>\n<div><p>“Sorry, but I seriously couldn't care less, and I definitely had no part in it.” Flapping her left hand back and forth, Amasawa offered a genuine, outright denial.</p></div>\n<div><p>“I understand. Regardless, I had fully intended to broach this subject myself.” Dismissing the slight detour in their conversation, Nanase pressed on, firing off her carefully chosen words in rapid succession. “I will speak under the assumption that you truly know nothing. He... Ishigami Kyō is not entirely unconnected to the White Room.”</p></div>\n<div><p>With that single sentence, Nanase sliced right to the heart of the matter, abruptly dragging the core issue out into the open.</p></div>\n<div><p>“Ishigami-kun has ties to the White Room? If he’s my age, that would mean he’s a White Room student, but that’s impossible. And Ayanokōji-senpai is the absolute only one in the generation above us... Wait, could he be younger? Hmmm... I think I'd be even <em>less </em>interested if he were a junior, though~”</p></div>\n<div><p>“You are saying that while knowing full well it is not the case, are you not?”</p></div>\n<div><p>Noting the sharp, unmistakable flicker of anger in Nanase's glare, Amasawa brought her hands together in a playful gesture of apology.</p></div>\n<div><p>“My bad, my bad. So basically, you're saying he's connected, just not as a student. And since you actively moved to eliminate him, that must mean Ishigami-kun is working for the White Room's side. An assassin sent in to get Ayanokōji-senpai expelled, does that sound about right, nya?”</p></div>\n<div><p>Even as she voiced the theory, an obvious contradiction sprang to mind. If that were true, wasn't Ishigami leading an awfully leisurely, remarkably ordinary school life?</p></div>\n<div><p>And that wasn't all. The assassins specifically dispatched under Tsukishiro's orders to expel Ayanokōji were Amasawa and Yagami. If Ishigami was <em>also </em>tangled up with the White Room on top of that, things were certainly turning into quite a lively party. A faint smile touched Amasawa's lips at the thought.</p></div>\n<div><p>However, she was currently taking this entire story with a grain of salt. She wasn't about to swallow the claims at face value. After all, the true allegiances of the girl standing beside her, Nanase Tsubasa, were still steeped in a murky gray area, neither definitively white nor undeniably black.</p></div>\n<div><p>“The situation has changed drastically since you and Yagami-kun first made your moves shortly after enrolling,” Nanase explained. “The question of whether or not to expel Ayanokōji-senpai is nothing more than a single current in a much larger flow—”</p></div>\n<div><p>Mid-sentence, Amasawa lightly raised a palm, gesturing for her to stop. Right on cue, the door to the private pool opened, and a female staff member walked in carrying the melon cream soda Amasawa had ordered.</p></div>\n<div><p>Accepting the drink with a bright, charming smile, Amasawa waited politely for the staff member to leave before taking a generous gulp through her straw.</p></div>\n<div><p>“Wow, so sweet! But <em>so </em>tasty~” Pressing a hand to her cheek, she let out a small, exaggerated shiver, playing the part of an innocently cute girl to perfection.</p></div>\n<div><p>“May I continue?”</p></div>\n<div><p>“Go right ahead.”</p></div>\n<div><p>“Amasawa-san, you were ordered by the White Room side, specifically by Tsukishiro-san, to have Ayanokōji-senpai expelled. That is correct, yes?”</p></div>\n<div><p>Amasawa nodded encouragingly, urging her to go on.</p></div>\n<div><p>“From the very beginning, Tsukishiro-san believed the odds of you actually succeeding in expelling him were fifty-fifty.”</p></div>\n<div><p>“Wait, so he knew right from the start that our abilities were no match for Senpai's?”</p></div>\n<div><p>“It might be more accurate to say that he simply did not care which outcome came to pass.”</p></div>\n<div><p>The spoon in Amasawa's hand, which had just scooped up a bite of vanilla ice cream, froze in midair.</p></div>\n<div><p>When she had been sent to Advanced Nurturing High School, she was ordered to follow Tsukishiro's instructions. Because of that, she had indirectly assumed he was an ally. Was that fundamental premise completely wrong? She turned the thought over in the back of her mind.</p></div>\n<div><p>“That definitely brings up a lot of things I want to dig into,” Amasawa said slowly, “but can I ask a fundamental question first?\"</p></div>\n<div><p>“What is it?”</p></div>\n<div><p>“Nanase-chan, at the end of the day... Are you Ayanokōji-senpai's ally? Or are you his enemy?”</p></div>\n<div><p>Ayanokōji himself had previously asked Amasawa to look into Nanase. Right now, the girl was running around acting like his loyal knight, but there wasn't a single shred of concrete proof to back up her allegiance.</p></div>\n<div><p>“Yes, you make a fair point. It would probably be best to make my stance explicitly clear, including the matter regarding Tsukishiro-san.”</p></div>\n<div><p>Nanase pulled a smartphone from her bag, tapped the screen a few times, and held it out.</p></div>\n<div><p>As Amasawa reached out to take it, her gaze drifted to <em>another </em>phone resting innocently on the table.</p></div>\n<div><p>“For someone playing the honors student, you're actually quite a bad girl, Nanase-chan. Carrying two phones around, and one that looks like a carbon copy of the school-issued models, no less. If you get caught with that, a simple suspension might not cover it.”</p></div>\n<div><p>Teasing her with a playful lilt, Amasawa finally lowered her eyes to the screen she had been handed.</p></div>\n<div><p>“To answer one of your earlier questions, Ishigami-kun is not Ayanokōji-senpai's enemy,” Nanase declared. “Putting his own personal feelings aside, his faction is unambiguously the White Room... or, to be entirely precise, Ayanokōji Atsuomi's faction.”</p></div>\n<div><p>Ayanokōji Atsuomi was Ayanokōji Kiyotaka's biological father and the founder of the White Room. To Amasawa and the other students raised within its walls, he was their absolute ruler.</p></div>\n<div><p>The phone contained a comprehensive dossier on Ishigami Kyō, detailing everything from his upbringing to the circumstances that led to his enrollment.</p></div>\n<div><p>During his childhood, he had met Atsuomi and was profoundly inspired by him. Upon entering middle school, Ishigami leveraged his parents' connections to contact Atsuomi independently. He was subsequently highly praised by the man as a brilliant individual with a natural intellect, and ultimately enrolled at Advanced Nurturing High School to act as an observer over Kiyotaka.</p></div>\n<div><p>Scrolling through the profile, Amasawa’s eyes landed on a specific passage. It noted that while Ishigami deeply craved Atsuomi's acknowledgment, he harbored a bitter resentment over the fact that Atsuomi rated his own son much higher.</p></div>\n<div><p>“I see. It's precisely because he reveres ‘Sensei’ so much that he's jealous of Senpai, the masterpiece.”</p></div>\n<div><p>For a moment, another figure overlapped faintly with Ishigami in her mind.</p></div>\n<div><p>Yagami.</p></div>\n<div><p>Imagining the undeniable parallels between both of them, Amasawa felt a slight, involuntary stir of emotion in her chest.</p></div>\n<div><p>“That may well be the case,” Nanase agreed. “However, unlike you White Room students, he was not ordered to expel Ayanokōji-senpai. His mandate is strictly limited to surveillance.”</p></div>\n<div><p>No matter his personal feelings, Ishigami would never defy Sensei's wishes. If anything, his position was simply to watch over and preserve the masterpiece.</p></div>\n<div><p>“I was pretty confident in my ability to keep tabs on Ayanokōji-senpai,” Amasawa murmured, “but I never once noticed him in the picture.”</p></div>\n<div><p>For over a year, her own monitoring of Ayanokōji had bordered on stalking. Yet, in all that time, she had never caught Ishigami attempting to make contact. Since she couldn't stick to Ayanokōji twenty-four seven, Ishigami might have slipped through the cracks here and there, but if he were making frequent contact, she undoubtedly would have noticed.</p></div>\n<div><p>“Unless there’s some unexpected development,” Nanase said, “he may believe there is no need for him to interfere.”</p></div>\n<div><p>“So he does recognize Senpai's abilities.\" Amasawa let the thought settle before shifting to the next point. “By the way, does Ishigami-kun know about us too?”</p></div>\n<div><p>“I doubt he knows about me, but I am certain he has received detailed information regarding you and Yagami-kun directly from the White Room.”</p></div>\n<div><p>“Makes sense. If that's the case, he must be pretty capable.”</p></div>\n<div><p>Amasawa had never once been approached by him, nor had she ever sensed an unnatural gaze or hostile vibe aimed in her direction. That was exactly why she had paid absolutely zero attention to Ishigami throughout her entire school life.</p></div>\n<div><p>“I cannot speak to his basic academic metrics, but in terms of deductive reasoning, I would assess him as being at least a step above you and Yagami-kun.”</p></div>\n<div><p>“Eeeh~?” Amasawa’s voice rose with theatrical disbelief. “Aren't you just underestimating me a little? Or maybe you're overestimating him?”</p></div>\n<div><p>“It would certainly be helpful for us if that were true,” Nanase said dryly. “Regardless, his current policy seems to be to maintain his surveillance until graduation. But should the tide change, he will likely take immediate action.”</p></div>\n<div><p>“Meaning Ishigami-kun will make a move to force Ayanokōji-senpai out of the school?”</p></div>\n<div><p>Even when asked this, Nanase did not affirm. Instead, she briefly averted her gaze, and looked up at the clear blue sky.</p></div>\n<div><p>“At this point, the word expulsion alone is no longer enough to describe it,” she said. “What matters to Atsuomi is ensuring that Ayanokōji-senpai is brought back into his own hands. If he decides expulsion is necessary for that purpose, Ishigami-kun will follow his orders. If he decides it is best to leave him alone until graduation, then Ishigami-kun will do nothing until the very end. At least, that’s my understanding of the current situation.”</p></div>\n<div><p>Amasawa stared at her. “For someone who isn't a White Room student, you're vastly more knowledgeable about this whole mess than I am, and I'm the actual assassin sent to get Senpai expelled. You got that phone from Tsukishiro, too, didn't you? Just who are you, Nanase-chan?”</p></div>\n<div><p>That was the very core of the mystery, the absolute root of Nanase’s guiding principles, and the very thing Ayanokōji himself likely wanted to uncover.</p></div>\n<div><p>And now, Amasawa was stepping right into it.</p></div>\n<div><p>“Did you truly think I would just hand over that information so easily?”</p></div>\n<div><p>“Ah, figured as much. I guess I can't blame you, seeing as I'm a White Room student.”</p></div>\n<div><p>Thinking she might have probed a bit too deep, Amasawa was surprised when a faint smile graced Nanase's lips.</p></div>\n<div><p>“I am joking. You respect, no, you revere Ayanokōji-senpai. Because of that absolute devotion, I am completely convinced you would obey his every word. But precisely because the Ayanokōji-senpai you are loyal to belongs to the White Room, there are certain things I cannot share.”</p></div>\n<div><p>Amasawa understood what Nanase was implying.</p></div>\n<div><p>If Nanase’s true intentions were brought to light, Ishigami would undoubtedly make his move. That was Nanase's rationale. That was why she had struck first, attempting to get him expelled before he could act.</p></div>\n<div><p>Inside Amasawa's mind, the puzzle pieces rapidly began falling into place.</p></div>\n<div><p>“However, I <em>can </em>tell you my ultimate objective,” Nanase offered.</p></div>\n<div><p>“Then give it to me straight. What exactly is your goal, Nanase-chan? Y'know, within the boundaries of what you're actually allowed to say.”</p></div>\n<div><p>“Initially, my goal was to defeat Ayanokōji-senpai and have him expelled. That was the sole reason I enrolled in this school.”</p></div>\n<div><p>Seeing Nanase deliver this statement with such a deadpan, serious expression, Amasawa couldn't help but burst into laughter.</p></div>\n<div><p>“A for effort, but no matter what you do, Nanase-chan, you wouldn’t be able to beat Ayanokōji-senpai.”</p></div>\n<div><p>Even if Nanase had been hiding her true strength this entire time, that fundamental truth would never waver.</p></div>\n<div><p>“I am well aware,” Nanase replied calmly. “But do you not think that is only true if I were to fight him head-on?”</p></div>\n<div><p>Without speaking boastfully, Nanase continued, implying that she had a chance of winning.</p></div>\n<div><p>“No, no, frontal assault or sneak attack, it doesn't matter. It's totally impossible.”</p></div>\n<div><p>Ayanokōji simply wasn't the kind of opponent who would fall for conventional tactics, surprise attacks, or underhanded tricks. Amasawa felt a slight wave of disappointment, having assumed Nanase was at least smart enough to understand that much.</p></div>\n<div><p>However, the next words out of Nanase's mouth were something Amasawa could never have anticipated.</p></div>\n<div><p>“The enemy I must defeat is no longer Ayanokōji-senpai. It is the man lurking in his shadow: Ayanokōji Atsuomi, the founder of the White Room. And to accomplish this, I must steal Ayanokōji-senpai away, take control of him, and seize the initiative. After all, he is the most vital piece in his father's plans.”</p></div>\n<div><p>“Hold on, there's no way I can see that actually working.”</p></div>\n<div><p>“That depends entirely on the method. Ayanokōji-senpai is formidable. As long as I interact with him as an enemy, bringing him under my control is an absolute impossibility. However, if my goal is to induce a change of heart in him, the story changes.”</p></div>\n<div><p>“...A change of heart?”</p></div>\n<div><p>“Let me ask you, Amasawa-san. What do you think Ayanokōji-senpai will do once he graduates?”</p></div>\n<div><p>“What else? Wouldn't he just go back to the White Room? Whether Senpai becomes a new instructor or follows Sensei to accomplish something massive, I wouldn't know.”</p></div>\n<div><p>“I was told his future would be one of those two options. In other words, if that comes to pass, Atsuomi wins. I intend to prevent that at all costs. Tsukishiro-san said it himself: while Ayanokōji-senpai may have fled the White Room's environment out of intellectual curiosity, he certainly does not hate the place. Nor does he have any real intention of defying them. No, he is fully prepared to willingly return to his origins.”</p></div>\n<div><p>“Well, I don't know how it looks from your perspective, Nanase-chan, but I don't exactly have a bad image of the White Room either,” Amasawa shrugged. “It's where I've spent every single day since I was born. Simply put, it's my home.”</p></div>\n<div><p>Having recently lost that very place to return to, one could say Amasawa’s heart carried a quiet, hidden wound.</p></div>\n<div><p>“That is completely unacceptable,” Nanase replied. “That man is simply biding his time, waiting for the perfect moment to use Ayanokōji-senpai. To send him back to a man like that... I absolutely refuse to let it happen.”</p></div>\n<div><p>Realizing her hands had unconsciously balled into white-knuckled fists, Nanase forced herself to loosen her grip.</p></div>\n<div><p>“So, you're going to try your absolute best to stop Ayanokōji-senpai from returning to the White Room, huh? Nanase-chan.”</p></div>\n<div><p>“Yes.”</p></div>\n<div><p>“Then what? Are you just gonna bow your head and beg, ‘Please Ayanokōji-senpai, go and live a normal, happy life~’? Come on now~”</p></div>\n<div><p>“I know it will not be that simple. Ayanokōji-senpai is not going to just nod his head and agree.”</p></div>\n<div><p>“I don't know if he has any actual interest in a ‘normal life,’ but I definitely think returning to the White Room holds a lot more appeal to him.”</p></div>\n<div><p>“Indeed. And on the off-chance that he did agree, there is no way Ayanokōji Atsuomi would tolerate such a rebellion.”</p></div>\n<div><p>“Then how exactly do you plan to change Senpai's heart?”</p></div>\n<div><p>“To be completely honest, I have not fully pieced together the answer to that yet. But I believe I have found a hint. Before I can put it into action, however, the stage must be perfectly set. Persuading him and tearing him away from the White Room will require careful groundwork. The moment I begin making overt moves toward that answer, Ishigami-kun will undoubtedly notice, and he will come to stop me</p></div>\n<div><p>“So you tried to strike first and get him expelled to clear the board....I see.” Amasawa murmured.</p></div>\n<div><p>But now that Nanase’s preemptive strike had failed, a dangerous new reality loomed over them. If Ishigami was truly as capable as Nanase claimed, there was a very real chance that he had already sensed the anomaly. In all likelihood, he was investigating who had targeted him, quietly preparing to eliminate the threat.</p></div>\n<div><p>“Making that move to get Ishigami-kun expelled this time might have been a bit of a blunder on your part, Nanase-chan.”</p></div>\n<div><p>“I will not deny it.”</p></div>\n<div><p>Yet, Nanase didn't seem panicked in the slightest. Watching her, Amasawa deduced that the preemptive strike had likely doubled as a probing attack to test her opponent's strength and gather intelligence. And if Ishigami was truly as sharp as Nanase claimed, then targeting an unrelated student in retaliation was an absolutely brilliant, perfectly calculated move, a flawless warning shot that established dominance without escalating the situation completely out of control.</p></div>\n<div><p>“Okay, I think I've grasped the general picture,” Amasawa said. “Though I have no idea how much of this little story is actually true.”</p></div>\n<div><p>“Of course. I am not asking you to blindly believe every word I say.”</p></div>\n<div><p>Even while taking it all with a grain of salt, Amasawa couldn't detect the faintest scent of falsehood from Nanase. At the very least, Nanase's claims were persuasive enough that Amasawa was willing to treat them as the working truth.</p></div>\n<div><p>“So, what's my role in all this? It's not like you just want me to play messenger and relay everything to Ayanokōji-senpai, right?”</p></div>\n<div><p>If that were all Nanase wanted, there would have been no reason to involve Amasawa like this.</p></div>\n<div><p>“I want you to become my ally.”</p></div>\n<div><p>“Ally? You mean you want me to help induce this ‘change of heart’ in Ayanokōji-senpai?”</p></div>\n<div><p>“That is certainly part of it. But first and foremost, I would appreciate it if you could act as my backup in the event that I am expelled.”</p></div>\n<div><p>“Heeh, so you've even factored in the possibility of being taken out by Ishigami-kun.”</p></div>\n<div><p>“I will do everything in my power to ensure that does not happen, but there is no telling how things will unfold.”</p></div>\n<div><p>When combining Ishigami's raw capabilities with the classified intelligence provided by the White Room, the threat level skyrocketed. Amasawa deduced that Nanase simply couldn't guarantee her own safety against such overwhelming odds.</p></div>\n<div><p>“Sorry, but at the end of the day, I'm still a White Room student through and through,” Amasawa sighed, shaking her head. “I've lived my entire life taking pride in that, and I still have lingering attachments to it. I don't dislike you, Nanase-chan, but personally? I want to support whatever future Senpai desires. And beyond that, assisting Sensei is my true, original purpose.”</p></div>\n<div><p>What Nanase was trying to do was no minor adjustment. It was an attempt to take Ayanokōji’s future and bend it away from its expected course, forcing it from one path onto another.</p></div>\n<div><p>Whether that intervention was right or wrong, Amasawa could not yet judge. That was precisely why she had no choice but to refuse.</p></div>\n<div><p>“What is your dream, Amasawa-san?” Nanase asked quietly. “To return to the White Room alongside Ayanokōji-senpai... is that it?”</p></div>\n<div><p>“So what if it is?” Amasawa replied. “Got a problem with that?”</p></div>\n<div><p>Of course, she already knew deep down that such a dream would never come true.</p></div>\n<div><p>The White Room had branded her a failure, and there was no returning from that exile.</p></div>\n<div><p>Even so, finding solace in the fact that she was still free to dream, Amasawa offered Nanase a bright, unapologetic smile.</p></div>\n<div><p>“I understand how you feel,” Nanase said. “However, miracles do not happen. That wish of yours is one hundred percent unattainable. No matter what grand achievements you might accomplish, there is no bright future waiting for you.”</p></div>\n<div><p>“How can you be so sure about that?” Amasawa countered lightly. “For all you know, I might just be on the verge of awakening my true potential, y'know?”</p></div>\n<div><p>“This is a matter that goes far beyond your individual capabilities. Do you have any idea what your father is currently planning?”</p></div>\n<div><p>“My father? Sorry, but I have absolutely zero interest in that kind of thing. Doesn't that have exactly nothing to do with me?”</p></div>\n<div><p>“Your opinion is irrelevant. The simple fact of the matter is that the legal 'ownership' of you, Amasawa-san, lies with your father.\"</p></div>\n<div><p>Nanase smoothly took back the smartphone she had handed over and began tapping at the screen.</p></div>\n<div><p>“Even if some so-called ‘parent’ I've never even met tries to butt in—”</p></div>\n<div><p>“I am well aware that you are an existence your father cannot control,” Nanase interrupted. “And because he knows this just as well as you do, he has been in close contact with the White Room to advance his preparations.”</p></div>\n<div><p>As Nanase laid this out with quiet, clinical detachment, the playful smile began to slip from Amasawa's face.</p></div>\n<div><p>“What is it, re-education? Discipline? Whatever grim future he's planning, bring it on.”</p></div>\n<div><p>“If you were truly prepared for the reality of it, that would be fine,” Nanase warned. “However, massive fraud has recently been uncovered in his company. Short on funds and backed into a corner, he is desperate. It seems there are certain syndicates overseas willing to pay exorbitant prices for beautiful young women, and he is currently scrambling to secure a buyer for you.”</p></div>\n<div><p>Nanase handed the phone back. On the screen Amasawa was now scrolling through was the photo and profile of a man presumed to be her biological father.</p></div>\n<div><p>“So I've outlived my usefulness, and now I'm just going to be sold off to the highest bidder. Hilarious.”</p></div>\n<div><p>Regardless of whether this was the truth or an elaborate lie, Amasawa cheerfully clapped her hands together and laughed out loud.</p></div>\n<div><p>But her eyes were completely dead. It was as if the harsh reality had just been violently shoved in her face, the agonizing truth that she didn't even possess the fundamental right to dream of a future.</p></div>\n<div><p>“If you choose to cooperate with me, I may be able to save you from that fate.”</p></div>\n<div><p>As Amasawa continued swiping across the screen, the display switched to an English webpage. It detailed exactly which overseas brokers her father was currently in contact with. It also outlined the horrific reality of what awaited her at her destination, a living hell so depraved one would hesitate to even put it into words.</p></div>\n<div><p>“Oh my, look at that crazy price tag attached to me,” Amasawa giggled. “I could buy anything in the world with this kind of money.”</p></div>\n<div><p>“From the perspective of an ordinary person, yes,” Nanase replied coldly. “However, given President Amasawa's massive debts, that amount is merely a drop in the bucket.”</p></div>\n<div><p>Amasawa thought about it over and over again. Her entire life was something she couldn't even verify as truth or lie. However, one thing was absolutely certain: the future she had just been shown held zero salvation.</p></div>\n<div><p>“Upon successfully inducing Ayanokōji-senpai's change of heart, I will extend ample protection to you after graduation, just as I plan to do for him. If that happens, you will be able to start a life that belongs entirely to you.”</p></div>\n<div><p>Meaning she would finally be allowed to stand on the starting line as an individual, autonomous human being.</p></div>\n<div><p>“...Could you really pull something like that off?”</p></div>\n<div><p>“I can. It is true that Ayanokōji Atsuomi is a man of considerable power with deep connections to the underworld. However, the faction backing me is large enough to easily swallow them whole. Given the circumstances, even you can imagine that much, can you not?”</p></div>\n<div><p>“Well…” Amasawa said slowly, “assuming you were actually serious about protecting me, maybe so.”</p></div>\n<div><p>But Amasawa wasn't naive enough to blindly swallow such sweet promises. If she held the same kind of absolute value as Ayanokōji Kiyotaka, then perhaps Nanase's faction genuinely would mobilize to protect her. But there was no guarantee they would afford her that same luxury. After all, she possessed no such value.</p></div>\n<div><p>“Could you give me a little time to think about it?”</p></div>\n<div><p>“Of course,” Nanase nodded smoothly. “I will be waiting for a favorable reply.”</p></div>\n<div><p>Flashing a defiant smirk, Amasawa scooped up a bite of the ice cream, which had now begun to melt.</p></div>",
    "6": "<div><p>Nearly two grueling hours of alternating between academic hurdles and physical exertion had finally come to an end. The supervisor announced a thirty-minute break, bringing the trials for the four teams of Group 3 to a temporary pause.</p></div>\n<div><p>Some students collapsed right where they stood, while others made a beeline for their backpacks, desperately digging out bottles of mineral water. It was perfectly understandable; the ordeal had felt like taking a comprehensive exam while baking under the blazing sun.</p></div>\n<div><p>“That really took a toll on me... I don't think I'll be able to manage even a single step for a while.”</p></div>\n<div><p>Slumped on the ground, Sanada removed his glasses and let out a heavy sigh, voicing his sheer exhaustion. His dirt-streaked jersey was a clear testament to his efforts; anyone looking could see he had given it his all. He was usually the type who kept his composure intact. His cool manner rarely cracked, and he did not often allow fatigue or emotion to show plainly on his face. But under these conditions, even he could not conceal the toll.</p></div>\n<div><p>“You're seriously insane, you know that? Sweeping every single individual match across both the academic and physical tasks…”</p></div>\n<div><p>Yoshida wandered over as he spoke, his expression caught somewhere between exasperated disbelief and genuine admiration. Although his tone was casual, a distinct gleam of shock lingered in his eyes. Sanada, twisting the cap off his plastic bottle, too, offered several firm nods of agreement.</p></div>\n<div><p>A single victory could be brushed off as a fluke or a favorable matchup. But consistently crushing such a diverse range of tasks painted a very different picture. Even to classmates who hadn't known me for very long, it was undeniably clear that this stemmed from true ability.</p></div>\n<div><p>Wiping the sweat from his brow, Sanada looked at me with an expression of quiet acceptance.</p></div>\n<div><p>“To be honest, I knew you were capable to some extent, but... this far exceeded my expectations.”</p></div>\n<div><p>He took a slow sip of water before meeting my gaze once more. Unlike Yoshida's, his words held no trace of exaggeration.</p></div>\n<div><p>“No, seriously,” Yoshida added. “While we were desperately trying to just survive the tasks, this guy was completely unfazed the whole time. Honestly, I'm just glad he didn't go all out against us back when he was still in Horikita's class.”</p></div>\n<div><p>When people genuinely acknowledge someone who produces results, and at the same time feel that they belong to that same circle, they become far more honest than one might expect. The tense atmosphere softened slightly, and within this brief period of rest, the outline of Class C was steadily growing firmer, taking shape once more.</p></div>\n<div><p>“Still,” Sanada said after a moment, glancing around, “I was just thinking it was unusually quiet around here. It turns out Morishita-san isn't with us.”</p></div>\n<div><p>Catching sight of Morishita resting her back against a distant tree trunk, Yoshida followed up on Sanada's observation.</p></div>\n<div><p>“Well, she's terrible at anything physical,” he said. “She probably doesn't even have the energy left to open that loud mouth of hers.”</p></div>\n<div><p>After the two of them had recovered a little, I began handing over the tokens in order. With each transfer, a matching electronic chime rang out from my smartwatch and echoed from Yoshida's and Sanada's as they received them.</p></div>\n<div><p>I set off toward Morishita to hand her the tokens as well, but no sooner had I started walking than I heard another set of footsteps hurrying toward me.</p></div>\n<div><p>“U-Um, Ayanokōji-kun…” The voice came from close by, soft enough that it was almost swallowed by the noise of the break. “Do you have a minute?”</p></div>\n<div><p>Mii-chan stood there looking visibly unsettled. Her eyes did not stay in one place for long, and even before she said another word, it was clear that she had not come to speak casually.</p></div>\n<div><p>“Um... over here.”</p></div>\n<div><p>She gestured for me to follow, slipping away from the prying eyes of the other students and moving to a secluded spot where our voices wouldn't carry.</p></div>\n<div><p>“There's something I want to consult you about,” she began, lowering her voice even further. “I know it's not really my place since we aren't in the same class anymore, but this is something I feel like I can only tell you, Ayanokōji-kun…”</p></div>\n<div><p>Her restless gaze darted around, and it was plainly obvious who she was looking out for: her own classmates from Class A. Judging by the fact that Ike and the others were currently nowhere to be seen, she had clearly waited for the perfect window to make her move. I stayed silent, gently prompting her to continue.</p></div>\n<div><p>“It's... about Kushida-san. Since today's tasks started, right up until this break... Shinohara-san hasn't given her a single token. And so…”</p></div>\n<div><p>“I understand why you wanted to keep this quiet, but that's highly sensitive internal information,” I interrupted. “Are you sure you want to be telling me this?”</p></div>\n<div><p>“Even though our classes are competing against each other, Ayanokōji-kun,” she replied, hesitating over each word. “we're still allies in the same group right now. Plus, it seemed like you genuinely value Kushida-san's abilities, so…”</p></div>\n<div><p>Normally, information about who had handed over how many tokens, and to whom, was something that should never be revealed carelessly. But the fact that she was bringing this to me meant that <em>it </em>had finally begun.</p></div>\n<div><p>“Assuming what you're saying is true, you and Ike have still been receiving your shares without any issues right?”</p></div>\n<div><p>She responded to my question with two small nods. “Yes, we've both... received ours perfectly fine.”</p></div>\n<div><p>“If Shinohara is keeping hold of all of Kushida’s tokens and refusing to hand over only her share, then that is certainly a problem.”</p></div>\n<div><p>Even without witnessing the scene firsthand, it was easy to picture the suffocating atmosphere it must have created.</p></div>\n<div><p>“Shinohara-san was complaining last night,” Mii-chan continued. “She said Ike-kun was constantly staring at Kushida-san. Even during the one-legged balancing task this morning, them being paired up was purely a coincidence, but her mood has been terrible ever since.”</p></div>\n<div><p>“Knowing Ike, he's always had a soft spot for cute girls. Throw Kushida into the mix, and it's bound to be even worse.”</p></div>\n<div><p>“B-But Shinohara-san is his girlfriend…” Mii-chan’s voice trembled with an earnest kind of discomfort. “I honestly think Ike-kun is completely at fault here…”</p></div>\n<div><p>She wasn't wrong. In reality, however, one cannot spend an entire eternity with eyes only for their precious girlfriend. It is often said that as a relationship went on, intimacy deepened while the initial spark inevitably faded. Considering Ike had harbored feelings for Kushida to begin with, a wandering eye was, to some extent, unavoidable.</p></div>\n<div><p>“I thought that once Ike learned more about Kushida’s true nature, he would put some distance between himself and her,” I said. “But I suppose that hasn’t happened.”</p></div>\n<div><p>“I suppose not. Lately, Kushida-san has often been isolated in the classroom, and Ike-kun has been going out of his way to talk to her. That's probably been bothering Shinohara-san for a while too.”</p></div>\n<div><p>“But even taking all of that into account, the root cause of everything goes back to the Unanimous Special Exam... doesn't it?”</p></div>\n<div><p>Mii-chan closed her eyes tightly, and then nodded deeply.</p></div>\n<div><p>“In truth, the words that Kushida hurled at Shinohara back then were so intense, they were impossible to forget.”</p></div>\n<div><p>I remembered it clearly enough.</p></div>\n<div><p>During the Unanimous Special Exam, Kushida had mocked Shinohara in front of the entire class, casually declaring her to be ‘on the ugly side.’ If Shinohara's boyfriend had then been constantly doting on and acting chummy with the very person who had humiliated her, it was all too easy to imagine the resentment boiling inside her.</p></div>\n<div><p>Even so, maliciously withholding tokens exclusively from Kushida was a secret she couldn't possibly keep forever.</p></div>\n<div><p>Up until now, Shinohara had likely bitten her tongue for the sake of the class. She had kept Kushida's toxic nature under wraps, taking a step back to avoid causing any public friction. But now that she had been handed the power of a representative, it seemed her restraints were finally beginning to snap.</p></div>\n<div><p>“Still, this is surprising,” I noted. “I thought you'd come to hate Kushida too, Mii-chan.”</p></div>\n<div><p>While it might not have been quite as brutal as insulting Shinohara's physical appearance, Mii-chan had also been a victim; her innocent crush on Hirata had been ruthlessly exposed during the Unanimous Special Exam.</p></div>\n<div><p>Putting aside the fact that most of our classmates had already noticed her feelings long before the reveal, the humiliation had still driven her into such a deep depression that she temporarily stopped coming to school.</p></div>\n<div><p>“It's true that Kushida-san... really hurt me,” she admitted softly. “But even so, I feel like if I let myself become a hateful person just like her, it would be wrong.”</p></div>\n<div><p>She was bringing this delicate issue to me, someone who had essentially betrayed her class by transferring out, despite knowing full well the complex circumstances at play. It was safe to assume her words were grounded in genuine moral conviction, not just surface-level pleasantries.</p></div>\n<div><p>“From what you've told me, there's no doubt she's abusing her position as representative to harass Kushida,” I said. “But your biggest concern is the worst-case scenario: that Kushida might actually end up in last place. Am I right?”</p></div>\n<div><p>“Yes…”</p></div>\n<div><p>If Shinohara monopolized all the tokens and refused to give Kushida a single one, Kushida would be fighting a steeply uphill battle, no matter how many tokens she managed to earn on her own.</p></div>\n<div><p>This Special Exam was divided into three categories— individual, team, and group— but having the entire class united was an overwhelmingly massive advantage.</p></div>\n<div><p>If a class treated the trivial Private Points reward as an afterthought and simply distributed their tokens equally, that solidarity alone would act as a tremendous shield against falling into last place. To counter such a strategy, the other classes would be forced to unite as well, ultimately boiling the exam down to a sheer numbers game where the expulsion would fall on the class with the lowest overall total.</p></div>\n<div><p>However, the logistical hurdles required to reliably execute that kind of strategy were staggering. It demanded trusting unseen classmates, coordinating meetups in the forest, transferring tokens, and meticulously adjusting the totals. The entire plan rested on the fragile premise that no one would betray the group.</p></div>\n<div><p>“There's no doubt that Shinohara's pent-up frustrations are manifesting in her actions,” I continued. “However, it's highly unlikely she'll withhold Kushida's tokens all the way to the bitter end. If word of this reaches Horikita, Shinohara's own standing within the class would be in serious jeopardy.”</p></div>\n<div><p>“So... I don't need to worry?”</p></div>\n<div><p>“For now, it should be fine. Do you honestly think she would go so far as to force Kushida into expulsion over a personal grudge? It's safe to assume this is just her way of exacting petty revenge.”</p></div>\n<div><p>Driving a classmate to expulsion solely out of personal dislike wasn't a simple line to cross.</p></div>\n<div><p>When I added that, Mii-chan seemed to relax slightly. A small breath escaped her, as though she had finally been allowed to set down a little of the weight she had been carrying.</p></div>\n<div><p>“But if you're still worried, just keep a close eye on the situation for me,” I added. “If Kushida still hasn't received any tokens by the end of the third day, or going into the final day, I'll step in and contact Horikita myself. After all, if Shinohara finds out you were the one who tipped her off, she might end up holding a grudge against you instead.”</p></div>\n<div><p>“...You're really willing to help?”</p></div>\n<div><p>“If we want Group 3 to take first place, we'll need the cooperation of every class,” I replied. “The order in which we cross the finish line on the final day has a massive impact on our score multiplier. I don't know the precise rules yet, but there's no guarantee we'll win if we're carrying around a powder keg like this.”</p></div>\n<div><p>When I told her that, Mii-chan bowed her head deeply. “Thank you so much...!”</p></div>\n<div><p>“More importantly, you should probably head back now,” I cautioned. “It'll be a hassle if Shinohara and the others spot us together.”</p></div>\n<div><p>Giving a small, earnest nod, Mii-chan hurriedly jogged off. She nearly tripped over her own feet in her haste, but she managed to slip away, successfully putting enough distance between us before Shinohara's group ever noticed she was gone.</p></div>\n<div><p>“Pray tell, what mysterious matters were you whispering about just now, Ayanokōji Kiyotaka?”</p></div>\n<div><p>Appearing beside me seemingly out of nowhere, Morishita leaned in with her sudden question.</p></div>\n<div><p>“Looks like you've recovered your stamina,” I noted.</p></div>\n<div><p>“Pardon? Whatever do you mean? My boundless energy is simply overflowing in an endless fountain of vitality, you know?”</p></div>\n<div><p><em>Perhaps her panting heavily just a few minutes ago had merely been an optical illusion.</em></p></div>\n<div><p>I decided not to press the issue any further.</p></div>\n<div><p>And so, the quiet dissonance brewing within Class A was steadily beginning to take root.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>After completing several more Individual and Team category tasks, with lunch and a longer break in between, we followed our supervisor’s instructions and made our way toward B7.</p></div>\n<div><p>As we ventured deeper into the forest the dense canopy overhead gradually swallowed the sunlight, casting the area into a dim greenish gloom. Cut off from the breeze, the humidity clinging to our bodies felt even more oppressive.</p></div>\n<div><p>The ground beneath our feet was soft, mixed with patches of deep mud, giving us the constant, dreadful sensation of our feet sinking into the earth.</p></div>\n<div><p>Exhausted from the relentless string of tasks, the students' footsteps were heavy and sluggish across the board.</p></div>\n<div><p>Everyone unconsciously shortened their strides, trying to conserve whatever stamina they had left.</p></div>\n<div><p>This was especially noticeable with Morishita. Her shoulders drooped as she tried to maintain a steady rhythm, but her breathing had begun to falter slightly.</p></div>\n<div><p>“What in the world is going on...? Are we seriously still not there yet...?”</p></div>\n<div><p>“They're literal demons!” Ike groaned, his voice carrying the same exhaustion he was clearly unable to hide. “Do they have any idea how much we've been walking around these past few days?!”</p></div>\n<div><p>Shinohara glanced sideways at him, offered a few words of comfort, and slowed her pace to match his. She did not say much, but fatigue was clearly visible on her face as well. Even so, she did not stop walking. She was probably conscious of not falling behind the others.</p></div>\n<div><p>In stark contrast, Katsuragi remained completely unfazed. He walked at a steady, consistent pace, with a perfectly straight posture. It wasn't as though he was free of fatigue, but he didn't show any of it on the surface, simply keeping his eyes fixed dead ahead as he continued walking. His efficient, waste-free movements likely helped suppress unnecessary stamina loss.</p></div>\n<div><p>Ibuki walked a little behind him, wearing an expression of complete boredom.</p></div>\n<div><p>Her gaze wasn't fixed on her feet or straight ahead; instead, she seemed to be staring blankly off into space. She walked while occasionally kicking a loose pebble, using the small motion to distract herself from the faint irritation simmering inside her.</p></div>\n<div><p>A considerable number of assignments had been thrown at us over the course of the day, but to put it plainly, Ibuki’s results had been extremely poor.</p></div>\n<div><p>At the start, the number of tokens she held had probably been almost the same as mine. Now, though, there was no need to check the exact figures. Within Group 3 as a whole, she was competing with Kushida for last place.</p></div>\n<div><p>So far, Katsuragi had shown no signs of leniency.</p></div>\n<div><p>There was probably a deliberate reason for that. By being strict with Ibuki, he may have been trying to force her to produce results. But that was only one side of it. The more immediate reality was that he simply had not secured enough surplus tokens to spare any for her.</p></div>\n<div><p>When it came to contests of academic ability, the advantage inevitably went to the other classes. No matter how many assignments we cleared, the more we completed, the more the gap between us and them would gradually widen. And even in physical contests, the one area where Ibuki should have had her chance to shine, luck had not been on her side. There had been cases where the teammates she was paired with dragged her down, and other times when she had the misfortune of running into me in succession.</p></div>\n<div><p>There was no way she could possibly find this situation amusing.</p></div>\n<div><p>A thin veil of light slipped through the gaps between the trees, faintly illuminating the path ahead. Our destination was still nowhere to be seen. Conversations had dwindled until only the sound of footsteps remained, falling into a steady, almost mechanical rhythm against the damp forest floor.</p></div>\n<div><p>Each of us continued forward in silence, confronting our own exhaustion in our own way.</p></div>\n<div><p><em>What exactly was waiting beyond the forest?</em></p></div>\n<div><p>No one had the room to think about it, let alone confirm it. We simply kept moving our feet, one step after another, as though our bodies had been reduced to that single repeated motion.</p></div>\n<div><p>Suddenly, the supervisor leading the way slowed his pace. He didn't come to a complete stop, but he did glance back over his shoulder, his eyes sweeping across our entire formation.</p></div>\n<div><p>After a few more steps, he called out in a clipped voice.</p></div>\n<div><p>“Kushida-san, there's an incoming call for you over the radio. Can you take it?”</p></div>\n<div><p>Kushida gave a small jolt the moment she was called out by name.</p></div>\n<div><p>“Me?”</p></div>\n<div><p>The faint tilt of her head was natural enough, but there was a distinct hint of caution laced in her voice. It was the first external contact we had received since the exam began, so her wariness was perfectly understandable.</p></div>\n<div><p>The supervisor offered no further explanation, simply gesturing lightly to the device in his hand.</p></div>\n<div><p>Kushida looked around once, then quickly complied without breaking her pace. She reached out, accepting the radio from the supervisor, and placed the small earpiece into her ear.</p></div>\n<div><p>Shinohara and the others stared at her intently, wondering what was going on.</p></div>\n<div><p>After a few moments of nodding to whatever was being said through the earpiece, Kushida exhaled softly and spoke.</p></div>\n<div><p>“It seems to be Horikita-san.”</p></div>\n<div><p>With that single sentence, the air around us shifted.</p></div>\n<div><p>She had kept her voice low, but it was loud enough to be easily heard by anyone standing nearby.</p></div>\n<div><p>A contact from outside the group, and from Horikita no less, was unlikely to be some mere routine work.</p></div>\n<div><p>From where we were, there was no point in trying to eavesdrop on the radio itself. Whatever came through the receiver would belong to Kushida alone. Her own voice, however, was another matter. If someone wanted to listen, it would not be impossible to catch what she said.</p></div>\n<div><p>Because of that, the gazes around her naturally began to gather.</p></div>\n<div><p>The first to move were the three students from Class A.</p></div>\n<div><p>As Kushida separated from the supervisor, they adjusted their positions and began walking around her, forming a loose screen. At the same time, they kept watch, making sure no one tried to come too close.</p></div>\n<div><p>There were no explicit rules stating we couldn't approach, but it was an unspoken agreement. Maintaining our distance now would make it easier to demand that same level of privacy when we inevitably needed it for ourselves.</p></div>\n<div><p>Katsuragi and I issued quiet instructions almost at the same time and moved toward the front. A moment later, the students from Class D also began putting distance between themselves and Kushida’s group.</p></div>\n<div><p>As I walked ahead, I cast a quick glance over my shoulder.</p></div>\n<div><p>Shinohara was walking beside Kushida, and the expression on her face held a different shade from before.</p></div>\n<div><p>The faintest hint of irritation.</p></div>\n<div><p>The fact that Horikita had called Kushida, not her.</p></div>\n<div><p>During the Unanimous Special Exam, Kushida had revealed her true nature and placed the class in danger. Her credibility had fallen visibly after that, as had her standing within the class’s internal hierarchy.</p></div>\n<div><p>And yet, despite all of that, Horikita had contacted Kushida first.</p></div>\n<div><p>For Shinohara, those two facts were becoming a source of invisible stress, quietly eating away at her from within.</p></div>\n<div><p>On top of that, there was a faint trace of anxiety. If Kushida reported Shinohara’s petty behavior as a representative to Horikita, a reprimand would almost certainly follow. While I couldn't be absolutely certain, with Shinohara hovering right over her, Kushida likely wouldn't do that.</p></div>\n<div><p>After all, in the eyes of those around her, Kushida was not the kind of bad girl who would go around voicing complaints.</p></div>\n<div><p>Even so, a different kind of silence from the one we had been carrying earlier had undoubtedly fallen over the group.</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>We had crossed into Area C9, our destination finally within reach, when the supervisor stopped in his tracks and turned to face us.</p></div>\n<div><p>“If we proceed at this pace, I think we'll cross into Area B7 in about fifteen to twenty minutes,” he announced. “We're almost there, so hang in there just a little longer.”</p></div>\n<div><p>Receiving those words of encouragement, a few students offered weary murmurs of acknowledgment before we resumed our grueling march.</p></div>\n<div><p>Not long after, a burst of noise reached us from somewhere nearby; voices, footsteps, the faint disorder of another group in motion. A moment later, the first figure to come into view was another sweat-drenched supervisor, walking at the head of the formation. And behind him came Group 6.</p></div>\n<div><p>The supervisor assigned to Group 6 approached Urushihara almost immediately, and the two exchanged a few brief words.</p></div>\n<div><p>On the afternoon of the exam's second day, this marked our first genuine encounter with another group.</p></div>\n<div><p>Among the Class C students assigned to Group 6 were Kitō, Yamamura, Satonaka, and Machida. From the look of them, they had also covered a considerable distance. Fatigue clung visibly to many of the students, weighing down their shoulders and slowing their steps.</p></div>\n<div><p>While many students likely felt a flicker of relief at seeing fresh faces, a seed of suspicion no doubt took root alongside it.</p></div>\n<div><p>“Please rest assured, everyone,” Urushihara called out. “We simply happened to cross paths. There are no inter-group tasks scheduled for today.”</p></div>\n<div><p>With that single announcement, the tension in the air dissipated. The students' underlying suspicions had fortunately been off the mark. With the reassurance that this was nothing more than a chance encounter, they dropped their guard, and tentative smiles slowly began to spread across their faces.</p></div>\n<div><p>“It appears Group 6 is heading to Area B8, so you're welcome to travel together for the time being,” he continued. “There's no issue with you chatting or exchanging tokens if necessary. Please, feel free to do as you like.”</p></div>\n<div><p>That permission was all it took.</p></div>\n<div><p>Students from the other classes began moving toward one another, closing the distance quickly. Questions were exchanged almost at once. <em>How was your group doing? Were you managing to collect tokens? </em>A little later, the Class C students; Satonaka, Machida, and Yamamura, also approached us.</p></div>\n<div><p>“You guys holding up alright with the tasks?” Yoshida asked, casually opening with some small talk.</p></div>\n<div><p>Machida gave a noncommittal nod. “We're barely scraping by right now. It's hard to tell exactly how much everyone else is earning. Would it be faster if we just showed you our tokens?”</p></div>\n<div><p>His gaze shifted to me for approval, so I quickly shot the idea down.</p></div>\n<div><p>“No, that won't be necessary. Right now, instead of worrying about where we stand, it's better to focus entirely on gathering as many tokens as possible, even if it's just one more.”</p></div>\n<div><p>“You might be right…” Machida admitted. “But honestly, I'd be lying if I said I wasn't anxious.”</p></div>\n<div><p>“You can rest easy,” I assured him. “I've already decided on a strategy for how we'll survive this Special Exam. Right now, we're just waiting for the right moment to put it into action. I have no intention of letting anyone from Class C get expelled. When the time comes for detailed instructions, I'll definitely contact you over the radio.”</p></div>\n<div><p>Leaving the rest of the intra-class chatter to Yoshida and Sanada, I shifted my focus beyond our class.</p></div>\n<div><p>My primary concern right now was Class B's movements. Katsuragi was already at the center of a discussion, where the events and developments within Group 3 over the past day would undoubtedly be shared in meticulous detail.</p></div>\n<div><p>He would pass on any information he could without relying on the radio, such as exactly how many visible tokens I currently held.</p></div>\n<div><p>I knew it wouldn't be long before that intel reached Ryuen's ears, prompting him to formulate his countermeasures.</p></div>\n<div><p>There was no need to rush, I will just proceed with the strategy as planned───</p></div>\n<div><p>“Hey, Ayanokōji-kun...“</p></div>\n<div><p>The voice came hesitantly from beside me.</p></div>\n<div><p>“Do you have a minute?”</p></div>\n<div><p>It was Hasebe from Class A. When I glanced past her, the other Class A students were gathered a short distance away, smiling and talking with Kushida at the center of the group. Hasebe’s departure from them had not drawn any particular attention. At least for the moment, no one seemed to be watching us closely.</p></div>\n<div><p>“Let's walk a bit slower,” I suggested.</p></div>\n<div><p>“Yeah, thanks.”</p></div>\n<div><p>We hung back to let the other students move ahead, then stepped off the main path toward the nearby beach, staying just close enough to keep the trail in sight. The sound of footsteps and conversation thinned behind us, replaced by the dry rush of wind and the steady breeze of the sea.</p></div>\n<div><p>Spotting a large rock nearby, I had Hasebe take a seat to keep her from burning through any more of her stamina.</p></div>\n<div><p>“How are your legs holding up?” I asked. “You must be burning through a lot of energy too with the endless hiking and tasks.”</p></div>\n<div><p>“Yeah, I'm managing,” she replied. “What about you, Ayanokōji-kun? Are you... actually, never mind. I doubt I need to worry about you.”</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_ch5.webp\"><span></span></div>\n<div><p>“I'm doing well enough in my own way,” I said. “How are things on your end?”</p></div>\n<div><p>“I'm not really sure. It’s hard to say without knowing how the other groups are doing, but I think we’re holding our own well enough.”</p></div>\n<div><p>It seemed that, for now at least, neither Hasebe nor the rest of the Class A students were feeling overly anxious.</p></div>\n<div><p>A stronger sea breeze swept across the shore.</p></div>\n<div><p>Hasebe narrowed her eyes against it and turned her gaze toward the water, where the sunlight scattered in countless bright fragments across the surface.</p></div>\n<div><p>“Do you feel guilty?” I asked.</p></div>\n<div><p>At my question, she turned back to face me, pausing for a moment in quiet contemplation.</p></div>\n<div><p>“If I said I didn’t feel any guilt at all,” she said at last, “that would be a lie…”</p></div>\n<div><p>With that preface out of the way, she continued. “But it's better than seeing you get expelled, Ayanokōji-kun. That's what I told myself... so I can honestly say I don't have any regrets. Was my advice helpful?”</p></div>\n<div><p>“Yeah, pretty much. Thanks to you, I managed to avoid taking the fall and getting expelled.”</p></div>\n<div><p>“I see. I'm glad.”</p></div>\n<div><p>It wasn't a forced smile; it was a genuine expression that Hasebe showed from the bottom of her heart.</p></div>\n<div><p>“Can I... you know, um... go back to calling you Kiyopon...?”</p></div>\n<div><p>“You really fixate on the strangest things,” I noted. “I don't mind, if that's what you prefer.”</p></div>\n<div><p>“...I'm glad. For me, using that nickname is kind of like a barometer, I guess? It just makes me feel a certain way... probably. Ugh, I don't know. What am I even saying?”</p></div>\n<div><p>She let out a self-deprecating laugh, fully aware her words were turning into a jumbled mess.</p></div>\n<div><p>“Once this uninhabited island exam is over and we're back at school, we should hang out over summer break,” she suggested.</p></div>\n<div><p>“I highly doubt Miyake or Yukimura would welcome that.”</p></div>\n<div><p>“Oh, right. I guess so. Then it can just be the two of us... ah, I mean, just for starters, you know?”</p></div>\n<div><p>“Alright. Just let me know whenever.”</p></div>\n<div><p>Seeing that I hadn't rejected her, but instead agreed without a second's hesitation, Hasebe broke into a genuinely delighted smile.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>It was half past six in the evening.</p></div>\n<div><p>The campsite for the second day had been fixed at B7, and no sooner had the decision been made the students began moving with practiced efficiency. Packs were lowered, tools were brought out, and the quiet rhythm of preparation spread through the site.</p></div>\n<div><p>Back when we were first-years, pitching a base camp had been an agonizing struggle. Now, regardless of whether they were boys or girls, it was something they had all grown incredibly well-accustomed to.</p></div>\n<div><p>“Their movements are finally starting to look the part, aren't they?” Morishita said, folding her arms with an air of authority. “If you ask me, they still have a long way to go, but I suppose I should offer some praise for achieving this much as mere high school students.”</p></div>\n<div><p>A rather bold stance for someone who had done absolutely nothing but watch since day one.</p></div>\n<div><p>“Ayanokōji-kun, you have an incoming radio call. It's from Nishikawa-san in your class. Can you take it?”</p></div>\n<div><p>The supervisor walked over relaying the message as he extended a two-way radio in my direction.</p></div>\n<div><p>I accepted it immediately and slipped the earpiece into place.</p></div>\n<div><p>“Could it be some sort of trouble?” Morishita mused aloud. “How bothersome.”</p></div>\n<div><p>“Sorry, but could you get the fire started in my place?” I asked.</p></div>\n<div><p>“Eeek.”</p></div>\n<div><p>I engaged the safety lock on the utility lighter and handed it over to Morishita, who had made a small joke (I guess?) with an expressionless face.</p></div>\n<div><p>“Well, just leave it to me,” Morishita said solemnly. “I'll make sure Ayanokōji Kiyotaka's bed is reduced to ashes.”</p></div>\n<div><p>“That would almost certainly result in expulsion, so please take this seriously.”</p></div>\n<div><p>I was slightly concerned, but I couldn't afford to keep Nishikawa waiting. Deciding to put my faith in her, I left the lighter in Morishita's hands.</p></div>\n<div><p>“Sorry for the wait.”</p></div>\n<div><p>The moment I responded, Nishikawa launched right in, her tone brimming with her usual energy.</p></div>\n<div><p>“Yahoo, Ayanokōji-kun. Do you have a second? There's something I wanted to get your advice on.”</p></div>\n<div><p><em>Advice? Did something happen?</em></p></div>\n<div><p>“What is it?”</p></div>\n<div><p>“I was just getting a little worried about the token counts for the other groups. Aren't you worried, Ayanokōji-kun?”</p></div>\n<div><p>“Of course it's on my mind. I'm especially concerned about Shiraishi and the others who ended up in Ryūen's group. Under normal circumstances, I don't think they'd make a mistake that would wipe out their tokens, but in this case, even that isn't a guarantee.”</p></div>\n<div><p>The possibility that they could fall into some sort of trap and hit zero, even if only for a fleeting moment, couldn't be completely ruled out.</p></div>\n<div><p>“Even if they haven't hit zero, someone might be struggling because they're dangerously close to it.”</p></div>\n<div><p>“Is there a specific student you're worried about?”</p></div>\n<div><p>Her tone practically gave the answer away, but I deliberately feigned ignorance.</p></div>\n<div><p>“I want to know how Asuka is doing.”</p></div>\n<div><p>Perhaps sensing I had seen right through her, Nishikawa dropped the pretense and got straight to the point. She must have been harboring the same concerns I had since early on.</p></div>\n<div><p>To find out a specific person's exact token count, the only surefire methods were to make direct physical contact or call them on the radio. The former relied heavily on luck, while the latter cost precious tokens. Neither was a simple matter.</p></div>\n<div><p>“Wouldn't calling Shiraishi directly solve your problem?” I asked.</p></div>\n<div><p>“She's a kind girl. Even if she were in trouble, I feel like she'd hide the truth from me. But since you're the class leader, Ayanokōji-kun, I think she'd answer you honestly.”</p></div>\n<div><p>“I see. It's true that the only way to confirm her exact tokens without meeting in person is over the radio. Unfortunately, I have no intention of wasting a token just for that. I don't approve of how you're using the radio right now, either.”</p></div>\n<div><p>“...But what if she really is in trouble?”</p></div>\n<div><p>I had laced my words with a hint of reprimand, but Nishikawa's voice remained completely unfazed.</p></div>\n<div><p>“She might be desperately hoping for help,” she added.</p></div>\n<div><p>“You really don't want to see Shiraishi expelled, do you?”</p></div>\n<div><p>“Of course I don't. She's a dear friend of mine.”</p></div>\n<div><p>“That may be true. But plenty of other students share those exact same feelings and relationships. ‘I don't want him to be expelled,’ or ‘I want to protect her’— you aren't the only one who thinks that way, Nishikawa.”</p></div>\n<div><p>“That's why I came to you for advice,” she said. “Honestly, I'm perfectly willing to use my own tokens to contact her. But it might end up being a waste, and more importantly, I don't want to disrupt the class's harmony. That's why I'm asking.”</p></div>\n<div><p>“So, if I tell you ‘no’ right now, will you obediently hold back?”</p></div>\n<div><p>“I wonder about that…”</p></div>\n<div><p>Perhaps Nishikawa also understood what my answer would be, as she muttered evasively but with a hint of irritation.</p></div>\n<div><p>“How you use your personal tokens is up to you. If you absolutely must know how Shiraishi is doing, I have no right to stop you. However, confirming her token count now will only buy you a fleeting moment of peace of mind. In fact, if you find out she really is struggling, it will only fuel your anxiety.”</p></div>\n<div><p>If that happened, she would inevitably use the radio to contact Shiraishi again a few hours later, wasting even more tokens. Her focus on the exam would fracture, leading to a drop in efficiency. Factoring that in, even if Shiraishi were to inflate her token count to reassure her, she certainly wouldn't under-report it.</p></div>\n<div><p>“Shiraishi is highly capable. Don't you think the odds of her falling to last place are quite low right now?” I asked.</p></div>\n<div><p>“I won't deny that. But there are no absolute guarantees, right?”</p></div>\n<div><p>“I suppose it depends on who she's up against.”</p></div>\n<div><p>“If she only has a few tokens left, I have to do something.”</p></div>\n<div><p>“Are you prepared to protect her even if it means sacrificing yourself?”</p></div>\n<div><p>“No way, that's impossible. It wouldn't mean anything if Asuka gets to stay at this school but I get expelled,” Nishikawa answered without hesitation. “However, if it means protecting Asuka, I don't care if someone else has to be the sacrifice.”</p></div>\n<div><p>“Are you saying that, in a worst-case scenario, I should sacrifice someone other than you or Shiraishi?”</p></div>\n<div><p>“Exactly. That's precisely why we made you the leader, Ayanokōji-kun. Because I believe you're capable of making ruthless decisions for us.”</p></div>\n<div><p>It seemed Nishikawa's little ‘consultation’ carried far more weight than I had originally anticipated.</p></div>\n<div><p>“Sorry, but I have my own way of doing things.”</p></div>\n<div><p>“Are you saying... you won't help her?”</p></div>\n<div><p>“My role isn't to decide whether or not to save Shiraishi. It's to ensure we never end up in a situation where we have to make that kind of binary choice in the first place.”</p></div>\n<div><p>“That's reassuring,” Nishikawa said. “But doesn't that also mean if push comes to shove, we have no idea what kind of decision you'll actually make?”</p></div>\n<div><p>“If you can't trust me, then you'll just have to handle it yourself. If you manage to earn more tokens than anyone else, there's a chance you could save Shiraishi entirely on your own.”</p></div>\n<div><p>“Hey, Ayanokōji-kun. You don't actually think our class doesn't matter, do you? Because if you're secretly a spy for Class A, that really wouldn't be funny.”</p></div>\n<div><p>With a cold, accusatory tone, she mercilessly stabbed the words into me.</p></div>\n<div><p>“I won't say it's too late to be bringing that up now,” I replied. “I know it will take time to earn everyone's understanding.”</p></div>\n<div><p>“I guess so. I just can't place my complete trust in you yet. So, if you want me to get to that point, cooperate with me. Contact Asuka.”</p></div>\n<div><p>“I have no intention of repeating myself.”</p></div>\n<div><p>“Right... That's a shame, but it looks like we're out of time. I'll hold back for today, but I’ll make no promises about tomorrow.”</p></div>\n<div><p>Saying that, Nishikawa ended the call.</p></div>\n<div><p>“Thank you,” I said as I handed the radio back to the supervisor.</p></div>\n<div><p>I turned my eyes toward Morishita at once, who was supposed to be busy setting up the fire.</p></div>\n<div><p>“What exactly are you doing?”</p></div>\n<div><p>“Eeek.”</p></div>\n<div><p>“No, never mind that.”</p></div>\n<div><p>Instead of holding the ignition lighter I had just given her, Morishita was crouching on the ground, drawing a picture in the dirt.</p></div>\n<div><p>“I thought I'd leave behind a dying message,” she said. “It's a sketch of the culprit.”</p></div>\n<div><p>“I have no idea who that's supposed to be, but more importantly, I’m fairly certain I asked you to start the fire.”</p></div>\n<div><p>“Oh, details like that hardly matter,” Morishita replied, “It will be all the same if Ayanokōji Kiyotaka does it now. Please, feel free to burn it to your heart’s content.”</p></div>\n<div><p>Saying that, she lifted her foot, picked up the lighter she had been stepping on, and held it out to me: the nozzle pointed directly at my face. Much like a pair of scissors, common sense dictated handling these tools over in a way that posed no danger to the recipient, but she clearly didn't care. To make matters worse, her finger was resting right on the lever.</p></div>\n<div><p>Just as I reluctantly reached out to take it, she suddenly squeezed the trigger, attempting to ignite it right in my face.</p></div>\n<div><p>However, nothing happened..</p></div>\n<div><p>“A misfire?!” she gasped.</p></div>\n<div><p>Naturally, it didn't ignite. I had engaged the safety lock before handing it to her.</p></div>\n<div><p>“You're a dangerous person, you know that?”</p></div>\n<div><p>“It was a joke, of course,” she replied. “I knew the lock was on; I merely wanted to give you a fright.”</p></div>\n<div><p>“Knowing the lock is on doesn't excuse trying to ignite a lighter while pointing it at someone.”</p></div>\n<div><p>“More importantly,” Morishita said, brushing past that point with no sign of reflection, “what were you discussing with Ryōko Nishikawa?”</p></div>\n<div><p>“She said she was worried about Shiraishi and wanted me to check on her. When I refused, she accused me of being a spy for Class A.”</p></div>\n<div><p>“Oho. A rather sharp observation, coming from her. I must admit, I was just beginning to harbor that very same suspicion once again myself. The ‘Ayanokōji Kiyotaka is a Class A Spy’ theory.”</p></div>\n<div><p>“Is that so?”</p></div>\n<div><p>“Watching you up close these past two days, I can't help but feel like you've been particularly preoccupied with Kushida Kikyō. It certainly seems to go far beyond simply worrying about a former classmate.”</p></div>\n<div><p>\"I see. So it looks that way even from an outside perspective?\"</p></div>\n<div><p>\"It certainly does. Or rather, that ‘even’ is practically a confession! You just said, ‘even from the outside.’ I caught that!”</p></div>\n<div><p>She flashed me a smug little grin, looking exactly like a detective who had just backed a criminal into a corner.</p></div>\n<div><p>\"It's true that Kushida Kikyō appears to be quite capable in her own right,” Morishita continued. “But even so, you two have been a bit too close. To the point where I'm honestly startin' to think, ‘Are ya actually in love with her or somethin', yo?’”</p></div>\n<div><p>Why did she suddenly switch to a casual tone? Or rather, why does she sound like a total delinquent now?</p></div>\n<div><p>“Let me ask you something. Even if that were the case, would it cause any problems?” I asked.</p></div>\n<div><p>“Let me ask you this in return: do you honestly think it wouldn't?”</p></div>\n<div><p>“Anyone can see that Kushida is an exceptional student,” I said. “Even you can't deny that. Therefore, there's no doubt that she's the most suitable person to keep this group running smoothly. The presence or absence of romantic feelings is completely irrelevant.”</p></div>\n<div><p>“If you desire an exceptional student, why not your classmate Sanada so-and-so, or Katsuragi so-and-so? There's no need to limit it exclusively to Kushida Kikyō, is there?”</p></div>\n<div><p>“We were in the same class for two years. I have a much clearer understanding of Kushida's capabilities.”</p></div>\n<div><p>“Because she's a former classmate, you say? My, my, how very suspicious. The plot thickens. It almost sounds like you'd swoop in and protect her from Shinohara so-and-so and her friends if push comes to shove. Let me be perfectly clear: I will not give you a single one of my tokens, you thief.”</p></div>\n<div><p>I had already settled today’s portion properly, but it seemed likely she would continue pressing me on the details from tomorrow onward.</p></div>\n<div><p>“Interpret it however you like.”</p></div>\n<div><p>“Well, rest assured, I won't get angry at you for looking at Kushida Kikyō through rose-tinted glasses and playing favorites. Because as long as I am kept safe, I'm perfectly willing to turn a blind eye to it. Therefore, please make absolutely sure to prioritize me over Sanada so-and-so and Yoshida so-and-so.”</p></div>\n<div><p>So, in the end, all that mattered to Morishita was that her own safety was guaranteed.</p></div>\n<div><p>“Even so, you sure use ‘so-and-so’ a lot. I've been pondering this for a while now, but if you don't know their given names, there's no need to force yourself to use their full names, is there?”</p></div>\n<div><p>“Then allow me to ask you this,” Morishita said. “What would you do if there were thirty people in the class with the surname Yamada? If you called out, ‘Hey, you there, Yamada,’ thirty boys and girls would all turn around at once. It would be absolute chaos! Surely it would be more convenient to know whether one meant Yamada Jirō or Yamada Hanako?”</p></div>\n<div><p>While Yamada is certainly a common surname, it wasn't exactly the most populous in the country. A scenario where thirty people in the same class shared the exact same surname was practically unthinkable anyway.</p></div>\n<div><p>It had been quite some time since I first met Morishita, but I still couldn't figure her out.</p></div>\n<div><p>“Ayanokōji, come here a sec.”</p></div>\n<div><p>Yoshida raised his voice and beckoned me over. A shadow had fallen over his expression, leading me to suspect that, right on the heels of my conversation with Nishikawa, yet another problem had cropped up.</p></div>\n<div><p>“Let's go, Morishita,” I said.</p></div>\n<div><p>“No, thank you,” Morishita replied at once. “It may be a troublesome matter, and I would prefer to avoid such things. I shall remain here and light the fire. Please lend that to me.”</p></div>\n<div><p>With that, she snatched the lighter right out of my hand.</p></div>\n<div><p>Leaving her in charge of the fire felt incredibly risky, but I decided to put my faith in her just this once. Then I hurried over to Yoshida to hear what was going on.</p></div>\n<div><p>“I don't really want to stick my nose in other people's business, but Shinohara is seriously crossing a line,” he muttered gesturing vaguely with his chin toward the members of Class A, who were huddled together in a tight group. “It looks like she distributed tokens to Wang and Ike, but Kushida hasn't been given a single one.”</p></div>\n<div><p>“Kushida hasn't? Why?” I asked.</p></div>\n<div><p>It appeared that Class A's internal drama, which was supposed to be kept under wraps, had already leaked. Whether Shinohara had let it slip, Kushida had skillfully orchestrated the leak, or it had come from an entirely different source altogether, I couldn't be sure. Regardless, there was no point in trying to track down the culprit now.</p></div>\n<div><p>A short distance away, Katsuragi and several Class D students who had evidently caught wind of the rumor were already approaching Class A. An argument seemed to be breaking out, and I could already see the anger flashing across Shinohara's face.</p></div>\n<div><p>“We should probably head over there,” Yoshida said. He broke into a jog, and Sanada and I quickly followed suit.</p></div>\n<div><p>“You guys are here too? What the hell is going on?” Shinohara immediately directed her frustration at Yoshida before shooting a sharp glare in my direction.</p></div>\n<div><p>“I heard you aren't giving any tokens to Kushida,” Yoshida said. “Just because you're the representative doesn't mean you get to do whatever you want.”</p></div>\n<div><p>“...This has nothing to do with you, Yoshida-kun.” Shinohara shot back. “We in Class A have our own strategies we're desperately trying to figure out in order to win. I don't know if you eavesdropped or what, but mind your own business. Don't butt in when you're from another class.”</p></div>\n<div><p>Her counterargument was perfectly valid; under normal circumstances, this wasn't a matter Yoshida and the others had any right to interfere in.</p></div>\n<div><p>“But we're in a group together,” Yoshida argued. “Stop disrupting the harmony.”</p></div>\n<div><p>“Who's the one disrupting things here?” Shinohara demanded. “If we change our strategy because of you and end up losing, are you going to take responsibility for it?”</p></div>\n<div><p>“That's…”</p></div>\n<div><p>Faced with her forceful rebuttal, Yoshida faltered and took a step back. I, on the other hand, stepped forward, closing the distance between Shinohara and myself.</p></div>\n<div><p>“What?” she said, fixing me with a hard, unflinching stare. “Do you have something to complain about too, Ayanokōji-kun?”</p></div>\n<div><p>Her eyes held a stronger wariness toward me than they had toward Yoshida.</p></div>\n<div><p>“If Horikita were to find out about this,” I said. “Wouldn't your position be in a bit of jeopardy?”</p></div>\n<div><p>“Huh? Is that a threat?” She scoffed. “...This has nothing to do with you, Ayanokōji-kun.”</p></div>\n<div><p>“If this were a strategy meant to secure victory, I could understand it. But what you’re doing is letting your own self-preservation and personal resentment take priority.”</p></div>\n<div><p>“Satsuki ain't that kind of person! You just don't get her!”</p></div>\n<div><p>Stepping in to protect his girlfriend, Ike shoved himself right into my face. He was practically seething, radiating an intensity that made it seem like he might grab me by the collar at any second.</p></div>\n<div><p>Sonoda and Morofuji, who had been watching from farther away, seemed to notice the rising tension as well. Drawn by the commotion, they began moving toward us.</p></div>\n<div><p>“Perhaps you really are executing this as a legitimate strategy,” I said. “But to the people around you, it certainly doesn't look that way. It looks like you're abusing your authority as the representative to suppress and control someone more capable than yourself. It looks like, in a worst-case scenario, you're planning to save your own skin even if it means kicking Kushida down to do it.”</p></div>\n<div><p>“Are you kidding me? What's with these baseless accusations!” Shinohara snapped. “I became the representative for the sake of Class A, and I'm managing things so we can win. Stop making up stories based on your own warped speculation!”</p></div>\n<div><p>Ever since we had formed this group, a lingering grudge had festered between us. Naturally, confronting her with such a harsh rejection of her methods was bound to invite hostility.</p></div>\n<div><p>At this point, I shifted my gaze toward Katsuragi, who had been observing from the sidelines, and the two Class B students who had hurried over.</p></div>\n<div><p>“Since we're on the subject,” I continued, “I’ll say this as well. I have some doubts about Class B’s policy too. I’m not saying a performance-based reward system is inherently bad. But when it’s handled too openly, I can’t say I’m impressed.”</p></div>\n<div><p>Sonoda, clearly not expecting the sparks to fly his way, furrowed his brows in annoyance.</p></div>\n<div><p>“What the hell is that supposed to mean?” he said. “Another class has no business criticizing our policy. And I hate to put it this way, but especially not you.”</p></div>\n<div><p><em>A class traitor. </em>It was obvious they had no intention of taking advice from me, a person already at odds with Class A.</p></div>\n<div><p>“Yeah, exactly! This ain't something for an outsider to butt into, Ayanokōji!” Seizing the opportunity, Ike quickly sided with Sonoda, attempting to drag their representative into the fray. “Right, Katsuragi?”</p></div>\n<div><p>“It's true that it's none of his business. But the same goes for you and Class A, Ike,” Katsuragi replied heavily. Unable to stand being lumped into the same category as Shinohara, he made his dissatisfaction clear. “I am making judgments fairly in my own way, and distributing tokens among my three group members accordingly. But as Ayanokōji pointed out, Shinohara is controlling Class A's tokens entirely on a whim. That is not fair.”</p></div>\n<div><p>“No, no, it's completely different! Satsuki is managing things on our end so we don't lose. The strategy is to properly redistribute them at the right time. Were you even listening to the explanation?” Ike complained, as if to say, <em>And here I went out of my way to become your ally.</em></p></div>\n<div><p>“If that is truly the case, then you should conduct yourselves in a way that actually convinces Kushida of that.”</p></div>\n<div><p>At Katsuragi's words, Shinohara let out a mocking laugh.</p></div>\n<div><p>“Isn't that, like, the exact same for you, Katsuragi-kun? Can you confidently say Ibuki-san is completely convinced by your methods?”</p></div>\n<div><p>As evidenced by the fact that Ibuki was nowhere to be seen, it was safe to assume she was highly dissatisfied with Katsuragi's policies.</p></div>\n<div><p>“...Perhaps you are right.”</p></div>\n<div><p>Receiving Shinohara's unexpected counterattack, Katsuragi averted his gaze, patted Sonoda on the shoulder, and backed away.</p></div>\n<div><p>“There, see?” Ike said, raising his voice. “The rest of you, back off! Don’t get in our way!”</p></div>\n<div><p>At his words, the Class D students began to withdraw. Class C quickly followed as well.</p></div>\n<div><p>Within Group 3, irreversible misalignments in the gears had begun to steadily form due to the clashing policies of the representatives. On one side was Kushida, who was performing well enough but hadn't received a single token due to Shinohara's management. On the other was Ibuki, who was unable to perform as she wished and was thus drip-fed a meager amount of tokens.</p></div>\n<div><p>Of course, Kushida simply hadn't received her distribution yet, so her situation wasn't completely identical to Ibuki's. However, since her chances of receiving her fair share rested entirely in Shinohara's hands, the two girls were in remarkably similar positions when it came to their underlying anxiety.</p></div>\n<div><p>Without a doubt, within Group 3, those two were currently the prime candidates for last place.</p></div>\n<div><p>“What a wonderfully harmonious group we are.”</p></div>\n<div><p>As I looked over to find the source of the comment, I saw Morishita spectating from afar.</p></div>\n<div><p>The campfire still had not been lit.</p></div>\n<div><h2>Part 4</h2></div>\n<div><p>After a break filled with unrest, and after dinner had passed in much the same unsettled air, two more tasks were announced, just as they had been the previous day.</p></div>\n<div><p>The category was ‘Team’.</p></div>\n<div><p>In these tasks, Class A managed a respectable result of taking second place twice, but naturally, Shinohara showed no sign of handing any tokens over to Kushida.</p></div>\n<div><p>Though a faint look of anxiety occasionally surfaced on Kushida's face, she outwardly maintained the stance that she had complete faith in Shinohara.</p></div>\n<div><p>The student known as Kushida Kikyō was the type of person who was kind to everyone, perpetually cheerful, and deeply trusting of others. From the perspective of students in other classes, the impression she gave wasn't vastly different from Ichinose. Because of that carefully crafted image, she couldn't simply air her grievances in public and demand, ‘I can't trust you, Shinohara, so hand over my tokens.’</p></div>\n<div><p>That was precisely Shinohara's aim, and it seemed Kushida was being successfully taken advantage of.</p></div>\n<div><p>I walked over to where Class A was huddled together and called out to her.</p></div>\n<div><p>“I need to talk to you for a second.”</p></div>\n<div><p>“The hell do you want, Ayanokōji? What're you plotting?”</p></div>\n<div><p>Ike immediately jumped to his feet, stepping into my path as if to protect Kushida.</p></div>\n<div><p>More accurately, I figured he was doing it to prevent anyone from interfering with Shinohara's policies as the representative. However, far from pleasing his girlfriend, his aggressive posturing seemed to be having the exact opposite effect as Shinohara looked rather displeased with him.</p></div>\n<div><p>“I just came to talk to her as a fellow member of Group 3,” I said.</p></div>\n<div><p>“You think that excuse is gonna fly?” Ike shot back. “Sorry, but we don't trust you.”</p></div>\n<div><p>“I wasn't asking you, Ike,” I said, before walking past him. “Kushida, there are too many distractions here, so why don't we go somewhere else to talk?”</p></div>\n<div><p>At my invitation, Kushida slowly rose to her feet.</p></div>\n<div><p>“You can't go,” Shinohara warned her. “You know it'll look like an act of betrayal, right?”</p></div>\n<div><p>“It's fine, Satsuki, I won't let her go,” Ike said before turning toward Kushida, his tone softening at once. “Kikyō-chan, we're definitely not gonna treat you badly or anything, so you shouldn't get involved with Ayanokōji. We have no idea what he's scheming.”</p></div>\n<div><p>“It's okay, Ike-kun.” Kushida looked away from me, turning to offer him a gentle smile. “People have been saying all kinds of things, but I believe in everyone from Class A. I believe in you, Ike-kun.”</p></div>\n<div><p>Saying that, she shifted her gaze from Ike to Shinohara, then to Mii-chan, before looking back at Ike once more.</p></div>\n<div><p>“You especially have been looking out for me this whole time. I’m really grateful for that.”</p></div>\n<div><p>“R-Really?” Ike’s expression loosened. “Well, I mean, it's only natural since we're allies.”</p></div>\n<div><p>He chuckled, lightly rubbing a finger under his nose in a bashful display. However, upon noticing Shinohara glaring daggers at him, he immediately snapped back into a serious expression.</p></div>\n<div><p>“So, I'm sorry, but I can't go with you, Ayanokōji-kun,” Kushida said to me.</p></div>\n<div><p>Mouthing the words <em>‘Serves you right’ </em>from an angle where Shinohara couldn't see his face, Ike shooed me away.</p></div>\n<div><p>“Looks like you got rejected pretty harshly,” Yoshida laughed teasingly, having watched the exchange from near the tents.</p></div>\n<div><p>“It's only natural for Class A to be wary of you, Ayanokōji-kun,” Sanada added. “Even if I were in their position, I imagine I would have handled it similarly. Though, I wouldn't have been so hostile about it, of course.”</p></div>\n<div><p>“But why are you so concerned about Kushida?” Yoshida asked. “I mean, sure, I feel bad for her, but like they just said, it's not really something another class should be sticking their nose into.”</p></div>\n<div><p>“I just can't leave her alone,” I replied.</p></div>\n<div><p>“Wait...” Yoshida’s eyes narrowed slightly. “Don’t tell me…”</p></div>\n<div><p>“Have you finally noticed?” Morishita chimed in. “It seems our dear Ayanokōji Kiyotaka harbors simply extraordinary feelings for her.”</p></div>\n<div><p>“Oh, man,” Yoshida said, pressing a hand to his forehead.</p></div>\n<div><p>Without giving an answer to the two of them as they got worked up over their own assumptions, I stepped away and headed into my tent ahead of them.</p></div>\n<div><p>Not only Shinohara and Ike, but Yoshida and the others had now thoroughly taken note of my unusual behavior.</p></div>\n<div><p>That was a major gain for me.</p></div>\n<div><p>Ibuki and Kushida. The candidates I intended to have expelled from this school.</p></div>\n<div><p>By the day after tomorrow, their fates would be sealed.</p></div>"
};
